window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_020"]={"n":"洪繻","dyn":"清","poems":[{"t":"帝京篇","f":"楚辞体","c":["环山负海金汤城，蓊葱佳气连五陵。","阊阖天扉洞然訇，冕旒玉璪真人升。","真人旄钺森崒嵂，虎贲貂蝉侍从出。","屏藩贡使竞拜呼，帷幄重臣参密勿。","甲仗千群出校场，星躔雾旆过长杨。","铁驷神军铜鼓队，佽飞骑士羽林郎。","平生不到帝京路，想见帝京磐石固。","阿房五丈绣旗风，金人十二铜盘露。","帝京崔巍不可名，海若山灵为拱护。","控制寰中朝四夷，隆隆王气曾几时。","校猎犹存票骑部，宿卫犹用阴山儿。","犹忆将军逾雪岭，犹闻戈舰下昆池。","岂道盛衰争一瞬，周游无复穆王骏。","穆王一去昆崙邱，昭王不复汉水舟。","九鼎重轻得轻问，观兵直望周京留。","伊昔太平称全盛，胡越天骄奉吾令。","绝域殊方文教敷，远海重洋玉帛聘。","吾王有道九译通，重熙累洽闾阎庆。","旧事去今未百年，谁知强弱等天渊。","万里神州一线延，东西烽燧生狼烟。","无复铭功上耆连，无复扬威上楼船。","泥马铜驼足痛心，令人悲想云台贤。","可怜肉食无远图，欲施西学为典模。","不击祖生渡江楫，惟画王郎召鬼符。","翎飘孔雀项东珠，朝衣衮衮工步趋。","马前呼驺后除道，时平意气凌千夫。","去年妖氛风鹤警，争欲还山全首领。","老成不去运奇谋，割地求和称存郢。","吁嗟燕云壮士多，大风起兮今奈何。","长安落日无望处，京城如漆高峨峨。"]},{"t":"次韵梁任甫与林家诗","f":"七言古诗","c":["海民旧狎庚桑子，沧桑今作祝宗豕。","中有风尘肮脏人，埋头插脚颜常泚。","鳌沉已断地六维，鹑淫竟周星一纪。","仰叩苍苍阒不闻，独行踽踽歌靡恃。","勃苏复楚有未能，狐庸事吴不屑以。","将与轩皇备应龙，岂为蚩尤作工倕。","况他雨泽不霈施，使人炎火长秉畀。","虞候何止守薪蒸，崦嵫且遍徵砺砥。","哀嗷鸿雁无泽逃，取子鸱鸮有室毁。","钳余蟹足汝戏嬉，攘我牛田彼疆理。","警吏穿房长肆威，催科闯户且攘臂。","籍没田园不可堪，扰伤市狱更已矣。","保甲横施何足言，殴挞乱加尤莫比。","法律神明中外同，独至台湾法妄抵。","此间言论不自由，口尚须缄况敢指。","阜财无处挹南薰，嚼杀时来惊北鄙。","曩年屠戮焚山林，至今遍地生荆杞。","偶陈一二足心酸，欲说万千难口使。","有时种树实摇根，恰似从禽辄破觜。","我与蜣苏判薰莸，彼于燕虱殊悲喜。","方今海宇正纷争，衣裳溷在干戈里。","芦中有士徒激昂，朝右无人空诺唯。","方望十年或转移，不图两纪犹如此。","孰填冤石拔愚山，孰洒神灰止祸水。","东南裨海既已枯，西北漏天岂无圮。","不能轩舞愧庞然，每有跳梁输蕞尔。","朝鲜已入不羹封，越裳殆绝庭坚祀。","矧兹海岛土一拳，流沙黑水同司彘。","汉家既任珠崖沦，扶馀岂易虬髯起。","中土著鞭让人先，伊川被发哀吾始。","我生十载早埋尘，再坠劫中心早死。","既睹时艰足蒿目，每闻时事辄塞耳。","有怀中夜即抚膺，如跛寻履眇寻视。","能将东学心求真，岂觉西方法独美。","汉唐再世威万方，汤武一朝兴百里。","莫嗤邹衍幻天谈，不见种蠡湔国耻。","闻君有志欲兴华，君倘能行世能俟。","要知外学有金沙，须待吾人抉渣滓。","翘首东望海泱泱，富士山头峰齿齿。","一二畸人时往来，扶桑气到南溟紫。","我在柴桑采菊英，时哦楚骚搴泽芷。","门内无声地无尘，壁上有图床有史。","安得复遇素心人，閒把南华谈畏垒。"]},{"t":"登楼晚眺","f":"五言律诗","c":["暮色青山尽，寒天旷野低。","霜催归雁北，人在夕阳西。","云水帆无际，樵渔路已迷。","凭栏閒眺望，烟外草萋萋。"]},{"t":"有怀","f":"五言律诗","c":["人同流水逝，心似乱云飞。","草绿春迷路，花开昼掩扉。","江干逢杜若，天外惜芳菲。","鸿雁何时到，弹琴手自挥。"]},{"t":"咏古","f":"五言古诗","c":["驱车洛阳城，下马皋门道。","凭吊晋时人，胡尘净如扫。","昔者群氐狂，恶氛满苍昊。","臣庶供醢俎，帝王为舆皂。","倏忽无一存，乾坤旋再造。","夷吾彼何人，忧心空似捣。","不见祖生鞭，直向赵王堡。","于今缅遗踪，何处容夷獠。","伊水涧瀍间，秋色来浩浩。","遥望陆浑山，平原满秋草。","西楼六千里，东楼遥相望。","靺鞨何丑夷，夸毗称人皇。","中原凌替日，耀马中山阳。","后者居降邸，乃有东丹王。","雄猾阿保机，馀风何怆凉。","毡袍左衽人，车盖入大梁。","打草弃城走，惆怅登愁冈。","行人渡辽水，不见古临潢。","天祚百万兵，兵威忽不扬。","堂堂古雄国，早先弱宋亡。","悲风从东来，原野渺茫茫。","颓垣废宫殿，草低见牛羊。","走马游汴梁，出入汴城门。","哀哀啼杜宇，上有古帝魂。","虎狼群女真，南牧万马奔。","一鞭驱北去，八百赵王孙。","后日覆金族，乃仍青城屯。","妃嫔及王子，流血京城昏。","萧条上蔡州，黄伞投空村。","江南天水碧，犹有半壁存。","天兴靖康年，天道谁与论。","荒荒瓦砾中，白日惨不温。","登临陟华岱，沧海望洪波。","白云满天末，鸿鹄飞鸣过。","慨焉奇渥温，于此统山河。","中华群骁杰，俯首何其多。","运去蹈坎壈，时来生嵯峨。","濠阳淮泗间，跃马起横戈。","壮士挥返曜，英雄挽颓沱。","九州忽如砥，泰嵩不可磨。","何以乾坤毁，日月又蹉跎。","于今四海内，白狄舞傞傞。","大荒蹲犷獥，黑洋发蛟鼍。","自东欲徂西，乌兔相荡摩。"]},{"t":"喜施梅樵见过","f":"五言古诗","c":["春风满庭除，故人深夜至。","明月落空阶，霜痕白在地。","剪烛话骚诗，殷勤不能寐。","君今居近村，远与红尘避。","松风与鸟声，日以悦心志。","因之翰墨间，飘飘具高致。","五色纷满前，古音粲然备。","平生三数子，惟君得高寄。","褰涉鹿溪水，去来溪水清。","蓬门隔墟市，回车望高城。","青山二三里，流泉四五声。","相约载酒游，晚鸠啼春晴。","年来晤诗人，林君与君耳。","或多骛尘踪，巴歌沦下里。","扶轮彼何人，风雅自兹靡。","君昔少年时，鞶雕亦所喜。","中年忽有悟，清声追正始。","结庐山墅中，烟霞朝暮起。","日出众峰青，日落海波紫。","登眺极东西，云涛收笔底。","一别一相逢，惊余刮目视。","遵步得方涂，访君桃源里。","源水多蒹葭，水居多兰芷。","临风寂不发，相期道如砥。","韬晦丧乱馀，冥心谢时世。","高踪寡所谐，获君为深契。","所居山林间，阴晴互亏蔽。","葛天无怀民，柴桑尚苗裔。","穷巷馀落晖，衡门昼常闭。","君时一叩关，高谈发沉滞。","栗里有年华，晋秦非所计。","二豪一蜾虫，不堪供唾涕。","昨夕君来过，冥鸿忽即逝。","积冻在檐除，望风舒遐睇。","溪山两三重，衣裳愿再曳。"]},{"t":"早起望海","f":"五言古诗","c":["遥听洪涛声，不见波涛色。","茫茫大海中，榑桑陷深黑。","蛟龙出晦暝，鲸鳄上潮汐。","若木微影生，乌轮涌倾侧。","四山虽渐曙，大地犹未白。","东岭与西崖，阴阳互窟宅。","寒暑去来边，人间一驹隙。","黯淡悲河山，寥寥兴废迹。","我生处尘寰，亦一不速客。","俯仰古今人，怆焉流光掷。"]},{"t":"客有矜示铜雀瓦砚者赋此靳之","f":"古风","c":["呜呼，横槊奸雄骨已朽，铜雀虽存亦何有。","残瓴断甋更灰尘，文人好奇空宝守。","高台当日幸不倾，汉廷刀笔无公卿。","文举祢衡何处去，鹦鹉洲前恨不平。","老瞒空负文学名，祸人家国一老兵。","遗台废址堪作唾，鸲之鹆之辱眼睛。","吾家所好玉带生，不然五凤年砖亦怡情。","名人遗爱虽赝鼎，把玩犹胜饕餮觥。","闻说瓦出漳河底，百不一真欺墨史。","奸雄作伪无不为，后人一砚胡复尔。","当年作赋开邺宫，七子献颂争趋风。","岂知汉家成瓦碎，铜人露泣当涂中。","此砚流传良有数，奸人艳事非细故。","临漳不见铜雀基，石工夜发高陵墓。"]},{"t":"后铜雀瓦砚歌","f":"古风","c":["百金购一石，千金购一瓦。","不知何代物，云在魏王宫阙下。","当时歌舞充邺中，碧瓦朱甍铜雀铜。","艳传百世成宝玩，至今不数高欢宫。","或云晚出香姜井，六朝陶可三国等。","北齐避暑离宫物，古香古色龙山冷。","玲珑光衬宣德瓷，斑驳黝甚汾阴鼎。","漳河之底不可搜，冰台阁畔人争领。","两雄一例盗帝王，曹家风雅飞鸳鸯。","求魏得齐亦安用，未似书家王与羊。","今日甘泉传汉瓦，长生篆字兼未央。","惜哉后人不磨琢，定州高庙无同光。","分香卖履人安往，穗帷谁望西陵上。","千载砚工采璞来，当年七十留伪冢。","摩挲古物说奸雄，横槊赋诗亦可风。","杭州网得江心砚，终胜真藏许敬宗。"]},{"t":"题谢君生圹","f":"七言古诗","c":["乾坤老去剩残身，刍狗刍灵作比邻。","海外已无乾净土，山中尚有醉眠人。","当前斩板蓬蒿满，此后悬崖日月新。","我欲访君生死路，衡门输与墓门亲。","久欲从君起九原，奈他性癖爱邱樊。","随狙杜甫栖同谷，化蝶蒙庄寄漆园。","未待人间催薤露，预先地下辟桃源。","溪山岂觉吾儒腐，花落无言鸟不喧。","松楸三径日扶筇，拱矣亭亭部娄松。","笑看石朋来挂剑，卧听野碓助歌舂。","名山亦作麒麟楥，退谷偏崇蚂蚁封。","从得孝威求穴隐，此生端不叹龙钟。","健在浮生恨德孤，方壶圆峤等閒徂。","世间已任呼牛马，地下何妨听蟪蛄。","指点江山题素旐，安排风雨过黄垆。","瑕邱公叔称欢乐，谁效蘧瑗请首途。","浯水峿山待故吾，前身元是漫聱徒。","眼中王子柯虽烂，冢外袁公骨未枯。","问影问形皆若赘，为仙为鬼总称逋。","邱原三尺人无恙，无事延陵绕匝呼。","涧碧峰青好墓田，与君相见及黄泉。","灵均魂魄邻山鬼，陶岘平生近水仙。","有酒阮狂来痛哭，无声雍吊共流连。","清明寒食年年到，花发东墦北郭前。","六槚何年手自栽，空山隙地竁宫开。","丹砂不死仙人垒，黑劫无方造化台。","贞曜未铭东野去，通幽先相北邙来。","借君坟墓浇吾酒，及此平生进一杯。","埋文冢已同刘蜕，荷锸身将傍老伶。","槐穴玄驹先作梦，辽城白鹤欲藏形。","不知一老香山地，可是三休处士亭。","只恐谢敷求死苦，岁星未应少微星。"]},{"t":"泛太湖宿洞庭出石湖","f":"五言古诗","c":["远棹出胥江，旷漭无涯涘。","胥口复胥山，缥缈太湖嘴。","遥遥七十峰，一瞥失岿嶬。","既入太湖中，长天拍一水。","夜宿莫釐巅，高蹑灵威履。","朝来看包山，林屋何俶诡。","泛湖犹泛海，俯仰天尺咫。","及归向横泾，夹岸平如砥。","流水若流虬，连舟若连蚁。","曲折出洞庭，行行几十里。","石桥过几重，犹见洞庭尾。","回望石姥公，相送雨云里。","无限西南峰，露顶不及趾。","我欲认太湖，微茫何处是。","飘忽岂蓬莱，变幻成海市。","万岛列星躔，中流分峡峙。","犬吠水声中，鸟啼林波底。","凫浮浦溆多，鱼簖占洲沚。","人家渺霭青，村树蒙茸紫。","村家贴水平，水面炊烟起。","帆片贴水飞，远望叶叶耳。","欲问橘柚林，苍苍见葭苇。","大船行何迟，小舟去如驶。","出港入石湖，山遥水瀰瀰。","无山有湖天，月澄雨未止。","一棹绕胥门，满城灯如绮。"]},{"t":"自太湖洞庭回棹","f":"七言古诗","c":["灯火烟波认有无，天低月暗两模糊。","洞庭一棹姑苏返，夜半吟诗过太湖。","微月笼云夜不开，湖烟无际水无埃。","一灯远自中流见，知是姑苏城里来。","夜里波心又几桥，松陵不见客吹箫。","八枝急棹灯船过，我自湖光一叶摇。","玉雪坡南月露东，石湖故迹水浮空。","诗人亭榭词人路，无限烟波送小红。","尧峰远映水中央，曲港湾湾见水乡。","满岸人家满船火，石湖过后过横塘。","偃月成桥水作油，一城灯火认苏州。","摇船夜入姑苏市，宛在屏风镜里游。"]},{"t":"太湖中作","f":"五言律诗","c":["波浪涌冥冥，天白万山青。","南北吞江汉，东西峙洞庭。","雨含沧海气，风挟水云腥。","上下圆如笠，具区到此渟。"]},{"t":"苏州城内访古","f":"七言古诗","c":["湖里归来城里游，乐桥前后酒家楼。","专诸巷近要离远，偏是吴侬爱虎邱。","钱圃韩桥燹火经，荷塘柳岸尚青青。","南园已作空王地，赖有沧浪子美亭。","临顿桥边衢路长，驱车更访古沧浪。","锦衣大树将军尽，留得钱家鼎甲坊。","胜地茶花当武源，吟诗想像到梅村。","梦楼去后无人问，惟我来寻拙政园。","倪迂遗迹北城隈，巷近潘家路几回。","狮子林中太湖石，玲珑无数玉峰颓。","两岸人家夹绮罗，湔裙碧水市门过。","下塘街畔桃花舫，更比山塘画桨多。"]},{"t":"出无锡望慧山作","f":"五言古诗","c":["峨峨九龙峰，千古以锡名。","无锡天下宁，有锡天下兵。","今方无锡时，四海何交争。","出山矾水浊，在山锡水清。","泉池分上下，水味别淄渑。","四面芙蓉馆，两傍杨柳亭。","泉品居第二，茶经岂定评。","何如凌绝顶，一揽太湖精。","太湖波渺渺，远水入冥冥。","我欲访梅里，已无泰伯城。","飙然过常郡，尚可试中泠。"]},{"t":"扬州纪游","f":"七言古诗","c":["扬州风景名古今，我渡大江随处寻。","二十四桥无可问，虹桥烟月尚沉沉。","剪风横渡大江水，又渡瓜洲四十里。","侧看文峰宝塔湾，兼行淮浦伊娄市。","乘舟直向广陵城，胜概淮东居上程。","蘼芜城北隋堤草，冷落城中玉观琼。","隋炀已渺雷塘路，史公尚见梅花墓。","小金山傍瘦西湖，湖心寺对湖边渡。","蜀冈蜀井邵伯阡，风流尚在欧苏先。","三分明月二分柳，第一平山第五泉。","我行已过竹西远，我来无复珠帘捲。","青楼早绝扬州梦，迷楼不见隋家苑。","淮南江北接邗沟，城东一水入真州。","夫差阿◆豪华歇，祇有杨花逐水流。","离宫别馆居何许，邗江亦失芙蓉渚。","萤火已非古昔光，鸡声漫说陈隋语。"]},{"t":"北固山登望","f":"七言律诗","c":["江天楼阁渺茫间，天堑江城两面环。","寺内近寻梁武迹，云还远见晋王山。","象焦锁钥金陵道，京岘凭依铁瓮关。","六代犹馀驰马路，如虹石径枕波湾。"]},{"t":"北固山访古","f":"五言古诗","c":["胜绝千古称，胡乃一邱陵。","三国六朝间，长此阅废兴。","北顾复何有，江树渺冥冥。","赖有瓜洲渡，远入广陵城。","我从山头望，复向山中行。","栏杆百千尺，石磴三五成。","入寺访古迹，第一江山亭。","亭畔梳妆阁，下有很石横。","吴王留战帜，夫人留艳名。","梁鼎不可见，晋画已无形。","诸葛孙刘风，遗烈尚轰轰。","矫哉赞皇公，铁塔馀半层。","山腰云渺渺，江上风泠泠。","夕阳红到海，洪流去不渟。","骚人争凭吊，英雄事凌兢。","惟此一拳石，一顾今古更。","山小而江长，万派可扬舲。"]},{"t":"自瓜洲入扬州咏","f":"七言古诗","c":["飞鸟中流不易还，回头何处认青山。","重重江树茫茫水，山在南徐北顾间。","广储门外水萧萧，舟子江湾号柳条。","画舫珠帘何处是，月明千古照虹桥。","文峰寺外塔湾头，不见淮东胜概楼。","四十里程杨柳岸，瓜洲一水入扬州。","维扬风景不模糊，北郭园林入画图。","杨柳芙蕖无限好，五亭湖外瘦西湖。"]},{"t":"金山变陆感咏","f":"五言古诗","c":["金山如湘君，中流危插脚。","大地将变迁，一朝忽起陆。","嗟我东南天，六鳌不系足。","黑风吹蓬莱，汹涛没大麓。","此失鱼龙性，彼陷鲸鲵族。","浮沉俱已非，颠倒何其速。","而此立江干，犹可仰寥廓。","失水迩尘寰，终胜沉重浊。","我从苦海来，喜识山面目。","灵山倘有灵，我欲诉胸曲。","一溺至于今，何以脱诸梏。","闻说山当时，亦染潢池毒。","如来无完肤，与我同惨蹙。","今已换金身，无异西天乐。","宝塔凌天风，袈裟飘簌簌。","妙台岂云晞，琳宫未寂寞。","千磴摩旻穹，一洞入地轴。","江流山欲飞，万景聚一簇。","思作弥天谈，惜乎山僧俗。","东望三台山，此犹一粒粟。","试罢中泠泉，落霞满山隩。"]},{"t":"金山即目","f":"七言律诗","c":["吞江亭下妙高台，台外江光净不埃。","杨柳两湾云两坞，吴舟凫水入山来。","高台已共离宫杳，明月犹临蹬道边。","水调歌头来再弄，层层红树接江天。"]},{"t":"出城访竹林寺忽入鹤林寺","f":"五言古诗","c":["言出城南门，驱车夹山去。","言寻竹林寺，忽见连山树。","峰色夕阳中，苍筤绿如雾。","钟磬出瑶林，林外微风度。","径入鹤林中，寺外纷古趣。","茅茨作经楼，僧侣禅悦遇。","不见寄奴泉，遥想苏仙句。","有鸟无鹃声，林竹如沐露。","出寺五里馀，复得竹山路。","客亭涧曲临，禅房山坳聚。","翛然绝尘氛，恨无入山具。"]},{"t":"焦山","f":"古风","c":["焦山腴秀压金山，江娥江上堆云鬟。","寺里有山山有寺，一台二妙谁能删。","中流容与云霞现，船头俯仰江山面。","及停江时不见山，寺门缭绕青山甸。","入寺寻幽众妙多，楼台倒影江心波。","鱼龙跃浪吞青壁，赑屃凌霄挂碧萝。","偶过枯木堂，忽见名士迹。","四面新诗碑，一庭古法石。","山中最古是焦先，瓜庐虽渺有云烟。","登峰寻得三诏洞，访胜漫结六朝缘。","瘗鹤铭，鼋獭窟，出水入水旋浮没。","亭前鹤魄不可招，江上鼍风飘忽忽。"]},{"t":"出鹤林寺入山得竹林寺","f":"五言古诗","c":["万竹围一山，中有禅宫丽。","冈峦相属回，烟岚若澄霁。","山门步步高，竹林风细细。","佛殿山作阶，禅关石成砌。","万籁静清宵，钟声出林际。","入山洞壑殊，岩头露佛髻。","法锡六朝来，香烟未衰替。","遥望戴公崖，招隐踪可继。","寺前万绿深，殿后众山蔽。","一僧立云峦，人面山光翳。","日暮飞鸟归，我亦不留滞。"]},{"t":"初到镇江","f":"五言律诗","c":["青山拥人面，杨柳连江口。","山自六朝时，我来六朝后。","金碧压江南，雄秀压江右。","借问京口兵，何如京口酒。"]},{"t":"镇江城南玉夹山","f":"五言律诗","c":["日暝黄鹄山，何处戴颙宅。","山岚不见人，泉声出涧石。","回望献花岩，不见招隐寺。","杳杳林皋山，孤云与我至。"]},{"t":"出入镇江城","f":"五言律诗","c":["华街秋色满，不见满州营。","出入西南郭，回环铁瓮城。","晚来游夹山，朝来游北固。","今节值双十，提灯满街路。"]},{"t":"勾容道中望茅山","f":"五言古诗","c":["云中三茅君，向我若招手。","凌虚接太清，下作神仙薮。","劳山虽云高，不如茅峰陡。","峰峰滋白云，勾曲比岣嵝。","至今华阳洞，洞天极深黝。","山中陶隐居，长是烟霞叟。","惜哉符颂书，致诸萧公右。","灵山生药材，时为上方受。","少挂神武冠，老遗天子友。","宰相杂神仙，茅君其许否。"]},{"t":"下蜀港书所见","f":"七言律诗","c":["洪流一带浸长空，车路西行水向东。","落叶满江红日下，白帆如雪帆江风。","千片云帆港面开，隔江山望晋王台。","滁河渡口舟如水，应有人歌桃叶来。"]},{"t":"龙潭路望隔江桃叶山","f":"五言古诗","c":["隔江有名山，佛狸曾驻马。","饮马可渡江，天堑阻山下。","汤汤限南北，长江终古泻。","一朝王气终，隋师盈陈野。","美人传艳声，至竟亡陈社。","江上晋王冈，曾此受降者。","异代送青山，一井贻黄瓦。","抱膝张丽华，细腰同一把。","桃叶歌声哀，玉树歌声冶。","迎接过江来，桃根亦难舍。","一望瓜步空，谁将金粉写。","山水尚依依，无愁有泪洒。"]},{"t":"望见摄山","f":"七言绝句","c":["六朝烟柳六朝鸦，路近金陵问酒家。","青石满山红树远，大江如练到栖霞。"]},{"t":"过栖霞山","f":"五言古诗","c":["金陵三十里，山色从此分。","松根蟠古石，石骨仍嶙峋。","云霞出空际，半壁馀龙纹。","离宫连梵宇，自昔何缤纷。","一旦驰道荒，落红送斜曛。","山灵阅兴废，人世叹尘氛。","舍宅明僧绍，传作陶隐君。","虚声齐梁代，岂诚麋鹿群。","后有真隐者，名氏不可闻。","著书亦埋地，怀哉张白云。"]},{"t":"过尧化门及太平门车站","f":"七言绝句","c":["钟山叠叠路迢迢，海客踪随江上潮。","尧化门西秋色远，飞桥三折度虹腰。"]},{"t":"登三台洞","f":"五言古诗","c":["一洞入山腹，一洞凌苍穹。","宛转最高顶，缥缈悬虚空。","下压扬江水，上卓玉皇宫。","俯首江山小，两腋挟天风。","三磴千百折，蚁穴出游龙。","金陵在何处，一气连溟濛。","蜀江万里来，吴地一线中。","浦口九龙山，帆片如飞蓬。","江上八卦洲，点点覆青枫。","仪真与六合，目尽不可穷。","咫尺燕子矶，呼吸天可通。","栏杆落鸟背，平视太阳红。","长啸下高阁，放棹大江东。"]},{"t":"登燕子矶","f":"古风","c":["渺然临大江，凌空欲飞去。","洪流挟长峰，千里一蹲踞。","江左几兴衰，陈迹自何处。","今日乌龙山，昔时五马渡。","夷吾幕府起江东，今见翠微纷无数。","燕子洲兆燕棣祥，傅翼来自燕山路。","从此一江内外分，沧桑陵谷俱非故。","三国六朝事已空，两淮四辅谁为固。","水龙岸虎来石头，司马佛狸竞瓜步。","几时不以天堑鸣，江心出没惟乌兔。","此矶不比采石矶，亦不可比金焦与北固。","昂然邀得翠华临，山水盛名亦虚傅。","矶上右顾黄天荡，矶左远顾乌江戍。","千古江山大战争，尽供此水东流注。","一拳石觜閒徘徊，烟水茫茫望中赴。","回头欲入观音门，夕阳斜挂江边树。"]},{"t":"登鸡鸣山","f":"五言古诗","c":["不见功臣庙，惟见功德寺。","射雉彼何人，鸣鸡闻此地。","同泰馀故基，舍身复谁氏。","萧梁往事空，台城留位置。","何处景阳宫，井◆有遗腻。","突兀志公台，钟声出深閟。","覆舟山色青，玄武湖光翠。","已洗六朝痕，尚含六朝粹。","望见青溪流，绮合秦淮里。","烟市俯下方，万片瓦麟次。","寺后豁蒙楼，荒洲风景异。","江上乌龙峰，时送遥青至。","迢递下山邱，不尽白门思。"]},{"t":"登雨花台","f":"古风","c":["西望杳杳天阙山，东望大江去不还。","金陵故宫自何处，石头钟阜如长干。","兹冈锁钥城南关，遥撑半壁成重磐。","采石军声撼建业，古今争夺此弹丸。","梁武讲经于此间，天花法雨散华鬘。","青丝白马来侯景，朱雀乌鸢出大圜。","此台旧事不堪忆，高座寺边馀暮色。","吊古何须感废兴，即今且复埋荆棘。","梅岭已荒内史亭，石冈已铲谢公迹。","孤垒犹留战后氛，二泉空话茶时客。","嗟乎，绝好江山可游观，兵燹一动无翠峦。","于今寰海再鼎沸，岂得江淮一水安。","我从高处望中原，南北山门白日残。","岷江万里来秋色，缥缈海东生暮寒。"]},{"t":"莫愁湖曲","f":"五言古诗","c":["湖边杨柳树，湖上芙蓉花。","石城横塘路，云是莫愁家。","湖碧花逾香，花红水犹腻。","将波作镜奁，想见莫愁媚。","头有苏合香，居有郁金堂。","河水向东流，湖波自夕阳。","送欢下扬州，吴头复楚尾。","一日湖上心，千古秦淮水。","湖上有高楼，有子名阿侯。","输与中山王，天子亦无愁。"]},{"t":"金陵杂诗","f":"七言古诗","c":["虎踞龙蟠古帝阊，湖山虽歇尚苍苍。","微茫无数前朝迹，叠嶂长江绕建康。","下关浦口水悠悠，阛市东南占上流。","狮子山头白门路，兵旗不似阅江楼。","残泉犹有五龙澄，四角皇城剩两棱。","游遍帝乡如驿传，明宫过后过明陵。","一路青青叫画眉，朝阳门外柳如丝。","马蹄踏过钟山背，何处昭明饮马池。","朱雀桥空古色稀，燕飞不见旧乌衣。","秦淮桃叶流如故，画舫青溪日暮归。","废苑荒台感不禁，青溪流水到而今。","祇馀一曲残杨柳，无复当年九曲深。","无数遥峰对近鬟，楼头青压水西关。","南唐风景今安在，一簇清凉寺里山。","寓公好事有袁郎，士女风流映小仓。","今日随园鸿爪尽，茫茫二十四云房。","孤冷偏能耐久留，一层半亩在山头。","随园不及龚高士，残照秋风扫叶楼。","东吴阅后又南朝，淮色山光两寂寥。","故国周遭都已渺，石头城去大江遥。"]},{"t":"过乌江口望见霸王山及庙","f":"楚辞体","c":["渡江八千人，垓下一朝散。","舣舟此上流，虞兮终古怨。","谁知阅世后，威烈空山冠。","庙貌凛千秋，灵风凭两岸。","长陵土一抔，项庙江东半。","韩弓久已藏，楚歌今长叹。","乌骓亦馨香，不同炎火断。","缅想入关时，诸侯掌上玩。","鸿门公大度，鸿沟汉首叛。","本纪立当时，公论早应判。","狄相事金轮，正气亦有限。","土木施炎威，檄公何乃谩。","我舟去如风，无由一荐盥。","回首望三山，霭霭隐霄汉。"]},{"t":"过牛渚江","f":"五言古诗","c":["吴楚争长岸，孙策攻刘繇。","晋隋及宋明，战此如鸿沟。","叠巘连江起，一水亘扬州。","白月青天夜，飏帆白鹭洲。","岂不生山色，亦壮大江秋。","如何古迄今，系缆为战陬。","烽火拥江水，列戍海山头。","历阳与丹阳，南北阅边愁。","维昔谢将军，听诗上孤舟。","温峤然犀过，照见水府幽。","此事差可意，牛渚长悠悠。","我今坐轮舶，幸未惊蛟虬。","溯流至采石，喜见谪仙楼。"]},{"t":"眺采石矶","f":"古风","c":["赤城云霞起层峤，采石青山最佳峭。","中有锦袍谪仙居，外有韎韐将军庙。","临江作步如虹悬，长江渺渺波浸天。","群峰插岸相后先，艨艟衔尾舳舻旋。","青绿云山挂眼前，此时此景谁能迁。","所恨兵来多渡此，战争间续三千年。","东吴南朝迄南宋，常开平又奋戈船。","毓麟堂下馀废垒，然犀渚上生寒烟。","此时采石黯无色，迄今何幸留清妍。","彭杨水师靖湖海，采石江边祠堂在。","何如长庚捉月亭，魂魄山川长不改。","尝闻萧尺木，曾画李白楼。","匡庐衡岳落素壁，东岱西蜀连云浮。","此景足助青山色，此画青山留不得。","惟馀赭岸蘸横江，永与青山障采石。","我来无事溯江行，一棹长风万里轻。","船头已向蟂矶去，船后才从牛渚经。","何当待月清秋夜，"]},{"t":"看天门山 其一","f":"七言绝句","c":["出云楼阁压晴漪，两岸青山又一时。","采石矶头行客远，日边江上望蛾眉。"]},{"t":"看天门山 其二","f":"七言绝句","c":["破浪楼船气亦降，螺峰倚岸蹙成双。","重重天堑连天阙，楚尾吴头锁一江。"]},{"t":"北望裕溪口","f":"五言古诗","c":["东吴赤壁后，濡须亦恶战。","力争到淮南，始可固江甸。","水陆攻合肥，此口成急漩。","远江烟霭中，一望青如淀。","下有濡须水，上有濡须山。","巢湖出何处，还入窦湖间。","隔水对两军，夹水立两坞。","春水方生时，曹公去宜早。","猘子孙仲谋，以江为深沟。","濡须争战后，更到皖水头。"]},{"t":"过芜湖 其一","f":"五言绝句","c":["隐隐蟂矶庙，迢迢谢尚城。","一江灯火浸，两岸夜潮生。"]},{"t":"过芜湖 其二","f":"五言绝句","c":["雄紧临江县，苍茫极浦秋。","何时过北岸，一水入庐州。"]},{"t":"过芜湖 其三","f":"五言绝句","c":["远浦分吴楚，横流自古今。","赭山山色近，清弋一江深。"]},{"t":"世谓华州不见华山而同州反得见之华州人每不平余在池州江上亦望不见九华而人云无为州中可见爰作一诗","f":"五言古诗","c":["华州附太华，不辨太华山。","同州三百里，顾得见孱颜。","高人在山中，山人了不关。","姓氏驰远方，远客争来攀。","千里不见睫，与此同一般。","我过铜陵矶，莫认青阳甸。","远远无为军，反及九华面。","云际有芙蓉，九朵莲花瓣。","江神与醯鸡，狡狯宁目眩。","一叶障太山，何况渺兹县。","江水去悠悠，两岸即池州。","华山不可望，更望九华楼。"]},{"t":"过池州见山","f":"七言律诗","c":["淼茫东泻又西还，曙色朝霞远浦间。","江上青峰都已过，不知何处九华山。","一岸烟波一岸山，五松九子贵池间。","江南此地多山水，恨不维舟一往还。"]},{"t":"过枞阳江","f":"七言古诗","c":["我读汉书武帝纪，曾说射蛟三千里。","出自寻阳薄枞阳，盛唐之山枞阳水。","我今来过枞阳江，江山如画云如幢。","中流惟见燕飞乙，南狩不闻蛟叠双。","天柱霍山自何处，灵风欲逐武皇驭。","元封盛事不可追，江头空诵凌云赋。","江水近沦皖水波，淮水之满今若何。","再行即见皖山色，后游且继枞阳歌。"]},{"t":"泊安庆城南","f":"五言古诗","c":["自出建康来，形胜斯为最。","江行千里馀，耸见大都会。","天堑抱城边，云墉枕水外。","襟带控中流，烟寰郁苍荟。","远峰江上观，袅袅若阴霭。","何处皖公山，天末辨螺黛。","咫尺拦江矶，作此江上塞。","惜哉视不真，隐跃鼋鼍背。","独塔凌长空，波涛涌淜湃。","去去不移时，回舵见城内。"]},{"t":"秋试行役感咏","f":"五言古诗","c":["微名迫我起，我行过千里。","既越两重洋，又涉百重水。","波涛挟蛟鼍，时时向人跂。","咫尺生风云，天色迷瞻视。","身在澎湃中，轻掷同敝履。","不识有眠食，岂复有行止。","言念古战场，安能在海里。","丈夫志四方，艰难此为始。","我行过关山，一平复一险。","马角与船唇，流光常烁闪。","一入矮屋中，苍苍为之掩。","如蜂攒蜜房，如蛾傍灯焰。","不必帝京尘，缁衣已先染。","叹息古英雄，此中多沉奄。","意气幸发越，磨刀不惧剡。","摛文倚幨帷，月明星点点。","俯首念归途，胸中海潋渰。","归来阻海风，卧船经八日。","火轮不得施，心如飞箭疾。","惊浪向面生，朝阳从波出。","缩地古有人，超海今无术。","一夕玉镜平，如鲠胸中失。","问津傍蓬山，陆始水已毕。","扁舟过酒家，谁能辨清质。","身如蟠泥龙，不免蝇与蛭。","嗟彼远游子，何以同邮驿。","一出台北城，即接铁车路。","万山随转圜，千里失回顾。","虽丧磐石安，却胜舆夫步。","断虹悬空中，驶轮旋飞渡。","翘首望前途，烟云蔽午树。","息驾入城门，似马初停骛。","问我从何来，天风兼海雾。","泱漭整行装，明朝从此去。","一日复一日，行行将到家。","前途已无几，盼望转成遐。","马上有秋色，路上有秋花。","夕阳在树外，反哺有暮鸦。","惊心堂上亲，未谂餐饭加。","入门问老母，依旧两鬓华。","病体虽不康，怜子意犹赊。","只为区区者，累母望天涯。","叹息古人贤，负米亦孔嘉。","阿兄见我至，为我拂衣裳。","阿嫂见我至，为我具羹汤。","童稚先后走，相争负行囊。","自维不肖躯，满堂何皇皇。","乃知天伦中，至乐有馀长。","人生思富贵，悲喜在外旁。","呼仆啖晚饭，燥吻兼饥肠。","一饱身已困，不复思酒浆。","荆妻房外立，望我栏杆头。","相见问劳苦，翻讳己心愁。","自君之出门，不敢登高楼。","楼头红日照，楼外白云浮。","见云不见人，风信海中沤。","鲤鱼常渺渺，鸿雁自悠悠。","景物夙已换，自夏以徂秋。","桂轮圆复仄，橘柚绿已稠。","道上渐轻霜，言念季子裘。","相见虽云欢，明日将远游。","嫁君在少年，离别何如流。","为卿话旅况，卿当添烦忧。","丈夫负弧矢，岂复恋家室。","惟有高年亲，艰难离双膝。","幽禽鸣木中，时亦思琴瑟。","逐逐鸡肋名，似饥拾橡栗。","谋名复谋利，骥马徒奔佚。","思之辄不解，未能遗纤悉。","倥偬风尘中，金玉销素质。","行人已归家，家书始附至。","汪洋一海横，飞鸿失其翅。","叹息远行人，数语空自寄。","上有覶缕怀，下有平安字。","日月两周天，一纸滞途次。","草茅望阙情，寸衷无由致。","委质数篇文，与此亦何异。","江湖与故乡，遥下数行泪。","俯念大海中，求珠应不夜。","自恃骊龙精，当有神光射。","一寸明月辉，岂无神雀下。","象罔眼如箕，搜寻何能罢。","升之在云衢，鳞甲风雷化。","沉之在重渊，光芒泥涂藉。","得失两心煎，欲脱不得卸。","本无毫末加，何为动惊吒。","但思出身阶，此为乘时驾。","成都有相如，不屑赀郎借。","是以一卷文，珍重不轻假。","可怜遭按剑，犹望连城价。","九月月几望，桂树开花时。","蕊榜将悬阙，颠倒郢中儿。","我身在海角，引领望天池。","云程阻风信，得失未应知。","寸心已先往，大梦犹奔驰。","飞电空中下，一刀割乱丝。","得意不须喜，失意何庸悲。","翻悔昨日情，此心如醉痴。","月色淡将曙，天明秋路远。","鸟声唤行人，萧萧到山馆。","上岭午烟苍，下岭夕阳晚。","空中盼白云，不舒复不捲。","渺渺溪中水，秋深流转浅。","安坐閒斋中，诗书慵过眼。","转念读书乐，再把陈编玩。","浩歌梁父吟，落叶空阶满。","木末起蝉响，秋深天气凉。","萧森商声远，孤园摇众芳。","感此心容瘁，入世多悲伤。","富贵非所慕，雄心失行藏。","所以古之人，载质每皇皇。","八代起衰手，为此亦徜徉。","鸿鹄群燕雀，鸦雏傲凤凰。","意虽不奔竞，潦倒未应忘。","流水远更远，空山深复深。","怀在白云内，时傍高松阴。","幽人谁与语，一片古时心。","入世恫尘俗，谁复领清襟。","所以古贤豪，轻遇重知音。","伯牙不可作，子期毁其琴。","柯亭岂无竹，蔡雍邈难寻。","此地有高山，携酒独登临。","苒苒百世怀，悠悠千古想。","置身恨不高，未能空万象。","尺寸何所施，风尘徒鞅掌。","一朝为浮名，琴书失素养。","与世争涓埃，胸中胡不广。","遥遥望古今，寥寥思天壤。"]},{"t":"路上即景","f":"五言律诗","c":["山色接邮亭，行云去不停。","一春梅雨白，万点海天青。","客路莺啼树，村家鹭刷翎。","芒鞋桥上过，芳草满前汀。"]},{"t":"感事和韵","f":"七言律诗","c":["不见苌弘碧血腥，江山离乱杜陵经。","相逢白发黄倪辈，尽是饥鸠老鹄形。","海沸三年珠屿黑，天烘一角火峰青。","涛声远远蛟龙啸，日夕楼头当哭听。"]},{"t":"登珠潭屿偶咏","f":"七言古诗","c":["万山重重围一水，四水圆圆浮一山。","一屿如珠点波间，一汊陡入苍崖弯。","其水澄泓明海峤，其山高秀压尘寰。","其阳如展蓬莱颜，其阴如垂玉女鬟。","山水天光共一色，水碧山青互回环。","水远无梁山无磴，◆嵼云霞不可攀。","山开恍逢衡霍面，水转疑入潇湘湾。","花发鸟啼波渺渺，独有山灵时往还。","我来凌风试径渡，不觉中流风露寒。","阴沉恐坠蛟龙窟，登陟又愁麋鹿顽。","居人喜见山南客，导我请观水北蛮。","深山奇异不可尽，悬崖露骨树生◆。","我欲移家长此住，尘途扰扰山缘悭。"]},{"t":"野路","f":"五言律诗","c":["笋舆行不尽，苔径入平芜。","浊淖分禾亩，新泉注芋区。","烟飞双野鹭，水立一番凫。","极目斜阳外，青山露屋隅。"]},{"t":"番山近事","f":"五言古诗","c":["五月行军日，辎夫处处征。","险逾穿大漠，役似筑长城。","爆石冬雷迅，危峦夏雪盈。","战云深树里，悽绝鼓鼙声。","地绝东海东，安营僰爨中。","乱山千甲坐，险道五丁攻。","蜀鲊蒸人瓮，冤魂啸鬼雄。","合欢峰顶望，瘴雨日濛濛。","日日起烽烟，蛮山欲触天。","军无诸葛鼓，费有贰师钱。","万垤遭焚蚁，千峰叹站鸢。","驱人牛马走，挽运到霜巅。","惨戚内番山，藤萝亦血斑。","鏖兵深壑暗，放炮乱峰殷。","逃死林箐里，馀生雪窟间。","困穷时出斗，军气落凶蛮。"]},{"t":"閒居即事","f":"七言古诗","c":["大荒海外托纵横，寂寞人间气不平。","宗炳空怀五岳志，潜夫未遂九州行。","吟诗饮酒无他事，斫地谈天了一生。","灯下萧然念身世，閒居四十二毛惊。","海岱迢迢春复秋，遁荒未觉岁华遒。","上层楼住陶弘景，下泽车乘马少游。","富贵不如书万卷，沧桑况见屋千筹。","陆沉暂作浮沉客，花月江山似水流。","地走中原断不连，幽栖海澨与山边。","小园庾信三竿竹，负郭苏秦二顷田。","世乱消磨年少日，家居排遣劫中天。","只今杜甫吟诗处，兵燹疮痍满目前。","芜城废苑遍蒿莱，万里浮云眼倦开。","甲子谁题元亮宅，庚申独恸谢翱台。","千秋大事皆泡影，一卷新诗亦劫灰。","感愤满腔无处洒，案头长有酒盈杯。","年年闭户赋离忧，辞谢红尘绝应酬。","千岁古书堆榻上，一春今日据楼头。","云开远远青山入，潮起茫茫碧海浮。","且自逍遥人世外，不须欢乐不须愁。"]},{"t":"秋日感怀","f":"七言古诗","c":["夙愿乘风出请缨，江山何处卓龙旌。","晾鹰辽塞云无色，饮马长城水有声。","安得楼兰惊介子，可怜海岛遁逢萌。","霜天灯下萧条坐，万卷当前气不平。","西风簌簌奈吾何，阅尽惊波又逝波。","鲲背千年沉黑海，马头万里望黄河。","子通磨盾心原壮，张翰持杯鬓已皤。","匿迹穷荒无处所，有时山鬼一牵萝。","大荒海外更东荒，风急天高碧浪长。","日日编愁遵枉渚，年年晞发近扶桑。","有怀掷帛游关内，无路乘槎过日旁。","最是不堪登望处，神州时欲起红羊。","庾信生涯仅小园，荆榛何处认周原。","桑田沧海红尘路，燹火人烟黄叶村。","世难王樵居茧室，身閒宗测画苏门。","江山一片斜阳里，照见疮痍血泪痕。"]},{"t":"中东感事","f":"七言古诗","c":["忆昔中原汉道恢，宸游直过琅琊台。","海西白狄占星至，关上青牛望气来。","益地图从王母送，受降城向武皇开。","祇今九叶思前事，无复经纶草昧才。","世界方今号共和，英雄才岂老瞒过。","华夷獶杂衣冠尽，人物萧条制作多。","玉牒空移秦历数，金瓯谁补汉山河。","可怜海外珠崖郡，付与东荒作逝波。","血雨腥风处处流，蓬莱真个作蓬邱。","万家痛哭仍苛虎，九海孤穷更聚鸠。","罗掘一空兵不厌，怨仇交积主无忧。","管宁穿榻辽东地，懒把馀生计去留。","兵气漫天日月昏，深山大泽亦风云。","凯旋酒犒花门队，鏖杀戈来輴板军。","麛鹿毁胎方扫穴，貔貅见馘忽亡群。","洞黎亦有枭雄辈，请与中原猛士闻。"]},{"t":"鸡笼港漫游感事","f":"古风","c":["白浪如山西北来，谽岈一线港门开。","西山合沓东南障，远海重见琅琊台。","海水群飞今几日，旧日山容已全失。","中国楼船去似风，外洋烟突森于栉。","江山潮汐总凄凄，谁欤港中筑断堤。","古迹休寻郑国姓，战瘢堪诧佛郎西。","佛郎西从西海至，甲申往事余能记。","弃地虽由刘使君，扬威犹多李广利。","君不见，三沙湾外二沙湾，佛军白骨埋青山。","战船一年来一祭，峨峨京观海漫漫。","我行踏上狮球岭，岭头战垒犹堪省。","炮台尚拂蛟漦腥，烟晕可吞鲸鲵影。","何图乙未上氛祲，十载关山变古今。","重重岩阻无人守，日日渊沉海水深。","海山自青水自黑，山头旗交红日色。","山半今安日本营，海中今绝华人迹。","自古山川剧变迁，谁似我土多惨戚。","一丸海岛天穹垂，非雾非烟闪倏吹。","已矣人间无可道，泛舟仙洞仙踪追。","回看洋楼船坞连海起，一幅云山战场里。","民间膏血浪沙淘，千秋尽入尾闾底。","潮来潮去吊兴亡，我亦望洋悲海市。"]},{"t":"门丁谣","f":"五言古诗","c":["我公在何处，我公在县厅。","我公不解事，解事有门丁。","能令我公喜，能令我公怒。","指挥不待公，我公殊不恶。","我公下村乡，门丁能攘羊。","鸾刀取其血，血是民汁浆。","我公到城市，门丁能作豸。","有角不触邪，触取巨象齿。","公若欲催科，门丁张网罗。","役夫且慢发，役夫货几何。","公若欲谳狱，门丁几番促。","促公复迟公，门包几车粟。","门丁能作福，门丁能作威。","小民一身肉，俱为门丁肥。","我公能作官，门丁与有分。","我公欲和事，请向门丁问。","人生多得钱，不过作好官。","我公钱如水，门丁钱如山。","门丁利如锥，我公明如镜。","门丁与我公，与钱同一命。","门丁存善念，有时欲改恶。","待公官休日，门丁恶不作。","我言告门丁，门丁仔细听。","人间无刑书，天上有雷霆。"]},{"t":"纪灾行","f":"五言古诗","c":["庚寅岁六月，上天雨泽竭。","一夜风霆声，万山草木拔。","老龙奋横威，牙爪纷冲抉。","磅礡气所至，屋瓦狂飞发。","不知从何来，水潦万丈决。","田庐所居人，一夕为鱼鳖。","地上山忽奔，井田随破裂。","哀哀天弗闻，苍生受颠越。","苍生受颠越，不自今伊始。","去年新令行，诛求苦无已。","鲂鱼赪尾逃，平地皆祸水。","灾害一时生，天其显者耳。","我欲告苍天，请论数与理。","理数不可知，天怒有时止。"]},{"t":"鹿港卡","f":"五言古诗","c":["津头整布帆，好风正东南。","舟人不敢过，验船者二三。","偏隅一黑子，津吏亦眈眈。","鹿港非隩区，征商有馀馋。","由斯观天下，遍榷何以堪。","我到鹿津头，偶问鹿津吏。","关津不惮繁，尔身有何利。","自言利涉途，官一吏三四。","温饱在于斯，馀乃为公事。","乃知民之艰，半多吏所置。","朝廷徵其一，吏胥徵其二。","叹息古人贤，利薮在乎义。","一歌何易于，朝廷广恩意。"]},{"t":"汛地兵","f":"五言古诗","c":["犛牛不执鼠，虽大亦何为。","驽马在厩中，虽多亦徒糜。","养兵千百头，缓急供驱驰。","在野为守望，在城为守陴。","爱身不爱国，戴弁等行尸。","居恒犹惴惴，何论危急时。","昏夜闻盗贼，剽掠在城池。","女墙群酣睡，起立如醉痴。","声东而击西，子行姑迟迟。","自维为狐兔，何敢斗熊貔。","秦人与胡越，肥瘠两不知。","明朝在市井，哮阚威风施。"]},{"t":"蒿目行","f":"七言古诗","c":["岁在戊子月在酉，地上欃枪天彗帚。","社鼠野狐哀嗷嗷，一队健儿负梃走。","蛮烟细民无异志，只因新令掊克苟。","新令之条行者谁，刘公铭传来抚守。","自请住台过十年，剪除荆榛使财阜。","去岁剿番剿不成，遂向民间增税亩。","一方田园十数弓，丈量比前长八九。","累锱积铢算不遗，官乃与民争利薮。","不为朝廷培本根，斲丧元气焉能久。","区区弹丸何足言，坐使皇朝伤高厚。","农夫商贾不聊生，纷纷痛心又疾首。","浙东计亩为公田，南或呼箕北呼斗。","传说昨日已打城，无乃跳梁成刍狗。","揭竿作旗抢地呼，背负耰锄击土缶。","肉食无心为苍生，脧削依然故见狃。","古人不畜聚敛臣，此言真堪铭鼎卣。","赤城千里如金瓯，无故寻端欲碎剖。","不知祸水何时平，老范甲兵胸岂有。","九重高远未曾知，万民泪落秋风柳。"]},{"t":"催科役","f":"古风","c":["门前咆哮鸣，屋后锒铛声。","父老不敢出门视，催科到处鸡犬惊。","催科狰狞如虎狼，催科震怒如雷霆。","不为尔曹贿赂至，菽粟岂能生公厅。","前者催科归业户，业户自知辛苦情。","今者催科归我曹，我曹惟有醉饱行。","某月某日下新令，新供旧供火速清。","老农闻此语，方知前日是太平。"]},{"t":"卖儿翁","f":"古风","c":["男者奴，女者婢，田园稼穑生荆杞。","昨日催科到闾里，求生不生死不死。","老妻典尽禦寒衣，老农卖尽耕春耜。","今日家中已无馀，所未尽者惟有子。","欲别泣涟洏，欲往何处依。","皤皤双白发，何日再生儿。","出门得温饱，胜在家中饥。","养子已无期，生子复几时。","旁人闻之心骨悲，老翁吞声前致辞。","吾台前日称乐土，不知何人造崄巇。","量尽田园增尽赋，地无膏腴民无脂。","人事天灾一齐下，哀鸿嗷嗷何所之。","重以役胥如貙虎，削脧不得须臾迟。","我愿君心光明烛，烛尽逃亡田家屋。","蜂虿不得生其毒，民虽赪尾无鱼肉。","呜呼，此语天地为之哭。"]},{"t":"海关吏","f":"古风","c":["陆行畏虎水畏波，恶知波向平地多。","平地风波险而高，关吏时时张网罗。","不论千艘与万艘，扬帆鼓棹即逋逃。","风晴浪静不得去，关吏悉索如老饕。","溪壑填盈开一面，行人舟子唤奈何。","昨日无风今鸣涛，千夫性命系于毛。","地棘天荆无所往，嗟哉，环山蔽海以为牢。"]},{"t":"绿林豪","f":"七言古诗","c":["北风萧萧暮色黄，绿林豪客结成行。","腰横宝剑手长鎗，明火杀人胆气强。","来往跳梁何所忌，入室胠箧又探囊。","县令闻之无所问，此辈出入已寻常。","此辈亦是游侠客，激而为之无所惜。","饥饿驱人到于斯，何以削脧犹未息。","雨露云霓不得施，田畔良苗即蟊蠈。","今日作贼胜作官，坐收物力不知艰。","不稼不穑无所事，财帛货贿高于山。"]},{"t":"溪边田","f":"七言古诗","c":["流沙澌澌云漠漠，朝为青田暮为壑。","海外沧桑倏变迁，溪居莫道田家乐。","昨朝来时看绿禾，今日来时看素波。","老农负犁何处去，田在溪中万顷多。","溪边家家学耕作，春刈秋收岁岁过。","农夫最爱千年业，安得天上枯黄河。","溪头未归村犬吠，家中早已到催科。","老农闻之长叹息，欲罢不能行不得。","晚涨三篙流潺潺，仰视苍天无日色。"]},{"t":"海边耕","f":"古风","c":["大造茫茫谁真宰，东为青田西为海。","海畔沙漠不见人，老农耕之筋力殆。","拨沙拔茅锄作园，耕时十旬九旬喂。","夏畦冒雨种地瓜，秋天霜冷枯根芽。","荷锄负锸视地脉，不见瓜成但见沙。","陇头莳植生活计，有时种豆落生花。","花开花落不结子，野人满地空梳爬。","海滨卤壤为经纪，渔在山头樵在水。","我嗟海滨人，如在荆棘里。"]},{"t":"铁车路","f":"古风","c":["声轰轰，如霆雷，火炫炫，如流电。","双轮日驭速催行，回头千里忽不见。","抵掌欲笑夸父迟，轮台一日周围遍。","西人逞巧亦良危，颠踬往往艰一线。","我道带砺在河山，缒幽凿险山河变。","自古众志方成城，不闻铁车与敌战。","又况劳民复伤财，民穷财尽滋内患。","台湾千里如金瓯，浑沌凿死山灵颤。","有潦有流间其间，不能飞渡复中断。","借问铁路何时成，请待天炉为炽炭。"]},{"t":"机器局","f":"七言古诗","c":["乾坤火器不敢逞，上有炎轮下炎井。","大块水机不敢作，西有弱水东汤谷。","气机潜藏一朝开，千山万山鬼神哭。","机械循环何时穷，生民万类皆荼毒。","时势所趋亦难止，竭力为之将胡底。","损伤元气民怨咨，台湾脧削痛肤理。","加赋征商罄国赀，机器局中贮祸水。","国家自强在无形，销金铄石通精诚。","西洋有道不在器，惠政善谋无不兴。","国强不闻恃险马，区区利器何足行。","外虽示勇中心怯，西人亦岂畏虚声。"]},{"t":"西洋灯","f":"古风","c":["西人机巧无不可，不膏不脂能吐火。","一缕荧荧放电光，日暮人家燃千朵。","又有玻璃覆碗明，人家争置数盏灯。","或悬虚空或插案，照耀微茫白雪生。","中国圣人制度备，颠扑不破传利器。","流泽久长可百年，何乃世人竞为异。","西洋伎巧遍天下，中华物产失其利。","我叹台湾尚洋灯，一端可以验风气。","安得尧舜重光出，世间还淳返朴归郅治。"]},{"t":"台湾官府纪事","f":"五言古诗","c":["前车载囊橐，后车载妻孥。","壮丁夹傍路，布地黄金铺。","江山方鼎沸，官府争首途。","国事彼何知，鼠窜保头颅。","何来庾吴郡，载去飞舳舻。","始知朝庙上，多此误国徒。","可怜海外民，日日望来苏。","去者已如鲫，在者亦犹驽。","行旌出郊野，阻截逢狗屠。","千夫拥锹锸，一夫起啸呼。","官长将焉往，进退局辕驹。","轿有七宝笥，箧有一箪珠。","匍匐献营垒，四出调兵符。","护卫过城甸，胜似供军需。","官守弃陷阱，生死脱崎岖。","海峤三千里，谁能为负嵎。"]},{"t":"台湾沦陷纪哀","f":"五言古诗","c":["天倾西北度，地缺东南方。","蛟龙激海水，沦没蓬莱乡。","熬波沸巨浪，白日黯无光。","山俏牵木魅，土怪鞭石梁。","颠簸王母阙，震坼禹皇疆。","洪水湮部洲，燹火及昆冈。","嗟哉武陵客，坱莽失康庄。","避秦无源路，仰首望苍苍。","天心方有醉，西眷弥不遑。","玄枵淫岁纪，鹑首赐扶桑。","戈船起海岱，毒弩横汪洋。","寄托不得人，措置纷乖张。","射人空射马，擒贼不擒王。","不能捣巢穴，坐守任跳踉。","平日糜巨亿，海军等木僵。","柄政三十年，陆守复徬徨。","纷纷交涉事，议和绝不刚。","何为多设施，铁路亘遐荒。","大敌不敢战，乃受小敌创。","如许弹丸地，中国屈输将。","峨峨冲车轮，当路避螳螂。","叹我生此邦，眼泪作饭浆。","感时辄呜唈，事事结中肠。","复遭此世变，台海如沸汤。","输币兼割地，皇上费周章。","听为民主国，大总统曰唐。","玉人镌印绶，戎仆制旗常。","欢迎动郊野，宣耀照城阊。","覆舟得援溺，黔首喜欲狂。","逃遁先有人，万民阻行囊。","推戴大抚帅，中流恃宝航。","磨戈思一战，同泽赋三良。","黑旗兼栋军，曩岁经战场。","人心乃叵测，林氏首徜徉。","国恩不奋报，梓里不筹防。","敌氛来海上，引兵竟归藏。","无才哥舒翰，中夜起皇皇。","敌骑犹在边，唤渡觅洋商。","托词将督战，脱身沧海旁。","马厩冲烟火，无主乱兵攘。","居民不得安，招敌入城厢。","迟之逾三日，始见东兵行。","弹枪前队仗，炮子后筐箱。","马蹄行郭索，剑佩带锒铛。","头有髡发冠，腰无下体裳。","皂袍长至地，犹存古时装。","纠纷穿阛阓，住宿占民房。","杀戮幸不甚，老稚得踉蹡。","成群争越海，流离事堪伤。","叹息唐抚军，始末未交锋。","敌得长驱进，拉朽施利铓。","谁料大厦倾，乃逢一木当。","香山苗栗间，义民起如蝗。","鏖战不得前，敌马徒披猖。","自言海上来，未遭此颉颃。","倡之者为谁，义士吴徐姜。","用矛赴齐师，争推为徐骧。","绍祖亦悍斗，视死如阳阳。","吴君能统率，亦未易低昂。","村妇佐磨刀，耕农自裹粮。","力抗已兼旬，太守来共襄。","可恨县令李，掣肘不为倡。","无米巧妇炊，有沙道济量。","揭竿禦坚炮，无成亦足强。","五月迨流火，雷电破斧戕。","彼族添新兵，犀利何可尝。","刘帅援军至，迟缓徒奔忙。","曩土填决河，无益于河隍。","叹息台中郡，一旦同淜滂。","城下多死人，村间多痍疮。","乌鸦早暮飞，啄肉啼悲吭。","月黑鬼燐出，天暗飓台飏。","维时正上弦，暴雨继恒旸。","我在沧桑内，变迁托痴佯。","七月月几望，敌兵忽不扬。","游骑将南进，伏甲起深篁。","使之铩羽回，顿觉不翱翔。","可惜空弮搏，难当百鍊钢。","逾月聚兵往，民众见驱狼。","所叹刘光世，晚节不昭彰。","战守两茫然，坐镇岂民望。","为时固云久，赴敌未慨慷。","传闻于道路，今已去敖仓。","巍巍赤崁城，一带失保障。","可怜海外民，戴汉心未忘。","凶耗虽耳熟，疑信不求详。","昨日海关处，新令悬煌煌。","赋税将重征，不及恤流亡。","今春多灾异，天上分玄黄。","不出旬日间，澎湖受兵殃。","为时甫半年，黑劫换红羊。","蹂躏二千里，犹未收欃枪。","嗟我中华产，长鬣对艅艎。","儒冠皆扫地，表海空泱泱。","千秋伦物国，一旦化狼◆。","譬如五彩凤，俯首九头鸧。","末世多如斯，晋宋已蜩螗。","愁思无由写，日日登北邙。","举目见蓬蒿，涕泗如逝湟。","哀哉乱世内，默默谋为臧。"]},{"t":"洋兵行","f":"五言古诗","c":["鲸鲵出尾闾，鼋鼍鸣海峤。","雨淫山鬼啼，风凄木精啸。","杀气干青霄，白日昏不照。","三三五五群，佩铳横剑鞘。","军帽小筒圆，复帛双股绕。","靴袖束紧身，时或长衣掉。","其黧而贱蠢，裸形露两窍。","呜呜满街衢，酣醺一狂叫。","是为东洋人，但觉兵威耀。","当其整队行，兵气肃无声。","惟闻马蹄铁，郭郭来重轻。","背负一糇囊，腰缠一革縢。","木箱驼炮子，稻草覆釜甑。","炮车转轮至，殷地时轰轰。","进退无金鼓，指点非旗旌。","笼鹅又牵牛，路上掠牺牲。","入市索民舍，居房折户闳。","偶闯入人家，携取两手盈。","大者胠囊箧，小者及罍瓶。","俘杀非王意，将令失章程。","台民不堪扰，或思愿属英。","英夷岂吾类，转劣倭文情。","倭人处处是，黄色白肤理。","岛居有婆娘，貌近中华美。","照影在图中，纤纤裹素指。","兵人携在身，戏欲配汉子。","前朝有往来，最敬中邦士。","今丁国势衰，侮吾此为始。","祸胎谁养成，依稀傅相李。"]},{"t":"闻斗六一带被燬有感","f":"五言古诗","c":["皇天降灾殃，发自倭人手。","非彼能横行，天假为彗帚。","雨膏二百年，时数丁阳九。","或逢贪酷官，或遭跳梁丑。","潢池有沸汤，小民受其咎。","循环逾十秋，中辄生厄纽。","曩岁刘公来，台海经击掊。","纷糅及山川，削朘穷林薮。","一波未能平，一声狂鲸吼。","汪洋日出方，突如来祸首。","疆臣无瑰材，海天遭碎剖。","烽火遍全台，间时燎薪槱。","去冬台北城，忽有群雄纠。","聚沙不成团，焚如付乌有。","首从咸远飏，伤哉村童叟。","兹夏斗六门，亦复出抖擞。","彼族好扰人，乱丝益生绺。","闻说据在山，巉岩鬼神守。","彼族佩枪登，伤仆如坠缶。","失利无如何，馀怒及耕耦。","旁近几十村，村村焚成黝。","吾民居此间，如指在械杻。","所望天好生，意外能运肘。","俯提出妇孩，倒悬解耆耇。","吾民饥渴深，时时瞻箕斗。","骤雨不崇朝，暴风不恒久。","上天多变迁，云头灭苍狗。","岂有爱憎心，此薄而彼厚。","不过昏眚侵，太阳暂蒙垢。","真人驱天骄，名王系组绶。","献俘阙庙前，函头在左右。","未知我今生，得此遭逢否。"]},{"t":"老妇哀","f":"五言古诗","c":["出门逢老妇，白发蓬压眉。","倭兵蹴之行，哀哀泣路歧。","乞食不得饱，眼泪垂作糜。","问妇何所苦，呜咽不成辞。","有室无可归，残年丧子儿。","一家八九人，遭杀不胜悲。","大者能扶耜，小者仅知饥。","爱女倚房居，刺绣手牵丝。","大妇在炊下，淅米肉如脂。","一夕闻兵来，悚息泪交颐。","聚泣共吞声，忽有兵人窥。","闯入掠衣饰，索钱勒藏赀。","刀枪交股下，大者死阶墀。","回头视幼子，身首已分肌。","女妇骇啼走，并命于一时。","缕陈未及终，哭声已涟洏。","更端问老妇，摇首不闻知。","旁人纷纷说，甲乙亦如斯。","甲家益酷死，馈倭为倭欺。","遗下数顷田，芜秽草差差。","复存数间屋，入夜栖鸢鸱。","东家绝炊火，西舍游鹿麋。","亦有倭人宿，连甍卧豺罴。","破壁系鞍马，折门煮牲牺。","行人不敢过，迂路且鞭笞。","世衰人物贱，不死皆便宜。","翘首望苍天，言之有馀噫。","叹息百年上，琛赆朝四夷。","民物皆丰贵，鸡犬亦雍熙。","草野无知觉，听我吟哀诗。"]},{"t":"哀鸿篇","f":"五言古诗","c":["芦塞腾霜威，大地填杀气。","饥鹰搏击来，征鸿何处避。","嗷嗷向南山，复逢矰缴绁。","肃肃起秋声，飘飘洒毛血。","爰集在中泽，俯仰且偷生。","黍稻四野空，飞啄又安营。","我作哀鸿诗，未终泪盈把。","长距凌云霄，弱肉风尘下。","闻说云林地，今年遭屠杀。","垂翅落机中，破脑不得脱。","家室既摧残，脂膏亦剥割。","造化岂不仁，生物付夭阏。","哀哀群羽毛，枨触难为活。","凌空思奋飞，樊笼终有括。","中或失其群，饥鸣徒嘎嘎。","被絷啼向人，相视犹胡越。","今秋乃亢旱，郁风致恒旸。","禾粱半枯黑，草木纷萎黄。","鸿雁欲求食，四野如穷荒。","一粒即珠玉，未可升斗量。","接饭无所投，饥乌处处翔。","何以弋者流，缘株罝罟张。","残物以谋饱，人心胡不良。","寄语矰弋人，哀鸿已无肠。","戒杀犹未得，须为倾太仓。","更有澎湖路，沧桑海忽枯。","三十六峰屿，一旦焦为卢。","水咸不得雨，即雨草不苏。","鸿雁来何为，泽中徒叫呼。","岂有食可谋，更无田可芜。","往年海为耕，无食且饱鱼。","嗟哉鱼不得，啼血摧胸臆。","造物不孳生，吾为汝恻恻。","恻恻复恻恻，鸠形兼菜色。","城狐杂社鼠，日攒太仓食。","太仓日以盈，狐鼠日以生。","哀鸿自嗷嗷，岂有利爪争。","西风满地来，四野闻悲声。","昔日随阳鸟，今日刀俎鲭。","罗网多杀机，天地为阴坑。","我闻造化心，孵育靡不宁。","五雀与六燕，安有滋重轻。","闻我哀鸿诗，应为心怦怦。"]},{"t":"澎湖失守纪事","f":"古风","c":["杀气阴风北斗高，轰轰雷霆殷海涛。","仰首但见天周遭，鬨耳群惊海煎熬。","千里逝水闻滔滔，出地霹雳欢蛟鳌。","电音驿至报胜仗，明朝溃卒随波逃。","依稀败耗人未信，溃卒登岸如猬毛。","市中咆喊虎怒号，战阵驱来羊一牢。","呜呼，四万义军同日死，陈涛之罪千秋指。","今日战士望风奔，保全首领走而已。","争诧西洋炮火神，中国炮火日日新。","军不训练弃与敌，城垒有炮奈无人。","岁未月卯日庚午，蓬莱海岱生烟尘。","春风吹浪作号泣，鲸鲵小丑抉龙鳞。","汉廷元老筹妙策，议和遣使出天津。"]},{"t":"停战遣使纪事","f":"古风","c":["汉武射蛟临海岱，海水沸起蛟龙背。","昆明习战战士多，楼船百万皆鹳鹅。","海战虽失陆战兴，大冶堇山可铸兵。","又况燕云森壮士，一朝众志自成城。","君不见范阳鼙鼓动地来，李郭壁垒风云开。","金人马足中原播，宗岳韩刘一战破。","国家练军祸乱秋，志士义旗有同仇。","升平安坐谈韬略，临时或付流水流。","田单即墨犹保燕，长城万里夫何忧。","堪恨停战沮士气，楚人之鬼越人禨。","百万锋铓忽藏韬，战士坐甲空歔欷。","闻道使者出东洋，无从得见东倭王。","丧邦辱国此为甚，丛神土偶盈庙廊。","更闻上相欲亲使，包羞忍耻成何事。","幄帷画虎付虚空，肉袒牵羊甘跋踬。","积重如今竟难回，几时疆土可重恢。","沧海日到榑桑暗，阳阿晞发心为灰。"]},{"t":"割地议和纪事","f":"七言古诗","c":["万里金瓯浑不缺，谁道千钧系一发。","艰危一旅可重兴，何为遽把皇图割。","今日以和保都城，恃和狎敌鼎且倾。","胜败兵家有常事，数败一胜势可争。","今日未尝为血战，激使好战谁敢轻。","犬戎在昔陷西京，宣王亲整六师征。","我朝三辅奠磐石，山海关外兵连营。","大帅养重不励士，坐使越甲吾君鸣。","下国尚耻城下盟，大国上相亲行成。","重重海陆失岩阻，战守无计和无名。","公孙用刺真下策，裴相不死非尊荣。","辽阳自曩钟王气，台屿于今成蓬瀛。","一朝蹙国数千里，奥蔽尽撤将焉撑。","嗟予头埋足又蹶，叩阍无从效曹刿。","眼见岛夷更得天，心痛中华长失岁。","沉沦身世付伧荒，分裂乾坤销猛锐。","仓海君无博浪锥，衔石今后同精卫。"]},{"t":"追述去冬时事","f":"楚辞体","c":["时十一月岁乙未，台山北海如波沸。","遗民义气薄云霄，欲转汉天回汉地。","骤似雄风吹雨来，复似怒潮挟沙至。","重重夜袭台北城，惊杀倭兵失梦寐。","城头半夜起狼烟，城外连天列象燧。","倭酋持枪尽欲狂，倭卒寻刀起如醉。","越日彼族元节天，不成拜贺不就次。","电达全台皆戒严，火急三军齐结驷。","延城驱出领袖人，束以羁绁防生事。","是乃逢迎趋利徒，岂有才情能树帜。","狐疑鼠窜空怔营，维时外间尚无意。","彼族杀气犹未降，压阵冲锋出大帅。","天使遗民成国殇，二三首雄中炮踬。","雄徒四散登于山，可哀良善遭斩劓。","冬风惨惨吹哭声，阴雨凄凄飘肉骴。","平民庐舍数千家，灰烬之中无位置。","逃亡耕夫诈诱归，复以一坑除芒刺。","是时我正丧所生，倚门夜泣皋鱼泪。","闻之意惨心复摧，不能哀吟亦酸鼻。","年来衔石不能填，叹息海天出魍魅。","呜呼七哀兮，哀不尽，风云气。"]},{"t":"绿林行","f":"古风","c":["东洋兵气森如霜，破敌无声如虎狼。","一拳海上黑丸地，地窄不足供回翔。","数军弹压有馀势，狰狞恶貌惊洪荒。","谁知绿林多豪客，小丑不量出跳梁。","昼在山场夜城郭，凌空蔽日如飞蝗。","一指障目无泰山，劫夺民家穿营房。","洋兵瑟缩不敢出，有如猛虎畏群羊。","四围鸣炮声汹汹，两傍列炬光煌煌。","小寇由来过大敌，正正旗鼓阵堂堂。","入室横行无所惧，往复倒橐又翻曩。","委蛇欲退不遽退，辄向营头鸣数枪。","行人复说大坪山，白日出劫洋兵行。","初谓一吼噤万窍，谁知满身生烂疮。","南北烟尘复四起，兵且难行况善良。","呜呼绿林客，恨不为国出宣力。"]},{"t":"洋关行","f":"古风","c":["海风琅琅海水高，西油东布千百艘。","载以宝筏三五篙，未到鹿门皆逋逃。","关吏狞狞如鬼号，背上火枪腰铁刀。","下水挽筏牵上岸，充作公货饶尔曹，商人瞠视两眼如巨鳌。","泣诉不可得，关吏瞋尔言啰嘈。","吮尔皮血盬尔膏，东头有虎千百牢。"]},{"t":"叩阍辞","f":"七言古诗","c":["海外之民同戴天，覆盆在顶天悬悬。","天所覆载无颇偏，何为此地民颠连。","乙丙之际烽燧然，丁戊之交民孔瘨。","天魔对人舞蹁跹，鱼羊食人血湔湔。","杀人如篦如草菅，民居此间如拘挛。","足如茧缚手如捲，如肉如醢在刀边。","如獐如麋狼虎前，虎则咆哮狼流涎。","耳雷鼻火涎如泉，磨牙抉爪为戈鋋。","罗刹鬼国黑风旋，人肉为粮膏为餐。","一餐未饱万骨攒，肩膊高于火焰山。","浑沌无窍亦镵镌，况为血气何能全。","不角不爪堪一叹，天骄肆虐群生孱。","人类尽为异类残，何有飞走及蠉蠉。","杀机所逞毒◆◆，蒸为疫疠及黄瘅。","纷纷跕跕堕乌鸢，死或僵仆病迍邅。","病者死者郊遂迁，不然须遭挞与鞭。","重则系缧年复年，或鸩而死即方便。","讳死讳病泪涟涟，人间万户如禁烟。","疫所不及亦苦旃，防病骈将无病牵。","瓜蔓之抄果蔓延，我且翘首一问天。","天纵彼暴何为焉，岂为气数天无权。","古有大劫经三千，劫灰未满无可填。","须将人类劫中煎，但是为劫何矫虔。","祇将一岛付炎燀，东西之海何平平。","中央一土独倒颠，文物之邦辱腥膻。","伦类之祖一线绵，未知冥漠夫何言。","高高下下皆陶甄，生人机械亦戋戋。","天岂无力为转圜，何为坐视距喙专。","山有罴貙野有豻，狰狞头角行蹒跚。","避地欲到天门难，仰空呼吁天阊关。"]},{"t":"斗米叹","f":"古风","c":["斗米易钱钱一囊，台湾未闻此奇荒。","闻之自古疑荒唐，不意年来屡屡尝。","今年米价尤殊昂，一斗二升银煌煌。","市中之米作珠量，食米之人膏粱肠。","贫民得米为米浆，升杓在手千金装。","又有无米无可望，朝朝采藿登首阳。","旱潦之后草色黄，茹草不得为寇攘。","明火杀人取所藏，比于倭人尤堂皇。","劫夺孰与税敛强，时或放火烧民房。","亦习洋氛效薄凉，暴政焚杀皆寻常。","盗为饥驱情可伤，况有道殣无劻勷。","算及锱铢添税章，民不得食泪汪汪。","房捐市税何处偿，说增一倍告四方。","人人争欲望苍苍，望天或雨钱与粮。","无肉可敷眼前疮，无水可苏赪尾鲂。","呜呼，无米孰为指太仓。"]},{"t":"估客行","f":"古风","c":["曾闻海上蓬莱山，珊瑚之树翡翠环。","贸易往往得奇货，千艘万舶随去还。","今日来时非畴昔，魍魉攫人惊远客。","牵船上岸不放行，千金万宝皆一掷。","邱墟惨淡何市阛，轻行辄罚千百锾。","去家既苦远，居此复苦艰。","误入蓬莱山上山，无乃南峤鬼门关。"]},{"t":"闻日军队搜山感赋","f":"五言律诗","c":["乾坤长肃杀，海上战争多。","蕃队日鸣炮，山民夜枕戈。","炎昆糅玉石，覆卵扫巢窠。","世界今如此，苍生且奈何。"]},{"t":"兵火之后旧时街衢但存瓦砾感赋","f":"七言律诗","c":["惊天蓦地起兵戎，闾左繁华瞬息空。","喧路鹳鹅同上蔡，失家鸡犬异新丰。","蔓烟无复炊烟绿，燐火犹疑燹火红。","旧日楼台何处认，乱堆残瓦夕阳中。"]},{"t":"田亩叹","f":"五言古诗","c":["拮据置田亩，苟且充鹤餔。","姑为口腹计，岂暇子孙图。","视彼连阡陌，勺水与江湖。","奈何丁官厄，向我开广途。","横攘十亩地，顿减十斛租。","五鹿逢与块，空对野人呼。","昔人谋肥遁，日夕思莼鲈。","我食犹被夺，况望千木奴。","回头视野老，颜色惨更枯。","负耒无田耕，思欲作亡逋。","见说浊溪水，架有假铁桥。","一溪溉万田，万户仰以饶。","昨者洪潦生，桥梁被冲漂。","铁路畏濡滞，遏水修泥橇。","至今八堡浍，未有涓滴浇。","秧针初插土，日中旋枯焦。","况在夏秋交，大火似焚烧。","沾体涂手足，叹息腹空枵。","无以宽赋敛，岂复免征徭。","田家及佃户，助长思揠苗。","勺水不得濡，复欲徵水租。","水租犹尚可，地租恶追呼。","水租为公用，地租为国帑。","厉行籍没法，不比偿宿逋。","窃叹商鞅家，无此聚敛徒。","丁户计口收，房屋亦征输。","入市复算缗，锥末及锱珠。","削朘将到骨，未止占剥肤。","茫茫沧海桑，何日变膏腴。","损失泣万家，我亩良区区。","今人言避世，漫欲托渔樵。","岂知山海间，无处可逍遥。","环牢绝隙地，林壑惨不憀。","斧斤及网罟，薮泽宁汝饶。","区区数卷书，牖户亦萧条。","惟我读书窗，生意草色摇。","砚田废不耕，诗酒乐箪瓢。","漱石枕流水，看山忘饥枵。","盘桓五柳下，斗米未折腰。","收穫望明春，歌啸过村桥。"]},{"t":"大扫除","f":"五言古诗","c":["壬寅夏四月，土匪大扫除。","号令一朝下，万室为邱墟。","当其设甘饵，信誓说降初。","始作周郑质，继藏盟府书。","长待以不死，山泽任樵渔。","服从一以久，杀机起籧篨。","南北及中央，同日入周阹。","一时敦杯酒，万口为臡菹。","一二勇决夫，枪火伏衣裾。","作势与之敌，反噬不踌躇。","木毙人亦摽，虽死异羊猪。","馀悉骈首戮，载出薄笨车。","妇孺从流移，人弃室亦潴。","南投斗六间，杀气惨不舒。","阴风扑人面，燐火遍里闾。","哀哉归顺徒，不得求为鱼。"]},{"t":"大讨伐","f":"五言古诗","c":["丙午方隆冬，生番大讨伐。","叠嶂摩青天，连营一齐发。","白日照深箐，朔风响林樾。","烈火焚高邱，炮声夜未歇。","凿齿与雕题，相逢即驰突。","其俗本狉獉，其人如鹰鹘。","抚之曾几时，屠之起仓猝。","殆为垦荒来，辟土不容忽。","遂使瓯脱间，亦走东洋卒。","平野多草莱，何用入穷窟。","师劳久无功，万山掷枯骨。","狞树蛇蛰蟠，怪石鬼面凸。","谷暗丛木呼，径险古苔滑。","生番何处栖，腥风动溟渤。","呦呦麋鹿哀，莽莽狐兔没。","长坑无所施，群峰立峍崒。"]},{"t":"援道殍志感","f":"五言古诗","c":["茕茕有老妇，委作道旁喂。","无名登尺册，收容有同罪。","保甲连坐条，斯言非汝绐。","闻汝丈夫子，身材亦磊磈。","避乱逢倭兵，竟作刀边醢。","老妇无所依，流离成冗猥。","身体罹残疾，病容日腲腇。","视之怀为伤，赠之以货贿。","茫茫天地间，转轮为苦海。","沉溺彼何人，悲声有馀欸。","济物须乐施，厚费宜无悔。","常持此寸心，聊以补真宰。"]},{"t":"田野即事","f":"五言古诗","c":["村家何错落，村树何凌乱。","一径长逶迤，四野青草断。","道旁一老翁，牵萝发浩叹。","茅屋颠风飘，禾田恶水漫。","穷民兼饿殍，腹枵已年半。","荒鸡号昏宵，鳏鱼旷晨旦。","出门天地空，四顾无樵爨。","官吏日叩门，敲扑驱种蔗。","糖税归国家，糖利归会社。","农户绝饔飧，啼饥穷日夜。","农夫剧苦辛，为农难为稼。","蔗田虽有收，贱估不论价。","昨来大雨风，蔗苗况如赭。","徙倚到东皋，嗷嗷盈四野。","去年雨烂苗，今年风残稻。","陂塘处处乾，水租徵更早。","野田璺如龟，无禾亦无草。","农夫畏出门，坐饿成枯槁。","妇孺啼于床，牛羊号于皂。","粒米贵如珠，况乃乏刍稿。","荷锄何处施，悠悠望有昊。","潦后布旱云，雨露绝点滴。","四野烂如泥，炎威乃赫赫。","枯苗涸田间，峥嵘日火赤。","万户亿人家，群饥成菜色。","此间祲气多，有雨亦无泽。","况乃恒阳天，庶草何由殖。","薰风来若丝，解愠空太息。"]},{"t":"囚人哀","f":"五言古诗","c":["惨惨新竹城，悽悽苗栗路。","阴风四面来，颓云千里布。","警吏夜缚人，如狼驱走兔。","三五同一牢，百十同一捕。","骈颈就死期，悲情谁得诉。","亦有为鬼雄，一瞑绝不顾。","可叹瓜蔓抄，荆棘在跬步。","毙木作摽枝，生涯付草露。","贷死有轻条，犴门长禁锢。","仰首海东天，覆盆日为暮。","长此黑漆乡，黡然不求寤。","微尘一张眦，时时堪恐怖。","逝者良可哀，存者亦何慕。","海山有鲸鲵，京观封无数。","悲风散毅魂，何处五人墓。"]},{"t":"役夫叹","f":"五言古诗","c":["生作路旁尘，死作岩下土。","白日惨不温，照见役夫苦。","役夫来自东，见山两眼红，茧足万山中。","役夫来自西，有足自行地，未尝越山溪。","役夫来自北，呜呜复唧唧。","城人入深山，如鱼落罟罭。","役夫来自南，南热寒不堪。","入山逢阴雨，僵绝六有三。","山途况险恶，溪深石崿崿。","肩头负重担，未行足已弱。","长官图勋阶，民番填沟壑。","只有役夫苦，谁识从军乐。","西人驱向东，东人驱向西。","饥暍受鞭扑，不异犬与鸡。","毒疠中人身，仆地烂如泥。","一死无消息，望绝母与妻。","来时敛金钱，比闾供行李。","死者不求生，生者且困死。","骨积空山坑，泪满浊溪水。","奈何辟番疆，使我至于此。","他日青山碑，忍以赤血纪。"]},{"t":"入市书所见","f":"七言古诗","c":["荔支上市新桃红，绿竹雨过笋坼丛。","村家争趁挑菜节，街店初度卖鱼风。","杖头挂钱拟沽酒，酒楼近在市门东。","入市蹩躠才数步，捞虾卖浆如走兔。","碎裂粥鼓折饧箫，蚝筐满地钱满路。","蓬头乱发捉向官，皤叟啼哭黄童怖。","青春白昼此何为，官役执鞭处处怒。","旁人嘶声向我云，沿途贩卖例罚布。","鞭朴尚觉施小惩，重则科条须禁锢。","市上有门门有亭，小贩须从此中停。","牟利之夫蝇头聚，公徒敛钱一一经。","此钱为汝谋卫生，民愚不知自犯刑。","日斜市远无人过，肉味蝼漏鱼郁腥。","我闻斯故三叹息，营求锱铢比盗贼。","年来斗米贵如珠，一寸之丝当尺璧。","斥牛出犊充赋租，质子典衣供悉索。","朝卖芋拳夕卖瓜，穿巷入街行蹜踖。","天阴雀冻乌毕逋，空仓日日走饥鼯。","门前门后锒铛呼，临江谁有千头奴。","节食缩衣犹不足，可复酒家唤当垆。"]},{"t":"闻人话北部警事感作","f":"七言古诗","c":["昔日大坪聚健儿，沿山沿海驱岛夷。","风声鹤唳八公兵，篝火狐鸣五丈旗。","义旗一飏一再起，三载东洋惊祸水。","岛民虽被作牛羊，敌兵有时成蝼蚁。","自从□旅不可撑，梅子坑里为秦坑。","敌人眼中无铁屑，酷毒倭政尽□行。","粒粟寸丝难苟活，千家万家□剥夺。","十羊真有九人牧，一鸡长遭百刀割。","环山蔽海无所逃，釜中燥蟹钳巨螯。","残喘偷生不容喙，医疮剜肉竟焚膏。","沧海横流时一泄，涓涓忽洒苌弘血。","去冬北部鬼雄呼，四十人把斯人杀。","一时视死如视归，五人之豪颜佩韦。","况有同心数十辈，千秋义冢高巍巍。","昔人愿近要离墓，如君之徒堪比数。","恨予读书身手弱，闻风空式怒蛙怒。"]},{"t":"役夫行","f":"古风","c":["瘴气蒸成万峰赤，悬崖洒遍猩血色。","深箐万古无人行，只今道路开荆棘。","路在千山万山中，壑深无底涵虚空。","藤萝尚带洪荒气，炮火横施开凿工。","开凿未已驱人上，征夫前泣后夫望。","手足作车尻作轮，狞雨盲风催转饷。","热气烁人成乳饴，冷气中人成僵尸。","毒湿渍人为腐脾。","天惊地塌雷霆起，复有破石堕空糜躯肌。","昔日中华全盛时，讨番役人人不知。","黄金布地士争赴，岂似今日驱人供熊罴。","兵卒三千夫十万，中央南北搜罗遍。","弱者输赀壮输身，迭番践更急于电。","闻道溪中产水晶，复企山中生金英。","可怜膏血换空地，一寸茸茸原野万骨撑。","长林一过无日暧，危峰再去有冰块。","五月穿裘困雪山，万夫痛涕至天晦。","问渠于此何不逃，渠言无处匿蓬蒿。","商鞅保甲诛连坐，惠卿手实吹毫毛。","呜呼，闾阎何事求安堵，此间法比连环弩。","吉网罗钳匪所思，虎苛蛇敛不堪睹。","相逢尽觉无人形，山头日作青燐青。","莫怨灾星散平地，试看炮雨穿林冥。"]},{"t":"剿番行","f":"七言古诗","c":["山獠穷居深山中，亘古不与秦人通。","重重叠嶂云烟阻，缈缈危峦霜雪封。","生聚虽如三僰众，杀锋未似五溪凶。","如何下策用火攻，西海直侵东海东。","不比牂牁下庄蹻，岂同巴蜀通唐蒙。","忆昔汉家天子诏，划将瓯脱为边徼。","侏离有语安耕猎，烽燧无熇封岭峤。","南北輴蛮虽棱威，中央靡草未原燎。","长与深林养鹿茸，何事将军誇◆鹞。","乃今穷兵踏◆◆，炮火所飞狐狸叫。","重崖阴阴无日曜，滚滚溪流石陡峭。","暑寒不时风叫窱，冰块纷纷随潦漂。","役夫开道身虺隤，兵士重毡镜远眺。","酒保技师收厚利，台人号咷倭人笑。","台人久作釜中鱼，生番熟番奚安居。","耕地一蹂无秸粒，山庐一火无籧篨。","番人逃窜成猿狙，山中来往随豪猪。","可怜千炮深箐溜，顿使三危众骨菹。","回视番巢万蚁垤，一朝如蚁遭扫穴。","白石苔封苦役骸，青山瀑泻藤猺血。","花莲港与合欢山，两军遥举互包截。","东西战队未双连，南北挽输劳九折。","寄言番妇莫冤啼，嗟我周黎亦靡孑。"]},{"t":"剧新百一诗","f":"五言古诗","c":["新政言难罄，聊为举一隅。","岂能鱼漏网，长觉雉离罦。","天地空亭毒，江山等弃繻。","闾阎虚盖藏，郊邑伏萑苻。","律例繁兼猛，生谋有若无。","千方图悉索，百末责均输。","抑勒将刑迫，吹求藉势驱。","削朘吞弱肉，征榷尽锱铢。","铸鼎欺编户，怀琛罪匹夫。","明徵同冠夺，暗取似穿窬。","豢吏专苛敛，供军厉急需。","虞衡山作贡，盐府海为枯。","酒务重重酤，糖园处处租。","一朝开市里，万井变官途。","金币难三品，权量锢五都。","风云惊发号，雷火骇严符。","暮令朝旋改，前科后顿殊。","衣冠皆獶杂，逻视总貔貙。","侦伺穷幽隐，公私肆觊觎。","死亡因细薄，陷溺在须臾。","日日遭鞭挞，家家苦役徒。","深文真刻酷，善政益模糊。","检疫寒侵骨，焚尸痛切肤。","牛羊登册籍，鸡犬禁逃逋。","灾害伊谁恤，烦冤底处呼。","秉威官长暴，立宪下民愚。","黑界盆中戴，黎元几上屠。","锄夷难苟免，波累惨追捕。","连坐商鞅重，坑降白起粗。","杀机深北鄙，种类落东胡。","耆旧沦舆皂，农工比隶奴。","低徊思曩昔，彷佛隔黄虞。"]},{"t":"见台湾保甲连坐法感题","f":"七言律诗","c":["商鞅死后无罪魁，今见东邦炀死灰。","秦法每甘骈戮尽，苗刑又见罚锾来。","朱儒处处埋坑坎，乌鬼家家养祸胎。","竟岛拌将人物敝，鸡栖连栅不须哀。"]},{"t":"过大甲溪日暮口号","f":"古风","c":["两山夹溪出，众水中流分。","水落群石起，两山相对奔。","一水渡未毕，西海已衔半边日。","不辨山容辨水声，水声急驶如雷疾。","水挟沙石流滔滔，鲸鱼有脊鲲有尻。","风雨春秋发洪潦，一溪万窍生怒号。","招招舟子指行路，路在溪中乱石处。","陵谷今来几变迁，乱石如山流不去。"]},{"t":"艳歌行","f":"楚辞体","c":["捲帘忽茁老蛟须，燃烛忽唾骊龙珠。","红玛瑙碗青珊瑚，登筵为君祝欢娱。","窈窕神妃在堂隅，长眉修鬘立斯须。","瑶旗翠羽苍虎符，即之若有还若无。","将以饫之无灵巫，我所思兮在远途。","灵风闪烁霜雪肤，酌君寿君歌吴歈。"]},{"t":"新秋即事","f":"七言律诗","c":["西风瑟瑟暮云飞，远望关山路未违。","两岸白蘋初贴水，一林红叶欲沾衣。","淞江客爱莼鲈美，衡岳人看荻雁肥。","独有八闽天尽处，愁来不见片帆归。"]},{"t":"打鹿行","f":"古风","c":["崱屴千峰复万峰，峰峰如剑向人摐。","密密藤萝看不见，中有千年鹿养茸。","一群狰狞出苍狗，林中三鹿五鹿走。","腥风恶兽踯躅奔，山猪趋前熊趋后。","猎人持枪林中藏，不期中肩期中首。","负枪复向云雾中，穷冬莽莽生悲风。","扪壑攀岩作猱上，艎榛但见青濛濛。","逐鹿深山道，山深惟荒草。","相传上有琼瑶台，复说中有金银岛。","逐鹿不知山浅深，时时路傍逢洞獠。","洞獠深居穷崖阴，逢人杀人无人心。","猎人见獠如见鹿，獠群鬨散如惊禽。","打鹿取藏涧中水，或杂黄獐兼野豕。","十日挈出向冰壶，肠肉既佳味亦美。","身带山中烟瘴归，归到家中与妇子。","焙肉把酒共酣呼，鹿臭在衣血染须。","鹿蹄可以换斗米，鹿茸可以市珍珠。","鹿角熬胶养身躯，打鹿之乐何如乎。","打鹿不畏苦，使余从军气如虎，汉家狗屠视如土。"]},{"t":"意难忘 感事二首 其一","f":"古风","c":["一梦黄粱，看世情似水，断尽人肠；","江山馀琐屑，云物换苍茫。","天黯黯，海浪浪，是黑劫红羊。","最不堪，故乡花草，都付斜阳。","中原举目凄凉，问伊谁破碎，失却金汤？","回头非锦绣，转瞬见沧桑！","尘扰扰，事忙忙，岂电火流光！","叹此生，蓬莱已隔，又作伧荒！"]},{"t":"意难忘 感事二首 其二","f":"古风","c":["剩水残山，只斜阳一角，多少蜗蛮；","马嘶金谷树，车断穆陵关。","沧海外，软尘间，谁似我闲闲！","不肖躯，人丛溷迹，未是殷顽。","年来泪作朱殷，回头思故国，望断刀镮。","天长浑似发，地缺竟成弯。","时已去，鹤空还，有城郭阑珊。","好男儿，鬓眉镜里，照见惭颜。"]},{"t":"凄凉调 词纪近事，失于平质。盖时方头会箕敛，沿门挨户，无能免者；故不觉其言之直也","f":"古风","c":["何来轣辘！","凄凉甚，人人似坐刀镞。","不胜蒿目，谋生计尽，或歌或哭！","洋氛怎恶，更沿户咆哮怒蹴。","好无情，天魔部曲，者辈果鱼肉。","试看城村路，老幼号咷，孰堪敲扑！","市场最苦，到如今，局翻棋覆。","莫忆当年，想黄金都填壑谷！","谩逋逃，已是家家上簿录！"]},{"t":"丑奴儿慢 记事同上","f":"古风","c":["奇般异状，还是惊波骇浪。","念当日，天愁云惨，又下魔王。","釜里游鱼，那知一霎沸狂汤！","催科为计，不须抚字，新法西洋。","几处卖丝，几家卖谷，空自医疮。","问何事，翻囊胠橐，簸稗扬糠？","则见他来，峥嵘头角似饥狼。","算缗箕敛，有无力者，怎耐鎯铛！"]},{"t":"鹿溪行","f":"五言古诗","c":["我行鹿水上，遥望鹿溪东。","霁月出深碧，乱山悬半空。","东北为肚岭，东南为燄峰。","峰峰何奇崛，九十有九重！","群峦竞绿缛，万树含翠浓。","翠岫破荒起，朵朵青芙蓉。","鸟声啼竹林，又闻隔林钟。","循溪行不已，人家四、五里。","行尽青溪头，万冢乱烟起。","沙薯百顷红，芦黍千村紫。","谽谺春水桥，迢递夕阳市。","登桥望阴翳，云涛互亏蔽。","沧海从西来，潮水向东逝。","夕霭苍茫时，山海渺无际。"]},{"t":"旅思二首 其一","f":"五言古诗","c":["前路风忽忽，征车寂不发。","一出故乡来，回头望城阙。","不见乡中人，但见乡中月。"]},{"t":"旅思二首 其二","f":"五言古诗","c":["花开春已晚，月明人已远。","愁心如车轮，长行去不返。","欢情如月轮，圆时再不满。"]},{"t":"短歌行","f":"古风","c":["莫照堂前镜，照镜生白发。","莫上马头鞍，上鞍见髀骨。","富贵而销磨，无异厮养卒。","贫贱而销磨，不如长灭没。","峨峨者山，洋洋者河。","河流无已，不如山高。","愚为利役，贤为名劳。","富贵繁华，万古蓬蒿！"]},{"t":"猛虎行","f":"五言古诗","c":["南山有猛虎，食人无乐土。","悲风飒飒来，山鬼诉穷苦。","似诉当初时，被食人不知。","筋骨遭狼籍，皮肉受离披。","侠儿欲扑之，陷阱不先治。","反增猛虎怒，咆哮不可持。","攫兽食其䴠，攫人食其脂。","当道而蹲距，眈眈常苦饥。","行人无所逋，畏虎兼畏狐。","狐为虎牙爪，搏噬与之俱。","一虐犹难避，两虐将安图！","生莫近狐穴，死莫傍虎嵎！","生死不自由，前路立踟蹰。"]},{"t":"旅地寒风感怀","f":"五言古诗","c":["北风吹如铁，一夜寒冰结。","万山草木枯，十里笮桥折。","路上无行人，行人马啼齧。","尘壒扑天黄，日色入云灭。","村径十三条，条条沙断绝。","回首蓟北山，无此霜凛冽。","曲腰寒起粟，龟手冻欲裂。","磨砚池水乾，扫阶雪地洁。","佩剑霜有棱，熏笼火不爇。","窗外问梅花，冲寒未吐蘖。","踟蹰顾行旌，迢遰犹难发。","岁月叹蹉跎，谋生计已拙！","长大抚头颅，壮怀未豁达。","抑郁在人间，貂裘苦难脱！","意气百尺楼，风尘受颠越。","今古几英雄，销磨嗟未歇。","我亦失路人，同声一呜咽！"]},{"t":"过通霄路偶眺","f":"五言古诗","c":["波涛接远天，沧海接平田。","蒲帆片片飞，平地有流船。","举头东北望，海面高于山。","山巅视海浪，如望山上泉。","浪平水深黑，浪涌如雪白。","千丈若长蛇，奔驰银练色。","晴空无片云，下垂如笠泽。","行人惴惴危，海山一线隔。","到此万象卑，汪洋在咫尺。"]},{"t":"老衢崎","f":"五言古诗","c":["盘路赴蚕丛，上岘豁平场。","下临渺无际，远树但苍苍。","蝘蜒势千里，暝见东南冈。","西尽沧海阔，东去乱山长。","一线红泥坂，深谷散牛羊。","谷底有耕田，井密如罫方。","人家万松里，岚翠环四傍。","长飙起天末，屋古斜照黄。","登临极平楚，云物入微茫。","直北多关山，巉绝枕重洋。","此去路途广，车马似风樯。","暮霞半空落，断崖丹赭张。","北客驻遐眺，险尽喜康庄！"]},{"t":"红山崎","f":"五言古诗","c":["危云树末生，急客云中行。","崚崚千石磴，俯瞰深溪清。","万翠攒眼入，一红拍崖平。","疏林夹流水，十里一镜泓。","言是夏秋际，远山露列城。","万井积邱垤，百峰互阴晴。","登高望遥阜，想见官军营。","忆昔甲申初，此地防夷兵。","烽烟倏忽灭，耳有胡笳声。","今来开道路，遍志轮蹄程。","不久铁车过，平地殷雷鸣。","岩谷忽破碎，山海一楸枰。","我自催鞭去，秋风马首轻。"]},{"t":"中沥早路","f":"五言律诗","c":["山容隐晓雾，不见山头树。","西风早行人，浓浓青草露。","十里烟云开，日色前村护。","征车一梦中，山鸟啼无数。"]},{"t":"林烈妇行","f":"五言古诗","c":["明月在天中，能圆亦能缺。","清光不可磨，千古常皎洁。","烈妇在人间，慷慨立奇节。","青如涧中松，白如山中雪。","哀如夜乌啼，泣如杜鹃血。","夫婿方荡游，灯前苦陈说。","上堂拜舅姑，喜妇明且哲。","出门汲瓮提，入门芣苜襭。","劝郎攻史书，勿为纷华悦！","郎出朝看花，郎归夜踏月。","倚门待郎来，低声拓门闑。","问郎何所往？","春风易消歇。","问郎何所思？","铜镜易华发。","郎意云如何，得毋妾言聒。","唤郎犹未醒，谁知成永诀！","一病遽恹恹，中肠已惊怛。","郎魂何处招？","妾忧何时辍！","上天愿同行，入地愿同穴。","徬徨视女儿，「呱呱」苦难割！","米炊虽云巧，丝绣亦云拙。","无以养姑嫜，辗转徒苟活。","中夜起徘徊，殉夫志已决。","唤儿与姑眠，儿饥姑餔啜。","抱女与他人，未言声呜咽。","儿嬉不恋母，女殇我心恝！","茫茫天地间，此情难断绝。","妾心匪云石，妾肠匪云铁。","有如捣芝兰，成膏香不灭。","有如断莲花，成寸丝不折。","门外雨凄凄，帷边风切切。","灯光夜忽青，衣篝火不热。","一死谢所天，玉环与金玦。","园中花断肠，笼中鸟结舌。","吞药虽云亡，言之有馀烈！","呜呼泉下人，尘埃不可蔑！","相逢定无惭，何必臂盟齧！","巍巍望青山，磷磷立石碣。","贞风在何处？","高风万古埒。","坟前草青苍，坟后水凛冽。","山移石可转，斯人不可蔑！"]},{"t":"杂怀诗三十首 其一","f":"五言古诗","c":["生落古人后，忽作古人想。","古人在当时，谁知生景仰！","同居天地中，成材在所养。","宁为拙而直，勿为巧而枉！","常存不朽心，骨干自英爽。","春秋相循环，荣枯互来往。","自立坚不移，阴阳任消长。"]},{"t":"杂怀诗三十首 其二","f":"五言古诗","c":["自命贵不贱，持躬贵能约。","一侈百病生，江河为枯涸。","所以致远人，明志于淡泊。","穷苦亦可安，何事不可作！","措大寒书生，一身系民瘼。","读史怀名贤，高风在藜藿。"]},{"t":"杂感五首","f":"五言古诗","c":["我有成连琴，泠然出古音。","天风吹海浪，云外水沈沈。","一弹再三叹，感人意良深。","既有千古调，岂无万里心！","求之形象间，渺渺不可寻。","谁为相和答，沧海老龙吟。"]},{"t":"到北投寄兄","f":"五言古诗","c":["健足佩书囊，奚童负行李。","攀跻数仞峰，褰涉半溪水。","随云入远村，望树问墟市。","回首辨家乡，不见鹿溪涘。","虽隔一重山，已过五十里。","息驾竹林中，迎接主人喜。","遥拜先生尘，来脱先生履。","款客山人风，肴佳酒亦旨。","深树开讲堂，明窗列净几。","此间虽云乐，门闾老母倚。","已著孟郊衣，空致仲由米。","重累我仲兄，盘匜一身理。","忆昨欲别时，兄怀有忧只。","「去岁痛昊天，「蓼莪」哀未已。","今当季子行，家庭人有几」！","闻兄此一言，惆怅不能止。","但道咫尺天，朝发夕可抵。","勉强拜庭闱，皋此拥于此。","日入西山崖，日出东山里。","人在两山间，吾家在何许！","举头看云飞，回头看云起。","遥想吾家中，有人怀季子。"]},{"t":"杂诗二首 其一","f":"五言古诗","c":["我有一卷文，奇气吐氛氲。","清涌沧江水，高凌华顶云。","追古或不及，矫时已不群。","谈笑无千载，詑叱无三军。","风流可自足，不数公侯勋。","他日传名山，或亦俎豆尊。","韦、杜富贵儿，挥霍日酣醺。","楼台环紫帐，声色酗红裙。","旨哉昌黎言，此辈如聚蚊。","诗书滋味佳，膻臭不可闻。","我愿以风雅，澡沐日三薰。"]},{"t":"杂诗二首 其二","f":"五言古诗","c":["我有四壁书，宛委神仙居。","俯仰千古事，至乐不我如！","翱翔振金玉，罄咳鸣琼琚。","时或求古义，沧海钓鳌鱼。","时或列陈编，庙堂布璠玙。","咀嚼有馀味，吐纳凌清虚。","堪叹阿堵物，尘浊累累储！","王戎身自鄣，守之辄盈车。","一旦邯郸醒，大梦失华胥。","何如罗万卷，百城拥有馀！"]},{"t":"游侠篇，赠林君拱西","f":"五言古诗","c":["我有不平事，君有游侠风。","相逢易水上，与君道隐衷。","忆昔负意气，结交杯酒中。","君既遭家变，我正哭途穷。","销磨名场里，音问屡不通。","去年君来访，喜君气如虹。","今年君复过，劝君理旧功！","谁知别君后，遇暴折我躬。","君为我感愤，慷慨欲从戎。","感君意气重，肝胆古英雄。","喑呜风云壮，抑塞天地空。","宝剑切切鸣，光芒照眼红。","遇雠逝不避，利刃试新砻。"]},{"t":"客处见月有怀","f":"五言古诗","c":["一片青天月，晖晖五十里。","东出玉山峰，西到鹿溪水。","鹿溪东南楼，乌啼人夜起。","借问月来时，可照高楼里？","经秋露泠泠，曾否怨游子？","汉迥长空白，云飞夜色紫。","山断地相连，云头与云委。","况复月有情，照此复照彼！","今霄见月心，持归问予美。"]},{"t":"秋咏十二首 其一","f":"五言古诗","c":["我心忧如何，西风起庭柯！","朝下洞庭叶，夕吹洞庭波。","洞庭在何处？","沧海接黄河。","愁思从中至，日月速羲娥。","事业不一成，春秋空经过。","幽怀何所适？","散发晞阳阿。"]},{"t":"秋咏十二首 其二","f":"五言古诗","c":["独自出门去，忽忽不知处。","恍若得所思，旋觉无所与。","鱼鸟起寸心，天渊入吾虑。","举头得所爱，青山露林櫖。","斜照含西峰，夕色误朝曙。","胸次忽澹然，斯意谁与语！"]},{"t":"书堂听读","f":"五言古诗","c":["我无车马客，亦乏丝竹情。","虚堂听读书，四壁金石声。","秋风九霄外，常有黄鹤鸣。","噌吰互相答，露下天地清。","人间尘俗耳，一洗笛笆筝。","时闻吟李、杜，沧海吼长鲸。","时闻哦韦、柳，雪竹引银笙。","琅琅诵坟典，天风吹琼英。","读书有馀乐，何必轩冕荣！","独存千古意，可以语诸生。","「书中求大义，勿为泥功名」！"]},{"t":"向林十郎峻堂乞酒","f":"五言古诗","c":["天上有酒星，地下有酒泉。","清价同风月，欲买不用钱。","天梯与石层，往酤苦遥悬。","君有步兵厨，近在水云边。","鳌呿百斛浪，螺擎十丈船。","我亦非醉汉，思之偶流涎。","敢作陶潜乞，呼童擘锦笺。","乞食不乞酒，我为陶公瘨。","愧乏八斗才，斗酒无百篇！","能饮亦能咏，我生爱青莲。","论古无其诞，学醉无其颠。","慎勿相嘲谑，呼我为酒仙！"]},{"t":"茶肆女","f":"五言古诗","c":["山头采茶枝，店前拣茶叶。","女儿对门居，玉臂相交接。","一群如围花，双队成飞蝶。","腰携筼筜篮，手开湘竹箧。","拾茶垂纤指，评茶舒笑颊。","轻重与郎量，往来拖绣屧。","我叹拣茶娘，空自著罗裳。","一身虽云丽，徒为他人妆！","古王敦风化，家家学采桑。","采桑不采茶，女儿长在家。","采茶不采桑，寂寞女儿箱。","女劳不思淫，天上犹七襄。","谁为课豳图，山槲栽满墙？","舍末而求本，衣被在一方。"]},{"t":"海上遇风即事","f":"五言古诗","c":["枕上波涛鸣，水底蛟龙泣。","卸帆一梦惊，疑有狂澜入。","忆昨驾船初，浪平风习习。","天高动星斗，潮涌随呼吸。","直棹澎湖沟，遥望虎山立。","秋信中流来，北风一夜急。","浪头拍太空，鳌山高岌岌。","漰湃舟人呼，声与浪鸣悒。","鼓荡随罡风，忽向海湾集。","回视天色明，万变俱收拾。","乃知险阻间，随处可安戢。","乾坤亦幻然，江河吾且挹。"]},{"t":"福清路过郑介公故里","f":"五言古诗","c":["读史怀监门，爱君伟丈夫。","但请苍生命，不惜微臣躯！","伏阙陈谤书，如闻君疾呼。","意气过石介，岂为激烈乎！","一朝君命下，贬谪在江湖。","高风自千古，臣心足不孤。","后人思古谊，立碑在前途。","曰侠、诚义侠，名字不模糊。","岭头有松柏，路畔有苇蒲。","我过君故里，想见流民图！"]},{"t":"沪尾晓望","f":"七言古诗","c":["三面青山一面水，一山云霞连海底。","人家半在画中看，结水为邻山为市。","我来此地欲登舟，风信迟人二日秋。","昨夜月明船上望，碧天如水入云飞。","水气腥臊船气热，轻移小艇岸傍朅。","雨送海风入艇凉，半夜归潮两岸齧。","潮头已落岸头高，晓天曙色鸣波涛。","帆樯尽在日中悬，日出峰容处处多。","峰头犹含昨夜雨，苍崖翠滴浓于乳。","高从东岸望汪洋，远天树树青可数。","今朝喜得饱眼看，潇洒不知行路难。","地经百里风景异，归向舟中话故山。"]},{"t":"九十九峰歌","f":"古风","c":["乾坤奇气磅礴布，东南海岱巨灵护。","坼地擎天一臂撑，九十九峰空际露。","一峰摩空一峰从，空中密排青芙蓉。","森然突兀放玉瓣，朵朵太古烟云封。","有时风云气拂郁，剑锋如从指边出。","骈列巨刃倚天扬，鬼斧神工出旋没。","丹赭晴霞捧赤城，照烛炎洲明复明。","芒棱四吐如怒火，炙天不热天亦惊。","羲和日御行不得，重轮欲度便倾侧。","返照扶桑神鸟迷，倒影沧海蛟龙嚇。","云出如拥蚩尤旗，摇曳云头云不移。","三十三天星斗动，前峰、后峰相奔驰。","前峰、后峰作人立，或俯、或仰、或不及。","中有一座鲁灵光，次第肩随分等级。","我欲与之成百人，风雨未化蓬莱身。","欲求女娲补天石，补此一缺归陶甄。","山灵告我无庸补，大块有时缺抔土。","留此一角后人看，海山千秋与万古！","我闻中原九十九，曲河千里、百里为一波。","京师九十有九淀，一淀一薮如江沱。","天地山泽必有偶，斯峰因之变嵯峨。","又闻衡山九向有九背，一转一面成一态。","斯山崴嵬互阴阳，面面望之生光怪。","西蜀奇峰与此同，岛屿无此青玲珑。","去岸二十一万里，熬波浴日东海东。"]},{"t":"行路难","f":"楚辞体","c":["虎可驯兮龙可攀，石能渡海舟登山。","尘途咫尺不可过，世人惟有行路难！","北风白日天地阔，荆棘忽生顷刻间。","蓬莱弱水千万丈，人情变幻为波澜。","听我歌，行路难。","壮士徘徊何所往？","拔剑斫地一身宽。"]},{"t":"乞酒后再借书，与林十郎","f":"古风","c":["古人读书下以酒，胸中云梦吞八、九。","我今爱酒佐以书，举杯好开谈天口。","与君乞酒兼乞书，一编酒难还赵书。","不然倘能为我浇磊块，送归君家百尺楼上悬。","海内梨洲有述作，一部「明夷待访录」。","大名久已雷贯耳，偶睹应能蒙刮目。","名山五岳不能游，奇书一览当九州。","酒兴若浓狂歌起，放声一读天地秋。"]},{"t":"国姓涛歌","f":"古风","c":["鲸鱼跋浪沧溟里，岛屿无云雷声起。","波涛澎湃天低昂，气满尾闾飓风止。","千秋万古常喑呜，自是孤臣心不死。","孤臣有谁气拍空？","明人姓郑、名成功。","唐王赐与国同姓，天荒地老开鸿濛。","昔日中原纷战骑，为鹍、为鹏风摩翅。","英声直震大江南，钱塘铁弩三千避。","海枯不见孤臣心，潮落常满英雄泪。","泰山横流不能齧，咤?空有冲霄志！","归来厦岛天无光，地窄不足供徜徉。","宗悫长风万里浪，回头东海望炎荒。","喝石可渡无巨浸，投鞭可断无汪洋。","骑鲸直入鹿耳门，海若辟易湘灵奔。","波浪风云生指顾，鳌柱如山日月吞。","蜑水蛮乡拔荆棘，三十六屿澎湖侧。","岛中忽现蜃气城，海外自成蛟龙国。","喘息不觉生雄风，当时早已气如虹。","天倾欲将一木拄，时携匕首摩苍穹。","划断鸿沟不纳款，欲与华岳争累卵。","忽呼渡河宗泽薨，此恨填海海难满！","秋风喷礴作洪涛，忠臣气比秋风高。","唏嘘千里皆黑色，翻腾万籁为怒号。","日出扶桑不彪炳，龙蛇浮沈大力猛。","如山、如雪挟船飞，海人谓是「长鲸影」。"]},{"t":"银","f":"古风","c":["洪垆大冶不鼓铸，日本之银天下布。","团圆握之不盈把，易取货物纷无数。","光芒宝气在腰间，不畏饥驱不畏寒。","刓尽廉隅争资借，关津不惮行路难。","不胫而走似铜凫，贾人坐拥千金躯。","圆轮径寸利涉远，鬼物不敢萌揶揄。","中国银山高崱屴，利源乃让东洋国。","鬼夷挟此得自雄，孰使流通无壅塞？","古来为国收利权，太公乃有九府圜。","中华久不为此计，取利于民民日艰。","东洋幅?本穷窘，中国大度来蛮蠢。","失笑辄看龙子银，幕面特书「大日本」！"]},{"t":"题海外蓬莱图","f":"古风","c":["大海波涛断复连，撑起炎洲半壁天。","沧溟路绝风云渺，鸿濛世界开人烟。","安得泰山一枝笔，写作奇观空际悬！","悬之咫尺有万里，大块无垠水无边。","我思盘古凿混沌，斧凿到此生劖镌。","又思共工触不周，触柱为山缺半偏。","山头日月自昼夜，山下沧海自桑田。","奇气郁勃凌中土，独回万水为西旋。","上作赤乌窟，下作蛟龙渊。","中包小蓬壶，珠屿水中圆。","又有玉山可望不可即，日出插霄玉柱鲜。","回望燄峰九十九，烛地熏天火欲然。","一热、一寒分冰炭，八潼关里雪绵绵。","台地无霜、无雪年复年，山灵狡狯弄使夏泽坚。","北极何处鸡笼屿，遥与香炉烛峰相清妍。","灵气鼓荡山河动，鹿耳门涛摇星躔。","秋风万仞磅礴吐，鲸鸣欲簸昆崙颠。","奇奇怪怪无不有，敢问十洲、三岛谁真仙？","当年徐福不可到，未将地与秦人传。","留之一千万万日，张槎始来天上船。","船中载得王维笔，画到蓬莱笔不全。","落笔万丈惊五岳，纸上时有烟霞穿。","求之愈即去愈远，仙山疑在化工前。","我居蓬莱乾坤惯，依稀认得秋毫巅。"]},{"t":"述事，与乃营书后","f":"古风","c":["历尽巉岩经沧海，一波未平一波骇。","经尽波涛涉崎岖，一崄未终一崄踰。","我行已过千山万水路，胸中空有明月珠，眼中空有方壶图。","回头试说风尘事，疲于津梁否耶无？","初入鏖战荆棘里，心似荆卿怀利匕。","怵惕谈笑两有馀，水濡火热气不靡。","下场蹭蹬涉关津，风云泥涂在一身。","方把心情惊爨尾，又将况味尝劳薪。","归来秋风飒飒鸣，耳边犹有波浪声。","无端霹雳空中下，报道孙山名下名。","自是文章憎命达，利锁名缰苦难脱！","雷焕剑藏十年光，卞和玉受双回刖。","萧萧飕飕寂静间，君书寄来自前山。","大罗误传青鸟信，激水若怒蛰龙蟠。","君遭与我俱落拓，君更穷途受飘泊。","人生无数翻覆事，吹箫莫唱「声声错」！","聪明本与命为仇，华亭老子倒骑牛。","想其睥睨人间世，习见积薪颠倒成玉邱。","君不见驽马立仗在御阶，骅骝骐骥骨如柴。","又不见野雀献瑞上玉堂，麒麟鸾凤惊不祥。","笑余枉学屠龙技，技成三载无所试！","与君相倾杯酒中，酒酣一座生雄风。","与君相话夜灯下，灯残千里知音寡。","去日得交张汝南，把臂共发千秋谈。","汝南已死不可作，辄作栖风苦雨不可堪！","琴书几席时相贶，雄心因之减二、三。","此意惟君得深悉，今日徘徊无所质。","一纸遥寄王郎歌，明日云山相对出。"]},{"t":"寄澎湖许芬四首 其一","f":"古风","c":["君居澎湖我台湾，相隔一海复一山。","去日相晤南闽关，今日相逢云漫漫。","安得沧海生鳌柱，为君朝往暮复还！","沧海深，不见底。","凭藉片帆送一纸。","君倘能再来，何论重重有云水！"]},{"t":"寄澎湖许芬四首 其二","f":"古风","c":["文字相逢有前因，形虽未交神先亲。","君昔来鹿渠，犹未识君为何人。","读君之诗见君真，明日闻君起行尘。","风为客，月为邻，至今怀之水粼粼。","今秋访我闽闱里，抵掌矮屋生阳春。","乃信杜公不欺我，文章有道交有神。"]},{"t":"寄澎湖许芬四首 其三","f":"古风","c":["分道出闽天，不复睹君面。","归路茫茫阔于海，归心人人疾如电。","回首遥望澎湖峰，一笠云垂渺不见。","远寄新诗写性情，秋风木落飞片片。","问君在何方？","浪如山，波如练。"]},{"t":"寄澎湖许芬四首 其四","f":"古风","c":["一雷空中起，痴龙昂首视。","元珠知见遗，帖耳沈于水。","犹望同群有飞升，不自持竿亦同喜。","千佛名经不见君，想是齐落恒河里！","此间无数古今人，沈没其中等微尘。","惟有豪杰能自立，时吐光芒惊鬼神。","愿君手持一寸铁，上摩日月下霜雪，鍊作干将长不缺！","天地有浑沌，此器不磨灭。","他日相逢将剑说！"]},{"t":"崇武观渔歌","f":"古风","c":["如山波涛蔽天际，叶叶舟为浮波系。","千樯万网烟水间，网得大鱼高于山。","以鱼钓鱼巧作饵，鱼傍舟行不知避。","港湾鱼小海鱼肥，随潮暂远暂忘归。","日暮风云四海黑，昏迷天地波无色。","渔人由来海为家，东西南北亦嗟呀！","泼刺鳣鲔与鲿鲨，行行不但摸鱼虾。","舟头时有鳌梁度，橹为摇曳波心路。","云中或见龙爪张，舟为回避向汪洋。","停舟偶到乌龟屿，千尾万尾纷纷举。","驶帆远过澎湖沟，大鳞、细鳞水际浮。","出海小舟傍大舟，小者打桨、大者流。","岁岁为渔逐海利，直从闽海到温州。","出没烟波忘餐饭，天寒一饮当穿裘。","雨中蓑衣兼箬笠，群鱼结队争呷唼。","舟人雨中为畏途，渔人雨中为利涉。","冬尽岁残不归来，生成海上事游猎。","大鱼为盐小鱼乾，天青日赤鱼满滩。","小鱼腌脍大鱼刓，割鱼曝炙肉团团。","网得鲂鱼味尤美，削肉渡海作甘旨。","春晴放棹始回归，归到家中妇子喜。","贩鱼过海收厚利，愿君莫厌风波靡！","君不见西夷捕鲸碧海中，冰山万仞无旭红。","火轮冲冰或粉碎，牵出长鲸高隆隆。","又不见夷人捕鲸卖鲸油，烛龙下照夜不幽。","海上烟樯日磅礴，任公大鱼三载求。","人生牟利忘蹭蹬，地上风波尤凌竞。","我来崇武观打鱼，渔人起我望洋兴。","渔人低头听我歌，我歌月色满山多。","山下潮声夜深起，回望台天淼淼水。"]},{"t":"罗山寄张茂才汝南","f":"五言绝句","c":["一尊前日酒，鸾鹤又离群。","看看来时路，青山断白云。"]},{"t":"登楼即事","f":"五言律诗","c":["一望苍茫外，长天白鸟过。","潮回江、浙远，船舶粤、闽多。","岛屿连沧海，云霞接薜萝。","月明惊夜梦，枕上吼鲸波。"]},{"t":"秋望有悼，为汝南作","f":"五言绝句","c":["何处故人颜，云间又水间。","东南秋色尽，不忍望罗山！"]},{"t":"渡海过犬山","f":"五言律诗","c":["浩淼虚为际，乾坤入望愁。","海随山异色，地与水分沟。","日月双轮迅，云天一笠浮。","飓风吹不去，千里过横流。"]},{"t":"八卦亭偶望","f":"七言律诗","c":["海天无际暮烟浮，一线秋空数点愁。","车马往来南北路，估帆向背东西流。","青山出水围城郭，红树穿云压市楼。","偶欲放歌亭下去，岚光月色暂勾留。"]},{"t":"拨闷四首","f":"七言律诗","c":["潇洒风怀杜牧之，几回猛省读书时。","不关造化閒花草，无补民生细茧丝。","竟体芳兰骚客意，销魂金粉美人辞。","聊应洁癖将蝉比，饱露餐风最上枝。"]},{"t":"场中题壁八首","f":"七言绝句","c":["插脚红尘廿四年，泥蹻释后欲登天。","蓬莱弱水三千路，鳌背曾经海上船。"]},{"t":"秋日登临偶兴二首","f":"七言律诗","c":["仰首天边暮色低，征途欲尽万峰齐。","云从南出风从北，山自东来海自西。","日落忽逢鹰独起，草枯何处马频嘶？","深篁大泽无人过，谁向狉榛事鼓鼙！"]},{"t":"遇李石鹤孝廉赋赠二首 其一","f":"七言律诗","c":["三生石上證前因，交道文章信有神！","脱略形骸千古量，相忘辈行一朝亲。","竟誇海岱逢奇士，自是闽天出晋人。","此去长安万馀里，柳袍应拂帝京尘。"]},{"t":"遇李石鹤孝廉赋赠二首 其二","f":"七言律诗","c":["天涯不用共温存，此去文星照帝阍。","别我看花春逗路，送君渡海雪浮尊。","华亭听鹤江南地，燕市驱车蓟北门。","得意未应高步上，愿留龙尾待追攀。"]},{"t":"台湾土匪纪事","f":"五言古诗","c":["立国有大纲，时势在提挈。","太阿一旁落，皇图四崩裂。","去年□□侵，人心徵固结。","鲁殇执干戈，并儿磨箭筈。","处处争守陴，机械为敌设。","忽闻和议成，金瓯割数缺。","台地在割中，义士皆卷舌。","倾心事皇家，见摈得金玦。","同袍有素心，仇愤无由雪。","况隔天九重，仰首望长觖。","自此人心离，短气失豪杰。","日暗浮霾生，狐狸出躠蹩。","匪人坌牛毛，郊野为草窃。","本非揭竿徒，亦异乘机哲。","不过如骄儿，无父出为孽。","所以民情涣，实由国柄折。","我思此时初，大势未遽跌。","何以枢府臣，国体此嫚亵！","竟将中兴基，欲以偏安列。","柱触共工头，碧呕苌弘血。","我抱杞人忧，闻之肠为热。","路上凄风来，长痛回车辙！"]},{"t":"溃兵弃地纪事","f":"五言古诗","c":["芒芒赤县州，六合拱神京。","蛮夷归鞭笞，殷武善徂征。","维时士用命，拘原尽力争。","自从宣宗季，恬嬉为敌轻。","乙酉胜法兰，弃藩与行成。","是以朝鲜事，倭人首败盟。","今皇奋威怒，志在吞鲵鲸。","谁知势决裂，到处无坚城。","一退鸭绿江，遂丧凤凰营。","辽东与山东，岛屿任纵横。","岂无金汤隘，尚有铁甲兵。","汪、黄主枢省，陵寝迫震惊。","积弱已不振，一蹶何时兴！","我思所由来，兵将不同诚。","济危无韩、岳，上下久离情。","暌隔致蛊否，未有不分崩。","可恨行阵士，赴战各贪生！","阃内谋不施，阃外士无能。","四郊多垒日，孰为奋请缨！","将相今何用，气象空峥嵘！","入辕开府坐，出门除道行。","临民事赫奕，遇敌屏息声。","坐谈抒奇略，议和以为名。","蹙地日千里，不知辱与荣。","我欲哭秦师，葬汝白起坑。"]},{"t":"叛将献船纪事","f":"五言古诗","c":["国家倾帑藏，百万具一船。","上置穿山炮，下置激火轮。","熬波出巨浪，蒸气成黑云。","海上习攻战，拟扫狂鲸氛。","寄之不得人，如山强负蚊。","今春威海卫，十船成一群。","将者丁汝昌，巾帼而从军。","怯懦不成夫，反侧以事君。","求降附敌人，颜厚徒逡巡。","十重如铁甲，岂谓铁军门！","平生事横行，一旦竖降幡。","北洋为夺气，此罪海难论！","其人服毒死，狗贱何足闻！","不行连坐律，国法何由均！","尾闾狂波泻，沧溟白日昏。","峨峨海上舟，竟使巨鱼吞。","地上称利器，铁车登昆崙。","海上称利器，铁船荡乾坤。","覆辙乃如此，无人器奚云！","枉自开船厂，万亿掷金银。","四海竭脂膏，仓卒付沈沦。","枢府皆屏息，忧惧动至尊。","我谓无海战，陆守势仍存。","割地势乃坏，痛哉海沄沄！"]},{"t":"冬至日家祭有感","f":"五言古诗","c":["陆游家祭日，不见王师来。","告考无喜信，一恸泣蒿莱！","肃肃孙子曹，拜跪趋堂阶。","年少无忧思，何知事可哀！","我在沧桑内，零泪滴苍苔。","仲冬风雪下，阴气横九垓。","乾坤已荒老，天地满尘埃。","为时经易岁，人事长悠哉！","生命既不辰，自甘为弃材。","行踪羁远海，坟墓守南陔。","富贵非吾愿，溷迹于舆儓。","时乱身愈重，韬晦复何猜！","载拜捧觞豆，莫上黄金台！"]},{"t":"咏怀四首 其一","f":"五言古诗","c":["九十九峰天，千秋缺一角。","万里金汤城，乍为寒烟剥。","沧海微尘扬，黄河末流浊。","谁知桃源中，乃先变汉朔！","我有足与缨，咸池不足濯。","天意与民心，尚皆在冥漠。"]},{"t":"咏怀四首 其二","f":"五言古诗","c":["托迹尘灰中，萧然无一事。","蛮触自纷纷，高闲见余志。","山海一年间，■偬风景异。","出门何处行，途有蕃马辔。","马嘶知俗殊，风鸣识秋至。","堪叹日暮天，变态如斯易！"]},{"t":"吊郑延平","f":"五言古诗","c":["天尽接海水，突兀岩岛横。","至今风雨夜，时闻人马声。","层波出洪啸，互答长鲸鸣。","痛哉骑鲸人，一去水泙泙！","拓地辟荆榛，绣壤错经营。","志气无六合，虎视蛟龙争。","千秋鹿耳门，风静怒涛生。","废楫在海底，曾至金陵城。","至今吴、越间，耳震孙郎名。","千丈晴霞出，犹疑为旂旌。","遗志不得伸，海大为不平。","舆图归一统，庙貌褒忠贞。","昔年游赤崁，春秋礼齍盛。","閒登望海台，兴废几时更！","彷佛崖山麓，孤臣痛哭情。","我朝君犹恨，况为外夷并！","古城有遗址，白日穴鼯鼪。","阴风扑人面，大厦重见倾。","郑公今不作，当世谁支撑！","神州竟中绝，无复古簪缨。","望风长叹息，头发空鬡鬇！"]},{"t":"怀蓝襄毅","f":"五言古诗","c":["海疆起戎马，七日陷全台。","争望王师至，慷慨蓝侯来。","舟楫上鲲身，风利布帆开。","指挥悉如意，澄清见将才。","小丑不足数，大敌何有哉！","海岱千里间，事后薙蒿莱。","最难戎幕里，帷幄储真材。","鹿洲蓝先生，文治佐鸿裁。","至今海山际，文章达上台。","谁知陵谷事，扫地如尘埃！","怀古心滋戚，感时心愈哀。","当初凭眺地，处处生莓苔。","三年兵燹内，楼舍为煤炱。","礼乐亦已废，坛庙况又灾。","鲁国有诸生，抱器耻徘徊。","招魂望漳浦，酌酒祭一杯。"]},{"t":"招隐六章 其一","f":"五言古诗","c":["古人轻荣华，脱组山中去。","常恐世人知，白云最深处。","我本谋世人，何慕猿鹤御。","祇因天地非，不觉尘途淤。","商山有紫芝，采之终朝茹。","卧听寒泉鸣，起视霜天曙。"]},{"t":"招隐六章 其二","f":"五言古诗","c":["入山一以深，遂生古薇蕨。","采之无所贻，食之甘如鳜。","孟春草木多，生机常泼泼。","回首望乡闾，棘荆生庭闼。","居者罹忧患，去者为蹙额。","何为溷世人，盗泉以疗渴！"]},{"t":"招隐六章 其三","f":"五言古诗","c":["章甫适越邦，衣裳居裸国。","虽不相往来，未免相疑惑。","南山有雾豹，非时长晦匿。","知几有哲人，焉可被时识！","时世日以非，浮光日以昃。","故里等殊方，瀛海同荒僰。","去去勿复迟，前山足登陟！"]},{"t":"检疫叹","f":"五言古诗","c":["睢盱海东国，其俗与人殊。","暴殄待人物，行与疫鬼俱。","检疫入人家，横将老幼驱。","刀圭及针药，刲剖死人肤。","云欲免传染，须焚死者躯。","到处人惶惶，有病应受俘。","不许在家养，病院非虚拘。","或有讳病人，一死如偷窬。","亦有无病人，羸黄以病诬。","封守死者家，禁锢七日踰。","彼谓行善政，防患无不孚。","将彼作疠看，自是愚人愚。","愚人死犹可，检疫呼杀我！","疫死柔于水，检死暴于火。","水火两无情，万物为么么。"]},{"t":"猛虎行二章 其一","f":"五言古诗","c":["林际腥风来，茫茫天地黑。","路人皆走藏，喑呜群动息。","不知何妖魅，有牙兼有翼。","或疑为天狗，化作狼与蜮。","攫人靡孑遗，充作饥肠食。","食人亦何求，聊为造化贼。","朝出吮人皮，夕作齰人腊。","路旁蝇蚁盈，纷横肩与骼。","邱山何累累，云是死者馘。","一见猛兽蹄，行人丧精魄！"]},{"t":"猛虎行二章 其二","f":"五言古诗","c":["城邑人所居，于菟聚其处。","髑髅纷满前，攫人逐人去。","士女觳觫行，纤纤倍忧虑。","咆炰入市廛，磨牙为刀锯。","搏噬无瘦肥，跳踉无餍饫。","室有死人头，途有殷血淤。","不闻啼哭声，有声将来觑。","岂真天地昏，欲将人类除！","且储弓与刀，禽生勿犹豫！"]},{"t":"望蓬莱山有悼","f":"古风","c":["海上蓬莱山，自是神仙闼。","琼瑶削作台，琳琅排作阙。","仙人凌云出，望之心目豁。","谁知阅沧桑，仙山亦轇轕！","沦汨苍茫中，滔滔海水阔。","残破不可知，中流剩一发。","日出照深渊，黤?见髣髴。","既作妖螭居，复变鬼狐窟。","人类想无存，岧峣枯髅骨。","时或洪流涨，浮沈见凹凸。","可叹蓬莱峰，年年海底没！","海底何所有？","鼋鼍来窸窣。","海中何所见？","鲸鲵弄溟渤。","海屋添筹翁，声噫气复郁。","日与鬼蜮邻，频年无一物。"]},{"t":"书后柬张汝东","f":"五言古诗","c":["昔年哭君兄，君侄才弁髦。","别来今几载，君侄如我高。","门前松柏树，垂垂添须绦。","伊昔倚松人，墓草长蓬蒿！","言之心为摧，泪比鹿门涛。","当时同应试，气欲吞巨鳌。","岂料到今朝，末路如斯遭！","君兄已不知，君泪应滔滔。","生离与死别，秋风为怒号。","时事况已矣，身世随鸿毛。","背中无六翮，安能万里翱！","死者在黄泉，有时共号咷。","剑缺徐君树，笔挫班超毫。","凄风习习来，仰首望星旄。","不见故人面，常想故人袍。","倘见君兄子，勖之古贤豪！"]},{"t":"暴雨险涨纪事","f":"五言古诗","c":["日没江河翻，狂涛天上泻。","急电催迅雷，冲飙万瓦下。","雨箭穿飓风，石壁不受射。","路人急奔豚，不知为旦夜。","道途水接天，无处认桥跨。","匉訇山石声，举目无完舍。","予坐读书斋，但见屋有罅。","积潦难出门，淋漓无枕藉。","三日见晴空，如囚得援赦。","开户逢行人，半多求屋借。","由来二百年，未闻此叹诧。","连村或水浮，沮洳无塘坝。","亦多付漂流，鸡犬人物化。","川涨陷邱陵，田畴没䆉稏。","屈指百里间，荒芜忽如乍。","窃疑造物心，年年不宽假！","疠疫与兵凶，更番成迭驾。","盗贼夷狄横，兼将奇灾嫁。","静思浩劫中，在在足惊怕。","盲风怪雨来，何敢生诅骂！","六月且披裘，时序无冬夏。","放怀作诗歌，泪随风雨罢。"]},{"t":"送梁子嘉先生归粤长歌","f":"五言古诗","c":["西风海上来，江湖秋已疏。","天涯远游子，日色冷菰蒲。","蒲帆天外去，忽忽浪花粗。","行客悲不已，远望绝平芜。","故乡在何处？","回首水云区。","岭南近如何？","未得一纸书。","衣锦滞他方，富贵亦唏嘘！","况为失路人，不如归乡闾。","我送先生行，欲挽先生裾。","先生昔来时，台海金汤如。","班生从戎幕，曾见海氛袪。","维时法兰西，遂为强弩馀。","兵气倏忽消，辐辏纷舟车。","先生半隐宦，拓地开菑畬。","台阳富山海，山人亦足鱼。","先生于山中，永以爱吾庐。","谁知浩劫兴，割地等商于。","欃枪无人扫，千里为邱墟。","先生攘袂起，有愤不得摅。","朝廷有子兰，枉哭申包胥！","仓皇戎马间，南北行趑趄。","越海去复来，囊橐无宿储。","不见汉衣冠，所遇多駏驉。","关津不易过，寄迹嗟籧篨！","当年华屋处，再过无人居。","伏莽时时起，十室九室虚。","沧海扬尘后，无复返其初。","先生长太息，决计问归途。","君家粤东路，地即古番禺。","亦曾遭英夷，夺去海膏腴。","伊昔林文忠，至死三叹吁！","有计不得行，谋国误奸诬。","虎门铸大错，筹策至今纡。","茫茫五虎洋，万国来揶揄。","汪、黄今再生，遗祸遍海隅。","粤海虽粗安，虢亡行及虞。","今日广州潮，轮舶环郡郛。","山海失岩阻，黔首其挛拘。","君归亦何乐，聊为妻孥娱。","我思祸乱中，素志不可渝。","祖生中流楫，气足吞羯奴。","西夷侮我甚，谓我无良图。","瓜分指中夏，囊括鼓咙胡。","我笑夷人眼，咫尺见糊模。","岂识中华势，衰乃盛之符。","君归求黄石，慎保千金躯！","见说粤西峤，胜、广已蠕蠕。","草寇启汉、唐，此岂为之驱！","可怜兵燹灾，到处无或殊。","君地与毗连，曷胜望苍梧！","滔滔郁林水，须虑走湛卢。","官军成铅刀，不足张威弧。","我辈何从计？","不禁碎唾壶。","时事且勿悲，请为君歌呼！","去年见君面，一拜识眉须。","嶙嶙耸傲骨，迥异风尘趋。","逢人辄面质，不为时俗谀。","诗文在正声，瑰异过璠瑜。","我读「钓龙歌」，高调入云衢。","稽康广陵散，不道今未无。","有作皆唐调，绝不为喁吁。","伤时生感喟，杜诗与泪俱。","平生复萧索，阅历貔生貙。","愧我非终童，未能弃关繻。","空送先生去，不共先生徂。","秋风吹远道，落叶客身孤。","东西马首瞻，怅惘失朝餔。","遥遥沧海上，帆片有云铺。","一去难复逢，望君眼亦枯！","粤山千万重，君去飞舳舻。"]},{"t":"再送梁子嘉先生三首 其一","f":"五言古诗","c":["十载寓台湾，四载经危乱。","寇氛及台南，行客中肠断。","故旧与新知，存者不及半。","先生亦且行，舣舟于海岸。","海有函谷关，鸣鸡度待旦。","回首望东洋，洋轮来汗漫。"]},{"t":"再送梁子嘉先生三首 其二","f":"五言古诗","c":["君入台南城，相逢无一识。","短衣脚不袜，衣垢面黧黑。","访旧过军门，阍人先作色。","及与刘帅谈，共争问消息。","往事那堪追，人去来何益！","徘徊异域间，不如复归得！"]},{"t":"再送梁子嘉先生三首 其三","f":"五言古诗","c":["昨日先生书，言归及秋馀。","今秋已将尽，难驻先生车。","凉风起天末，木落声徐徐。","沧海日已深，故园日已疏。","作客虽云乐，未若在家舒。","何以远送君，白云近所居！"]},{"t":"雨后述事","f":"五言古诗","c":["春深草木苏，万物思雨泽。","勾萌欲发生，原野资膏液。","连旬无雨云，生意咸欲息！","年来况歉荒，粒米等圭璧。","一金八、九升，携囊难告籴。","雨膏复不行，嗷嗷安求食！","去年徵敛苛，不念民饥色。","今春迫徵期，无地为逋客。","不知上天心，何以处苍赤？","此邦硕鼠多，民物皆不惜！","天苟为旱灾，彼且啖人腊。","时事无一堪，言之填胸膈！","昨夜闻迅雷，不觉喜跳踢。","天有爱物怀，一雨救穷阨。","大者如倾盆，细者亦滴滴。","可怜未多时，不及起枯塉！","水源乏雨滋，末流不洋溢。","慰情却胜无，此际可多得？","我作喜雨诗，农夫有忧戚。","救死尚未能，税敛来相迫。","安得兼雨金，万民皆悦怿！"]},{"t":"有所思，效玉台体十首","f":"五言古诗","c":["我读「玉台诗」，芬芳沁我肠。","诗人逸兴多，香草托徬徨。","芍药思渺渺，蒹葭水苍苍。","千古作寓言，美人在西方。","西方竟何许？","求之见荒唐。","昨云晤宓女，旋觉梦王嫱。","所居必金室，所倚必雕梁。","一鬟千万值，一身百宝妆。","我诗亦此意，意与美人长。"]},{"t":"在阿罩雾同林十偶眺","f":"五言古诗","c":["一路看山来，山尽是君屋。","翚革罗峰峦，清华湛水木。","入君书室中，琅环径重复。","沧桑存灵光，变迁忘陵谷。","与君为清游，亭台藏山腹。","登临望大墩，芜城蔽林麓。","炎峰接远天，夕阳满平陆。"]},{"t":"王君友竹索题简端","f":"五言古诗","c":["相闻不相识，日日望新城。","每逢北人至，辄询君姓名。","君家在何处？","迢迢新竹路。","忆昔承平年，驱车城外度。","可惜迟闻君，彼时未回顾！","一自丧乱初，始得君素书。","知君诗学好，展卷再欷歔！","灰烬兵燹中，播土扬琼琚！","伤心各悽恻，将诗慰离索。","卷里起秋声，中有胡笳拍。","陆公昔乱离，哀音鸣郁噫。","至今呼望帝，千载有馀悲。","杜陵不可作，愿君长咏诗！"]},{"t":"陈生丐题琴砚图","f":"五言古诗","c":["中郎绿绮琴，衰汉流沙漠。","米家海岳砚，宣和尤虏掠。","名士所宝储，乱世等残箨。","当日席上珍，此日泥中蓄。","子女与玉帛，同时填沟壑。","况是玩好间，何足铸金错！","莫怪名士身，自视常丑恶！","何来陈元龙，意气独磊落！","有琴不破碎，有砚不唾辱。","兵燹出劫灰，灵光存殿阁。","一弹再三叹，摩挲风云作。","不知是何世，高唱回风曲！","兴到走龙蛇，谁能为缚束！","逍遥閒中趣，几忘有荼毒。","照影绘为图，人苦我自乐。","我愿同之游，赏音看挥霍。","他日留名山，知有辽东鹤！"]},{"t":"座上赋赠林十","f":"五言古诗","c":["南风送君来，复欲送君去。","溪口茫茫云，山头重重树。","去年见君时，莺啼花满路。","今年君来过，落花乱无数。","麦秋风正凉，相逢各道故。","君今隐芦墩，为农老朝暮。","入山虽不深，避俗已得趣。","课芸即为诗，劝耕亦寻句。","种秫三十区，陶家备酒具。","竹林有阿咸，时来相亲附。","每于畎亩中，白云聚朋屦。","君诗学襄阳，令人生遐慕。","携家鹿门山，青年竟高步。","缔交我独初，谈心坦怀布。","昔日入中原，邮书当面晤。","航海去复回，屈身为井鲋。","功名付悠悠，不食甘匏瓠。","即今离乱馀，寓公随处寓。","云山异昔时，人物无孑煦。","鞭扑马牛忙，催敲鸡犬惧。","竭泽苦猎渔，挈瓶艰挹注。","读书最萧条，无以供租赋。","况又干戈年，时时求委输！","兵连与祸挐，乾坤纷鼓铸。","壮士孰为牺，吾徒皆守兔。","桃源不可期，栗里君小住。","今日偶逍遥，行踪冲罩雾。","迢递到鹿溪，轻车来如骛。","向余索诗编，吟声出韶濩。","理乱了不闻，忧乐复何顾！","相对两诗囚，书城搜积蠹。","高歌十宜楼，「南华」生解悟。","明朝送君行，报余须尺素！"]},{"t":"题施梅樵祖母像","f":"五言古诗","c":["台湾昔盛时，母家方繁丽。","爱子趋堂隅，名孙绕阶陛。","灼灼鸣珂坊，前儓而后隶。","结交刺史侯，豪宗开戟第。","母也居华闺，绮罗供娄曳。","林下夫人风，城中慕高髻。","富贵博欢颜，经营由贤裔。","如何原涉家，忽为尹君弊！","亡命走江湖，埋名局天地。","叹息酷吏威，顿使名门替！","母也居梓枌，闾日倚垂涕。","阅历及沧桑，流离满尘世。","洛市经战场，泰山作刀砺。","王母独崔岿，天孙为拱卫。","始觉皇娲年，崦嵫景未逝。","翼起有贤孙，簪缨又克继。","祖妣痛音容，丹青存髲剃。","昨日素车帷，汉仪备葬祭。","追远生孝思，慨僾写真谛。","想见君先子，黄泉含笑睇！"]},{"t":"外国保护纪事","f":"古风","c":["君不见山人委肉饲饿虎，空望?虎守门户？","急时篱下暂相依，终见攫人充饥肚！","又不见苑监驱狼牧羊群，一狼能使千羊奔？","弱肉强食既悬绝，系援凭藉何由存！","堂堂中国不自强，忍言扶持借西洋！","假令吴、楚保周、鲁，徒取戎狄笑禹、汤！","我思康熙、乾隆全盛时，彼时早已侈西夷。","詟伏天威供职贡，闭关屏绝无一辞。","飞车奇肱皆悚惕，呼毒古莽任鞭笞。","降至后人乃积弱，弱势非由力不足。","但夕苟延上下暌，遂使燕安生鸩毒。","文恬武嬉无所筹，有兵、有将如赘疣。","昔贤大法弃不用，西人机巧奚足收！","九夷八蛮迫宇下，四皇六帝王可假。","中华有气久不扬，今且灭裂无风雅。","强借兵威护吾疆，长使山川颜如赭。"]},{"t":"公医行","f":"古风","c":["东人以官来作医，生者、死者医不知。","推门入室验病人，瘦黑肥黄皆药之。","食药而死须湔肠，剖腹看脏浇以汤。","食药不死病在床，驱入病院身频量，以身短长量药方。","十人入院九人僵，僵者闻之火彭彭。","闻说台北路，健者出行弱者藏。","不知彼王为仁惠，老幼渡海人成行。"]},{"t":"公娼行","f":"七言古诗","c":["华人以娼为败风，东人以娼作奉公。","王家徵税夜夜同，公娼厅事明灯红。","插花盈头发一蓬，花布裹身舞氋氃。","贴腰作褥系腰后，人各一端摇玲珑。","比目交颈记点钟，无遮、无碍雌与雄。","从此烟花添故事，不须羞涩如吴侬。"]},{"t":"清洁行","f":"古风","c":["西人、□人重清洁，风景当前谁破裂！","洒扫庭除三尺能，何劳官吏鞭箠折！","中华此为奴仆事，外洋当作官箴设。","朝呼扫地愁马蹄，暮呼扫地怨车辙。","忽闻汹汹剥啄声，巷居妇孺啼呜咽！","閒来我过兵火场，粪土如山永不灭。","又尝看杀沐浴房，男女裸游同猥亵。","借问清洁人，谁如曳尾鳖？"]},{"t":"闻客述施孝廉仁思双妾殉节事有感","f":"古风","c":["东海扬波海水浅，纵跨双虹行亦蹇。","麻姑有憾方平知，大风吹海海难转。","天荒地老一身愁，况有雪霜随风卷。","儿女恨与英雄终，石烂海枯泪长满。","忆昨乙未丁苦辛，青衫红粉俱灰尘。","施君并挈西施去，一舸云烟远避秦。","谁知浩劫出儒坑，竟作人间一陈人。","世乱已拌名节轻，何期两美殉君身！","君之侠骨肝胆粗，家无䃫石掷樗蒲。","利刀时断纷缊絮，豪气能驱霹雳符。","挥金买得石崇婢，明灯净簟时相娱。","辛卯之秋折桂树，花枝复把黄金铸。","武昌有妓惜别离，新起朱楼藏娇住。","阿娇未煖玉楼中，忽然海上生悲风。","铁马金戈破空至，官军报道陷鸡笼！","维时我闻心亦碎，书生无从伸长喙。","君言当事能慨慷，时事已非出肝肺。","归来对泣有红颜，座上无声惨不欢。","见说携家亦航海，两美争先为凤攀。","七月七夕二日后，不堪回首望蓬山！","彰城既失君亦行，辽东有鹤去不还。","辽东有鹤去不还，三年君付一梦看。","蓬头婢子泪潸潸，吞阿芙蓉弃人寰。","谁道邯郸妾，学步不辞艰。","嘱子堂上婆，回死君怀间。","君不见坡仙谪去朝云决，少游死去讴者绝？","君并得之双玉玦，丈夫无成亦快哉，浩浩闽天长积雪！"]},{"t":"诗函报林十，适又渡海，歌以寄之","f":"古风","c":["去年烽火起，君去罩雾里。","雾山一一高，君视等鸿毛。","航海一去寻乐土，温陵旧是晋时浦。","晋人携家江畔居，当时亦避羯奴苦。","文物衣冠犹俨然，城郭襟海带云烟。","忆昔伧荒已千载，得君羁旅又三年。","今年台地烽偶熄，君潜渡海问田宅。","山川虽是景物非，疑忌之邦君遁迹。","得君诗函报君书，君已不滞回风裾。","一帆波起随急棹，四山月出空精庐。","望君在何处，天长迷海曙。","一纸搁山中，无由追日驭。","我向此邦依，何殊荆棘据。","闻君挈眷欲重来，叹息故巢难去去！","作短歌，小名署是「弃生」，甘执御。","从今富贵功名非吾知，惟望文辞诗卷人间著！","作诗与子且自吟，泪滴青山犹昔心。"]},{"t":"哀罗山","f":"七言古诗","c":["罗山坡陀撑不起，昔年汝南丧于此。","山头日出云悠悠，山下溪流石齿齿。","山水依然不见人，见山、见水情何已！","登高东望隔数峰，君家去我数十里。","望眼穷时暮霭生，是山、是云杂红紫。","遥想冲宇云山中，君居傍山有妻子。","愧我受君临终言，未能春秋时经纪！","复遭沧桑剧变迁，有子读书半途止。","国恨家常两不堪，寄书劝学近迂理。","君家书卷尚等身，会当携挈究经史。","临风忆君长痛君，有酒难浇君故址。","时乱俗殊君未知，安得长言到君耳！","空山招魂何处来，世事似尘人似蚁。","纵使化鹤犹得归，难问当时旧朝市。","朝市如今不可言，君之墓草亦已靡。","放怀回首望他山，人歌、人哭秋风里！"]},{"t":"哀苗山","f":"七言古诗","c":["昔年兵气冲扶桑，为虺、为蛇海上狂。","军中惟有哥舒翰，城下竟无张睢阳！","岛夷猖獗不可制，一撮苗山能抵当。","台湾破碎已三载，至今人说徐、吴、姜。","徐君勇敢推善战，儒巾结束变戎装。","腰下长携三尺刃，手中能擎百子鎗。","冲锋独队遏强敌，出没山林成战场。","姜君勇悍亦异常，一时驱虏如驱羊。","吴君统率同一气，义旗一竖神扬扬。","诚知大敌未易禦，民众骤合非久长。","又况援师不足恃，岂能只手除欃枪！","如火如荼敌军至，六月、七月人惶惶。","苗栗山头台安海，西有舟鲛东有狼。","为猿、为鹤不可知，数君名在家已亡。","存没死生疑传疑，生死于君两不妨。","生为国士死国殇，望风凭吊歌一章！"]},{"t":"钓龙台歌，和梁先生子嘉","f":"古风","c":["钓龙台，高崱屴，千年故址潮千尺。","钓龙台前海水深，钓龙台后风云黑。","于今不见闽王来，犹见闽王钓时台。","台对荒祠自今古，台成浮世如尘埃。","闽越王去不复返，海水东流不复转。","钓纶下水海水高，长绳系日白日晚。","争道当时禹迹遥，会稽禹穴今岧峣。","越国犹馀防风骨，闽山不到神禹轺。","往事迁流思帝子，骑龙、豢龙龙可使。","禹王胼胝不到斯，禹王苗裔王于此。","粪除足补神禹功，披荆拔棘东海东。","南台山下钓矶石，钓起禹时挟舟龙。","于今海水复扬尘，海中疑有蛟鳞鳞。","安得钓台沈一饵，钓断螈螭安八闽！","闽越王是屠龙手，惜哉事汉心不久！","夜郎自大轻辟胡，终被汉禽作龙屠。","后有负汉王心粗，请视王台血模糊！"]},{"t":"中秋暴风纪事","f":"古风","c":["秋空怒涛涌不止，万籁怒号动万里。","平分秋色何处看，海风吹立海瀰瀰。","海潮滂沛上冈陵，海岸邻居没风水。","黑云蔽天天色沈，浮壒入云云气紫。","一路山川齐撼摇，千年树木群飞起。","南北东西不可知，汹汹声从西北始。","予时道上匍匐行，碀礐礌礐砂砾倾。","摐金伐鼓俨临敌，身欲赴前势难争。","皇皇避入人家坐，忽见千船、万船破。","空际飘帆作纸飞，眼中老屋如箕簸。","六月、七月暴雨灾，谁知秋半暴风来！","天意微茫不可测，天灾重叠下吾台。","嗟嗟陆危海亦惨，海陆无处非祸胎！","问苍苍，有馀哀，天昏月黑惟尘埃。"]},{"t":"答林幼春并怀林十及梁钝庵","f":"古风","c":["燄峰崔嵬天一尺，峰下诗人林君宅。","来诗遥遥怀鹿渠，鹿渠流水冬寒碧。","前日送钝翁，共迟鸿泥迹。","钝翁归去不可追，广州山与海天隔。","复有松江食鲈鱼，君家十叔殊难得。","寥寥人散天一方，我与君居亦并僻。","安得君向鹿溪游，我向燄峰亦作客。","题诗名山祷山灵，回天转海洗尘积！"]},{"t":"吊梁钝庵","f":"七言古诗","c":["一年不见梁钝庵，见说已作古人谈。","广州潮际风和雨，曾记游踪到东南？","先生诗笔能使健，时如老骥腾服骖。","五十功名无所就，三千里路犹健探。","先生老境为诗格，自说学诗比高适。","诗篇无多篇可传，将军门下为揖客。","当时方盛汉官仪，幕府橐笔从文螭。","草檄欲取玉鞶带，登筵辄挥金屈卮。","沧桑之后君再至，匪遇山狙即野狸。","晦迹韬光不复出，杜门谢客惟作诗。","逸踪到鹿寻逸侣，索读文诗到予处。","扬子雕虫为我倾，茅容只鸡送君去。","去后君即归广州，竟闻玉树埋荒邱！","庾信哀时赋未就，相如遗稿谁得收！","五虎海门不可见，啼乌落日声啾啾。"]},{"t":"留声器","f":"古风","c":["万籁寂静虚堂风，长腔、短腔出郫筒。","一鼓促拍「河满子」，再鼓摊破风入松。","云璈水调殊玲珑，摄以电气贮以筒。","芥拾音响归冥濛，橐籥枢纽相磨砻。","放之满堂为逢逢，倾耳曲折无不通。","偷声共诧「声声慢」，动色四顾色色空。","初如湘灵鼓瑟湘江上，旋如洛神通辞洛水中。","一弹再叹有馀韵，一望无人无丝桐。","传递语音亦曲肖，又如楚巫翻译出喉咙，石言鬼语非谣童。","购得人人矜奇器，闻者往往惊神工。","我谓此事何足异，在昔偃师称小技。","革人歌舞能目招，驱使草木供游戏。","顺帝灵巧亦可言，铜人报时按节至。","国初博物有江永，邮筒传声千里致。","锼?浑沌机窍开，不须乞灵天地气。","木鸡、木狗并有声，变幻五行易位置。","奇巧即在耳目间，未用远徵输巧事。","西洋此器未十年，末巧由来吾吐弃。","是器传语况区区，何似传递今古有吾儒！","道德事功留纸上，但凭寸管非机枢。","有时馀事弄狡狯，咤叱笑骂杂噫吁，传之千载声声俱。","不第绘声且绘色，活留?咳并眉须。","西人亦有文字鄙且拙，廿六字母徒翻切。","拗断嗓子语言粗，虽有精意无由设。","时移地易音即差，兜禽僸佅难分别。","得其官骸遗精神，留声机械何须说！","炮火有声声震天，西洋制作年复年。","一震不留犹慑敌，兵家阴机能研坚。","中华此事诚缺憾，铁马屯军噤不前。","我思此事由人废，群才一出将渊渊。","吁嗟乎，留声器，我闻汝声泪为涟。","此间时事不堪述，妇孺啜泣难下咽。","劳者莫歌穷莫达，万户吞声何处宣！","愿借汝机托汝械，为记愁苦与颠连。","记事比珠哀比弦，传诸大帝钧天广乐边，叩天问帝夫何言！"]},{"t":"幼春邀过罩雾，喜晤其叔林十","f":"古风","c":["十年眺雾山，一朝登君户。","入门不识谁主宾，纷攫诗书同茹吐。","君家阮叔在堂前，长揖话旧问劳苦。","入夜挑灯明月光，瀹泉煮茗论今古。","朝来为指屋后山，山中有亭兼有圃。","共向山头泛棹行，归来君叔笑相侮。","问余袖中携何诗？","将毋当作看山谱！","看山、看雨住亦佳，有朋、有酒狂相舞。","留我暂为北堂宾，羡君长作东山主！","他时鹿渠得再来，此间燄峰犹可数。","万仞起白云，余怀能挹取。"]},{"t":"写山谷诗；幼春有赠，即次其韵","f":"七言古诗","c":["山谷诗编、蔡伦纸，我生见月辄忘指。","百里携屐为看山，忽为古书滞于此。","林子下笔发想奇，新词未就神先驰。","写余饭颗卓午身，成君织绵云汉诗。","是时六月鸟声变，祝融当天南氛煽。","手持一卷冰雪文，风流千古涪江擅。","涪江兴废二百年，七言古格今犹传。","忆曾全鼎尝一脔，未殊寸管窥长天。","健笔雄词万斛重，有人绝膑或折踵。","才怯搏虎终非豪，力奋当熊方成勇。","林子作诗贮满筐，三唐、两宋一囊装。","须与直追汉、魏上，沧海横流才可防。"]},{"t":"戒烟长歌","f":"古风","c":["人生嗜好各有偏，昔者为酒今为烟。","通脱俱能适我兴，迷溺乃足生彼瘨。","酒可合□可颐养，下饫渔樵上神仙。","奇士、隐士或赖醉中传，嗜之灭顶而流涎。","遂有丧性家国捐，归咎于酒何为焉！","譬之于食色，乐而过之亦致愆。","我生于世百无嗜，独有书味结寄缘。","宋艳班香供吮嗽，经腴史液相缠绵。","閒来偶吸罂粟髓，恰如客思莼菜然。","写意聊作消閒计，心不在此等谈玄。","床头金灯伴玉管，藉作藜光年复年。","亦愁食痂成夙癖，旬日匝月辄舍旃。","凌云吐气豪千尺，未许尤物长熬煎。","况思调鼎上金殿，复愿饮冰到居延。","一杯、一酌且须断，宁忍烟霞痼癖卧寒毡！","虽未作监兼作戒，早已忘蹄又忘筌。","自从世界变腥膻，燹火劫灰焚大千。","恶氛炎燀不可扫，瘴烟毒雾镇相连。","九霄无路餐金瀣，半世空劳炼汞铅。","自叹此身已废朽，遂将此事托逃禅。","古人有托隐于酒，我今何妨隐于烟。","收拾青云付灰烬，壮心缕缕管中牵。","芙蓉城主石曼卿，金粟堂身李青莲。","末路英雄无退步，喷■愤气填坤乾。","小榻一椽书百卷，枕藉拌作瓮中眠。","谁知时俗有洗涤，争伐髓毛争磨镌，禁烟争问到吾边！","吾聊从俗佩韦弦，戒之连日喜安便。","不如俗鼻有涕涟，不同俗态有痫颠。","无众生相无我相，脱然一笑破万缠。","但是长夏难排遣，终日废閒空手心悬悬。","此物费吾无多钱，吾姑执此胜执鞭。","陆沈于世何所望，吸风饮露一寒蝉。","援我自有「传灯录」，慎毋嗔我为矫虔，我于此中获洞天。"]},{"t":"题邱菽园「星洲选诗图」","f":"古风","c":["南溟万里海水黑，游人到此俱失色。","诗卷空留天地间，珊瑚直沈波涛侧。","儋崖久已无名儒，峒黎岂复知苏轼！","况自贡道当时绝天家，南洋万国已阻万重沙。","衣冠文采风流尽，言语侏禽教化差。","不迎白虎周符节，且罚黄龙汉使槎。","此时纵来青云士，如以衣裳卖越市。","世界烽烟炮火多，夷歌起时弦歌止。","倘逢世上操觚人，不啻海滨逐臭子。","谁知豪杰出芦中，独回窄袖乘长风。","怀铅握椠星洲东，大笔一扫万尘空。","汉、唐遗族有生聚，舜、禹苗裔非洪濛。","身自南来心自北，应有悲歌哀家国。","狂澜不断欧罗巴，痛泪无穷波罗的。","李、杜百篇寄远邮，板荡八章吟绝域。","我从王子慕邱迟，亦在天南沦迹时。","绝口不谈寰中事，杜门罕驰海外诗。","忽由图里见君面，不夷、不夏匡解颐。","想见掷笔鸡林地，折尽浮海扶桑枝。","孔融、德祖大小儿，贾山、鼌错新相知。","君也置喙于其际，令我闻之轩须眉。","云何避祸忽变计，朱公赎罪千金赀。","南海虽得云雾披，此生未免付聋痴。","今日閒情操选政，蛟龙岛国平如镜。","星辰时从海底回，日月每向涛头迸。","七洲洋过接昆崙，昆崙奴奉陶岘令。","鼠毫麋墨长髯来，犀角象牙奇物竞。","更闻炎方出翠毛，片羽值得黄金绦。","君也见诗如见宝，沧海一钓连六鳌。","人生时事不称意，浮沈一身无位置。","惟有饮酒与放歌，足以幕天兼席地。","二三素心共擘笺，传之千秋成韵事。","恨余阻隔万重山，蓬莱可望不可致！","题诗寄与海西头，拍海鹍鹏云生翅。"]},{"t":"有感放歌二首 其一","f":"七言古诗","c":["八年不踏中华路，海外风烟尽非故。","沧溟一水断东南，青山不合谁得渡！","黄云一片海上来，蛟鼍吹波长不开。","我欲鞭石作桥过，江山惨淡金燕台。","嗟我豪怀不可说，雷公烧尾剑破缺！","入水无由化龙飞，丰城夜夜牛斗热。"]},{"t":"有感放歌二首 其二","f":"古风","c":["我生不得骑马游司并，又不得披裘冰天射虎行。","壮颅郁郁居此岛，何能碧海诛长鲸！","行年三十又有七，电光雷火驱白日。","已抛腰下断水力，更秃楯头如椽笔。","意气空自不可羁，少壮风云能几时！","宇宙黄埃万丈积，挥戈欲扫嗟已迟！","此心岂得付流水，我欲登天一问之。"]},{"t":"赋赠丁茂才锡勋从内兄","f":"七言古诗","c":["昔日君家富华藻，琴书冠佩春风好。","老成凋谢危乱来，全家航海辞蓬岛。","楼台亭阁烽火中，丁令重归颜欲老。","中原山水已沈沈，故里风烟殊草草。","君来已叹风景非，君怀不与当初违。","过我床头论书史，奇气激昂风雨飞。","三、四年间两相见，闽山、台海开生面。","旧时头责不余嘲，今日神交不汝倦。","纵谈时事更谈诗，海外今无此襟期。","五千年史三更展，五大洲图四壁披。","时时激我功名念，夜永灯抽一尺燄。","上岸已同张子舟，冲霄欲作干将剑。","君今踪迹又一年，去帆阻滞蛟螭涎。","他日未署青山券，此间先买阳羡田。","可叹辞母别妻子，弟兄三人寄于此！","北风萧萧吹海涛，不免望云又拊髀。"]},{"t":"寄赠施悦秋先生长歌","f":"古风","c":["忆昔中原承平世，先生文采青云第。","万丈光芒压斗牛，千里江山开绮丽。","元龙豪气曾几时，世钢致人不可知！","曾参原无杀人事，范滂竟有党祸施。","党祸由来陷清议，大狱锒铛动缇骑。","浮家一舸走江湖，惊涛骇浪皆痛泪。","阴阴六月天雨霜，浮霾蔽日无晶光。","匿迹通家似张俭，埋名药市同韩康。","人生胸次多磈礧，得来祸患非寻常。","先生意气仍爁煔，耳雷鼻火吐长燄。","啸歌不废万卷书，感愤横磨三尺剑。","得拂蓬块生回风，张禄名字起秦中。","系铃、解铃非吾累，失马、得马惊塞翁。","大名方自满瀛东，谁知鼙鼓来破空，宰相割地出和戎！","瀛洲一岛付异族，海国遍处生狼烽。","先生全家复越海，祸患乱离才数载。","一生未餍升平福，千秋竟见河山改！","去年海峤来一游，城郭惨淡烽烟收。","老成星散人物异，猿啼鹤唳堪泪流。","今年访旧复一到，殊邦谁是辽东帽！","仙尉姑为外氏来，王母方壶长痛悼！","我在大荒正闭门，忽惊天外得逢君。","渡江温峤重相见，裨海邹生一论文。","中华可叹今迟暮，异人不出终沈痼。","功名无由汗马开，英雄多少儒冠误。","君不见辛幼安，旌旂归宋犹退閒？","我生况难作此梦，壮怀耗矣空汍澜。","先生虽未得盘礴，犹欣后起能鹰搏。","乾坤虽老有所娱，丝竹中年差不恶。","嗟余今生长此伧，唾壶击碎声彭觥，望汉如望登天庭。","万里向风常太息，何时鼓舵从先生！"]},{"t":"闻东西战事感赋","f":"古风","c":["东头斗龙西头虎，杂糅万类为刀俎。","草木江山腥血流，乾坤橐钥变机弩。","叹我生时何不辰，极目中原生莽榛！","汉武、唐宗不复作，争长黄池付夷人！","今日四万万生民，蠖屈谁能不求伸！","朝廷不为鼓舞计，坐视外人立两甄。","辽东、辽西无净土，海南、海北飞灰尘。","甘受商于仪诳楚，岂真鹑首天赐秦！","至今英雄尚不出，我恨造化诚不仁！","两狼斗门内，咆哮日成队。","褒衣大袖立当前，嗫嚅无从置巨喙。","谁为强弱、谁成败，痛我人物总齑碎！","传闻峨峨铁岭山，西夷驻马当雄关。","又闻旅顺城，西夷窟距成磐安。","叹我有险不能握，日以大地供戕残！","今年又撤西藏蔽，唇齿俱亡宁止寒。","海东一国况纠纠，纵驱西人非吾有。","外庭内奥俱破摧，辞得狼贪来虎吼。","中原尚有山林薮，亟呼豪杰四保守。","贰师、霍病能鹰扬，深目奇肱应狗走。","陆有大冶、海有琛，旋转坤维在反手。","不信万年太古邦，一旦龙钟便老朽。","呜呼今日谈强等谈空，平戎策付马耳风。","铁轮炮车满天地，狂澜日与海流东。","频年燹火接天红，侧身西望徒忡忡！","焦头烂额盛京路，匍匐父老提儿童。","谁知海外暂食息，哀哀亦成中泽鸿。"]},{"t":"春寒，林仲偕从弟过鹿，酒中述游迹并庚子在京时事；歌以寄之","f":"七言古诗","c":["我尝楼头望沧海，长恨怀抱不得开！","春寒连日风和雨，忽闻客自山中来。","客楼诗酒纵谈宴，彷佛高、李登吹台。","眼前吐气无蓬莱，抵掌大块如尘埃。","就中一人自远至，行尽中原万里地。","西拂华岳、东泰山，北沿黄河、南淮、泗。","太行秋色马头来，吴苑晓霜襟面渍。","朝浮淮水江水舟，夕宿焦山金山寺。","半渡闻得广陵钟，六桥看得西湖芰。","吊古屡酣燕市歌，感时直下雍门泪。","酒半为我谈帝京，巍巍宫阙妖狐鸣。","风声鹤唳无人色，戈船纷到西洋兵。","将军死绥天子去，关河咫尺无由行。","鬼火燐燐照白骨，虎牙戛戛腾阴坑。","君也万死寄一生，先时蹑屩出昌平。","惊魂未定更浪迹，到处访古停行旌。","驻骖才听华亭鹤，挂席去狎扶桑鲸。","壮哉风涛万里程，可怜尘事无一成！","君谈未已我长叹，世途于今是极乱。","东西夷夏溃长防，南北河山归糜烂。","吾台已付弱水沈，中邦亦共破舟看。","纵觉黄图终崛兴，不免黑风此吹散。","中宵难著祖生鞭，空听鸡声号至旦。","酒间慷慨欲悲歌，门外风多更雨多。","北斗沈天夜滂沱，我歌斫地君则那。","君家诗思况如涌，大山、小山能唱和。","其一中原历险远，其一海外历惊波。","眼里多少舞天魔，流露诗间即楚骚。","他日示我一尺卷，下倾沧海上银河。"]},{"t":"吊从内兄丁锡勋茂才","f":"七言古诗","c":["眼中诗笔谁清妙？","丁君鸾凤孙登啸。","乱世文章故家子，携家避乱南闽峤。","闽南一去几春秋，畴曩海东来一游。","陆子见人当入洛，仲宣邀我共登楼。","挂帆辞我中原去，秋风萧萧海天处。","忽闻贾谊伤鵩词，不信王乔骑鹤驭！","与君缔姻踰十年，去年始亲翰墨缘。","方拟鲁玙双合璧，谁知雷剑一沈渊！","是时分手才半载，相约榕城欲相待。","万里云程望帝京，一朝恨水填沧海！","海上有田家有书，闽山亦有寓公庐。","华表魂归城郭改，松亭梦落屋梁虚。","伤心母老妻孥稚，仲容寂寞身后事。","名山有才未著书，逢时无命空识字！","世界烽烟变古今，江山花鸟怆人心！","那堪朋旧晨星散，况复功名逝水沈！","台湾延平旧幕府，词客哀时泪如雨。","祇今不见丁仙芝，故里空馀洪驹父！","于公门第王公孙，垆下黄公痛夕昏。","涛声浪色沧溟路，何处招君海外魂！"]},{"t":"村家夏日即事","f":"七言古诗","c":["一村流水浮瓜棚，浓绿沈沈昼无声。","白鹭乌犍满村外，时有铜钲呼卖饧。","前村微暗后村明，新稼初收鸟噪晴。","农舍炊藜午烟散，人家打稻晚风轻。","瓮中腌出冬菘菜，盘上缕堆春薤茎。","催科旦夕偶不至，一村便作桃源行。","昨日典衣今赎到，老翁呼儿聚前楹。","忽忆户税未供毕，顿愁虏尉鸡犬惊。","曳杖趑趄门外望，暑云热日当庭横。"]},{"t":"倏忽寒暑，壮士迟暮，感愤身世，赋之","f":"七言古诗","c":["春秋寒暑速邮置，马狗车栖身如寄。","俯仰乾坤一蘧庐，叹息韶华几轻弃！","人生须作酒中仙，茫茫混沌不知年。","不然天地皆窒塞，低头蝼蚁为比肩。","丈夫莫言身七尺，虱处裈中偷游适。","风云高蹠欲扬眉，九垓六合都无隙。","况乎海国吹黑风，牟牟南北昧西东。","中原更在陆沈里，英雄老死蓬蒿中。","搔头我欲问造物，世界胡任狐埋掘？","神州、赤县无纪纲，灰劫久沦恒沙佛。","阴阳晦朔去如驰，智勇失时何所施！","壮士头颅不堪抚，朝为黑漆暮白丝。","狼贪鬼谲终难餍，万卷诗书输一剑。","何时唤得群雄兴，鲁戈返日光爓爓！","呜呼我已腐儒酸，后生谁能忘此念！"]},{"t":"感愤时事，再赋","f":"古风","c":["衮衮诸公如傀儡，朝求神仙夕尚鬼。","堂堂衣冠不自存，苦把貂蝉续狗尾。","叶公好龙已非龙，乃好殊俗小雕虫。","钩辀口舌成才隽，胪列皮毛为化工。","有兴不浅是老子，无物可观信恼公。","呜呼中法能求实，随处可生新艺术。","不然西法亦腐烂，覆辙后先总如一。","君不见西国亦有弱与强，强者不少兴与亡？","刻舟求剑去已远，胶柱鼓瑟宁非伧！","自丧黄钟宝康瓠，实弃苏合亲蛣蜣。","我谓有道兴征伐，蚩尤终不敌轩皇。"]},{"t":"口号，代酬日儒白井氏韵六首 其一","f":"五言律诗","c":["苦战山河血，长留劫火悲。","千兵横掳掠，万户叹流移。","赤野蓬头满，青芜泪眼窥。","九阍天问远，默默恨为谁！"]},{"t":"口号，代酬日儒白井氏韵六首 其二","f":"五言律诗","c":["祸水惊千古，机关遍九州。","错成炉莫铸，柯烂斧空收！","已结纵横局，谁能汗漫游！","先朝鞭策远，今日丧边筹。"]},{"t":"口号，代酬日儒白井氏韵六首 其三","f":"五言律诗","c":["掷地金瓯缺，河山付愤王。","尧疆看荡析，禹甸失圆方。","蹈海风波阻，回天日月长。","哭来途尽处，车辙在穷乡。"]},{"t":"口号，代酬日儒白井氏韵六首 其四","f":"五言律诗","c":["同室干戈起，纷纭在亚洲。","虎伤庄子获，鹬利老渔收。","唇齿忘邻谊，情形误上游。","万全如可计，鼎立是高筹！"]},{"t":"口号，代酬日儒白井氏韵六首 其五","f":"五言律诗","c":["有怀思故国，大势绌勤王。","控驭如三代，帡幪及万方。","伤心抛璧碎，失计折鞭长！","事事随流水，悲余老是乡！"]},{"t":"口号，代酬日儒白井氏韵六首 其六","f":"五言律诗","c":["托身同绝域，回首望神州。","日月瞢瞳转，风云痛泪收！","山河新局面，京阙旧魂游。","误国知谁手？","前谋李相筹。"]},{"t":"感梅","f":"五言绝句","c":["处处瘴氛生，桃花难得洁。","寒来一树梅，不染猩红血。"]},{"t":"故垒","f":"五言绝句","c":["故垒歌番曲，凄凉不可听！","无多古时树，伤心乱后青！"]},{"t":"海上","f":"五言绝句","c":["海上青山在，天边白浪多。","东南陵谷后，无复汉槎过。"]},{"t":"凭吊","f":"五言绝句","c":["青山竟无恙，紫气未应消。","一代兴衰恨，匆匆海上潮！"]},{"t":"望海","f":"五言绝句","c":["长天千里尽，斜日四山衔。","片片浮云影，依然故国帆。"]},{"t":"归乌","f":"五言绝句","c":["燹火楼台后，林间乌夜栖。","旧时风景好，犹自尽情啼。"]},{"t":"鹿溪","f":"五言绝句","c":["蓬山久变迁，古岸横波剪。","不觉鹿溪潮，年来亦日浅！"]},{"t":"感事","f":"五言律诗","c":["千古极沧桑，华夷杂犬羊。","长天生苜蓿，远海接鸿荒。","地阻虚闽、粤，时危变汉、唐。","羁留寰宇外，晦迹得昂藏！"]},{"t":"食乌鱼五十二韵","f":"五言古诗","c":["俊味来沧海，腥风近黑洋。","乌头馋客啖，鱼尾酒人尝。","煮濩宜同蒜，烹调不待芗。","青鳞残似贝，白肉润于霜。","山泽轻鹅鸭，江湖薄鱮鲂。","鲤同金脍好，鲈想玉冰凉。","比目嫌消瘦，生胎美抱黄。","伊时方魻鲽，无数共翱翔。","随浪千群出，迎涛万尾张。","轩鬐成蜃市，聚吻起鼍梁。","渔子乘流俟，鲛人撒网狂。","渊澄云渺渺，天压水茫茫。","满载编桴重，分阄入市忙。","贩争排巷过，买或典衣偿。","日暮千钱数，冬寒一担望。","唤来红店口，挑去绿田庄。","俎豆难尸祝，盐醯任灶娘。","鲜甜能下酒，酸酱可和汤。","腻比江瑶脆，甘逾海蚱强。","荔枝闽岭秀，橙橘洞庭芳。","食谱堪增选，厨珍足破荒。","朵颐纷落箸，染指快倾筐。","剖脑疑镌玉，含臊若吮香。","跰跹儿女辈，颠倒狗屠场。","阳至分前后，盘羞判楛良。","年年随序到，处处逐波飏。","似雁能无爽，如潮信有常。","有时踪迹少，问价往回昂。","合浦珠腾聚，洋川米发祥。","渔家欣出筏，海户喜开觞。","未觉天风冻，奚知水路长！","不须求鰋鲔，岂必慕鲨鲿！","王政浑无禁，波居可作粮。","今朝人涸辙，异事海生桑。","孤负持螯足，欷歔结蛎房！","豫且龙服困，霸国鲙残当。","嗜鳆奸雄餍，为鱎俗士将。","何曾贪肉食，张翰把莼忘。","弹铗惟卑屈，论蚶孰慨慷！","孕腴非鲞腊，削白愧熊肪。","即此当前味，教余触目伤！","功名鸡肋弃，身世鲗烟藏。","喉里悲吞鲠，槎头叹失防！","如鳊恒缩项，匪蟹久无肠。","日日思河汉，家家痛武昌！","偶然轻暖出，忽见巨鳃扬。","作炙糅辛醋，烹鲜列酒浆。","侯门鲭鲊摈，吴地菜鲑攘。","淡泊吾能受，腥膻尔不妨。","老饕千盏后，大嚼一灯旁。","梦断鳣三进，痴怀鳖两裳。","何如捐口腹，漱齿到沧浪！"]},{"t":"答梁先生子嘉二首 其一","f":"五言律诗","c":["四海风尘外，论交孟与韩。","岘山今体绝，蜀道古诗难！","老格追高适，雄词薄子安。","岭南源委在，当作替人看！"]},{"t":"答梁先生子嘉二首 其二","f":"五言律诗","c":["相逢如旧识，慷慨问为谁？","瀛海伧荒客，文章大小儿。","世将公作寓，诗与境争奇。","直道同刘四，危邦慎所之！"]},{"t":"冬日感事四首 其一","f":"五言绝句","c":["望断中华路，风波日日寒。","伤心沧海上，已作岛夷看！"]},{"t":"冬日感事四首 其二","f":"五言绝句","c":["无地无兵燹，年年劫火来。","梅花红雪里，犹带血痕开。"]},{"t":"冬日感事四首 其三","f":"五言绝句","c":["四载居荒徼，何能陋九夷。","家家存汉腊，不见汉官仪。"]},{"t":"冬日感事四首 其四","f":"五言绝句","c":["廛里来横敛，谋生计已穷。","逋逃何处去？","海市蜃楼空。"]},{"t":"闻难民逃居山内感赋","f":"五言律诗","c":["瘴雾杳层层，逃荒有客登。","箐开今日路，崖断古时藤。","穴树同林狖，穿山比石鲮。","天荆与地棘，何处汝飞腾？"]},{"t":"内山即事二首 其一","f":"五言绝句","c":["树古不知名，入山又一程。","萧萧木叶响，时有鹿麋行。"]},{"t":"内山即事二首 其二","f":"五言绝句","c":["苔残千尺壁，树落万年皮。","月黑天阴路，空山啼怪鸱。"]},{"t":"七言今体台湾哀词四首 其一","f":"七言律诗","c":["风雨吹颓镇海台，江南又阅庾生哀！","乾坤欲老沈王气，山水无灵失霸才。","旸谷煽炎焚若木，尾闾沦没长蒿莱。","东望何处堪回首，万里浮云扫不开。"]},{"t":"七言今体台湾哀词四首 其二","f":"七言律诗","c":["几将晋土等分瓜，人事参差散晚霞。","何限蛟螭兼蝄蜽，无多猿鹤与虫沙。","风尘已变寰中色，河汉难乘世外槎！","我欲寄怀渔父路，往来撩乱武陵花。"]},{"t":"七言今体台湾哀词四首 其三","f":"七言律诗","c":["鲁仲千金耻帝秦，竟看时事化埃尘！","有怀蹈海鳌梁折，无泪填河蜃气皴。","岛屿于今成粪壤，江山从此署「遗民」！","棼棼玉石昆冈火，换尽红羊劫外人。"]},{"t":"七言今体台湾哀词四首 其四","f":"七言律诗","c":["远海遥天缺一环，舟胶水涸到蓬山。","果然雨碎长平瓦，信是风吹大散关。","骇浪惊涛号泣痛，残霞斜照血痕殷。","扶馀不见虬髯客，故国云容有赭颜。"]},{"t":"感事，寄杨广文鸿图翁三首 其一","f":"七言律诗","c":["大海波沦万斛尘，桃源买棹尚迷津。","烂柯拌作观棋客，顽铁浪成铸错人。","四壁有书慵过眼，千秋无分欲藏身！","此间隔尽蓬莱路，日晚望洋远水皴。"]},{"t":"感事，寄杨广文鸿图翁三首 其二","f":"七言律诗","c":["河山举目日酸辛，沧海漫然理钓缗。","杜甫不忘天宝恨，陶潜长署义熙民。","伧荒有路须归晋，淫浸吾生一避秦。","洗耳不闻人世事，不妨傲骨不怆神！"]},{"t":"感事，寄杨广文鸿图翁三首 其三","f":"七言律诗","c":["低眉短气是儒绅，我已因人付笑嚬。","卧榻唯将书作伴，浮家不与世为亲。","深渊无处舒蟠蛰，勺水何妨寄泳鳞。","且幸苍天庇閒散，炎灰安稳远昆岷。"]},{"t":"寄别，叠梅樵韵 其一","f":"七言律诗","c":["沧桑陆海荡蛟舟，屈子问天赋远游。","家国沦胥三比日，乾坤萧索四围秋。","伧荒人物争依晋，灭裂衣冠益慕周！","送去如登仙岛路，故山虽好不堪留。"]},{"t":"寄别，叠梅樵韵 其二","f":"七言律诗","c":["身世飘然不系舟，尘寰何处可遨游？","蜗蛮国已轻中夏，鹊木居仍构戊秋。","晋室无人为祖逖，漆园有梦即庄周。","瀛洲今日成荒径，子去何妨我暂留。"]},{"t":"感咏","f":"七言绝句","c":["何处桃源世外天，天风吹去钓鱼船？","扬尘海上曾经见，又到蓬莱浅水年！"]},{"t":"寄友人杨倬卿，时避地在厦门","f":"七言绝句","c":["番卒驱过铁马蹄，楼台海市烂如泥。","羡君避乱移家去，遥在沧波落日西。"]},{"t":"即事","f":"七言绝句","c":["五月西风吹转东，云霞蔽海半天红。","行人记得楼台路，尽在寒烟燹火中。"]},{"t":"感怀十二首 其一","f":"七言律诗","c":["蓬莱城市阅兴亡，戎马当时一战场。","万古衣冠为赘痏，百年文物付伧荒。","几茎头发留遗种，不世心怀郁倒藏。","谁道我生今似此，中途摧折尽刚肠！"]},{"t":"感怀十二首 其二","f":"七言律诗","c":["破碎山河负此生，未寻春梦已无情。","人将南渡望温峤，我把西归谢子卿。","耻向金门谋索米，渴于玉海待澄清！","世途若有回机日，老大还须学请缨。"]},{"t":"和苗栗诗后有感","f":"七言绝句","c":["忆曾北上过房湾，连襼篮舆海驿间。","今日关津非昔日，不堪回首看苗山！"]},{"t":"自闻汝东凶耗，怀人感事，日觉伤心；再作二首 其一","f":"七言律诗","c":["一自沧桑变世尘，每闻时事辄伤神！","已因故国肠将断，况为同侪泪满巾。","天地无情催梦客，江山残劫到閒人。","不堪回首看云物，处处风烟散渚蘋。"]},{"t":"自闻汝东凶耗，怀人感事，日觉伤心；再作二首 其二","f":"七言律诗","c":["城郭依稀鹤不还，谁能将酒减愁颜！","悲馀陇上东西水，泪尽何家大小山。","夜月波沈三岛路，秋风梦断八闽关。","歌残「薤露」歌「蒿里」，不为多情鬓亦斑！"]},{"t":"和蔡君念淙因梦见忆二首","f":"七言绝句","c":["桃花潭水见深情，隔浦鸥群有旧盟。","一夜西风吹梦去，不辞关险入山城。"]},{"t":"再送梁子嘉先生二首 其一","f":"七言律诗","c":["秋风归去尉佗城，千里波涛万里情。","客地竟逢沧海变，家乡须觅富春耕。","路从绝岛洋关起，人向中原故国行。","此后不胜天末望，鱼书尚寄一函轻！"]},{"t":"再送梁子嘉先生二首 其二","f":"七言律诗","c":["九十峰头再一行，相邀话别不胜情！","今宵好雨千山隔，明日沧波万里征。","白雪西风生客鬓，黄云东海见归程。","此间咫尺犹难望，何况天涯望去旌！"]},{"t":"书事和韵二首","f":"七言律诗","c":["山水萧条阅四秋，中原翘首不胜忧！","频闻回纥侵京国，况见昭王去汉流。","歌哭辱公鸲鹆谶，艰难望帝杜鹃愁。","乾坤已老纷无主，长怨诗书误邺侯！"]},{"t":"报家韫岩孝廉信，并谢见赠苏紫笔、眼镜袋二首 其一","f":"七言律诗","c":["岁岁鱼书到海滨，伧荒何幸故交亲！","此生愿掷班超管，举目难遮庾亮尘。","翰墨因缘君爱我，褷缡眼界我思人。","乱中未老头先秃，惭愧琅函入盼新！"]},{"t":"报家韫岩孝廉信，并谢见赠苏紫笔、眼镜袋二首 其二","f":"七言律诗","c":["海外怀人路窅冥，感君投赠意丁宁！","毛锥藏颖头犹紫，瑶镜韬光眼孰青！","记得江湖新岁月，贮来京阙旧霜星。","亦知食肉原无相，惆怅风尘一瞬经！"]},{"t":"感望四首 其一","f":"七言律诗","c":["世路迂回入渺茫，浮生今竟识沧桑！","贯胸国已无王会，披发人皆下大荒。","百二河山馀瓦砾，三千城郭落风霜。","从兹莫过誇高蹈，小隐依然在故乡！"]},{"t":"感望四首 其二","f":"七言律诗","c":["东来不见旧梯航，故国依稀入望长。","秦地埋头梁苑客，汉家俯首夜郎王。","九边荒徼残云白，万里中原落日黄。","此后未知何处去？","穷愁多泪在沅湘。"]},{"t":"登楼有怅二首","f":"七言律诗","c":["海上浮云漠漠开，萧条人事叹登台！","谁将玉斧黎河划，竟使金牛蜀道来！","南北烽烟沈白日，东西山水起黄埃。","不堪踪迹如王粲，我欲伤时赋「七哀」！"]},{"t":"林十自吴淞归，寄问江东名胜二十二首","f":"七言绝句","c":["避乱离家已五秋，温陵更徙到吴洲。","归来海上看乡树，记得江南景物不？"]},{"t":"次林十韵，吊梁钝庵","f":"七言古诗","c":["地棘天荆蜀道难，归来鱼铗竟谁弹！","三生庾信埋吟骨，千里秦观梦殡棺！","碧海有鲸空鼓柁，蓬山无雁少书翰。","只馀朋辈闽南路，酾酒招魂泪不乾！","诗人自古逢衰世，沦落东南失放翁！","蓬岛巢痕千亩竹，扶桑游迹一帆风。","半生吏隐漫聱叟，百粤坛场亡是公。","今日宦途成散手，未须地下痛途穷！"]},{"t":"次韵答悦秋先生游台见赠","f":"七言律诗","c":["诗书吟啸托生涯，他日扁舟去未迟。","千古劫灰游子梦，一床风雨故人思。","知君渐作流东水，叹我难开向北枝！","自是浮沈过此世，销磨意气已无奇。"]},{"t":"志别四首，送悦秋先生归唐","f":"七言律诗","c":["蓬岛逢君又送君，差堪臭味不莸薰。","愧无居士鸡林赋，漫有邹生裨海文！","犹得故交心似水，再瞻前辈气如云。","倘能御李同车去，故国江山即梓枌！"]},{"t":"到雾山与峻堂话旧","f":"七言律诗","c":["携手东皋夕照明，隔林时鸟起啼声。","青山华屋人犹在，碧海丹邱世已更！","一路楼台非锦里，十年朋旧尚深情。","春蔬夏笋浮醪饮，宾主高歌感慨生！"]},{"t":"无聊自叙五首 其一","f":"五言古诗","c":["少年负意气，溺志在诗文。","唾手功名场，谓可张吾军。","长途虽跌踬，怀抱犹凌云。","谁知时世变，四海生楚氛。","波涛鲸鲵声，风异不可闻！","兵燹满寰区，世欲诗书焚。","痛愤摧五内，尘思空纷纷。","登高望长安，远海挂斜曛。"]},{"t":"无聊自叙五首 其二","f":"五言古诗","c":["弱冠窥时事，治乱入胸中。","夷狄侮京华，今古不相同。","临文怀杞忧，鸣声等秋虫。","负质诚毫末，商音凌太空。","乾坤有霜雪，极塞来宾鸿。","零零白露下，草木迎西风。","哀哉我生初，时异兼途穷。","徘徊风尘际，繻帛误终童！"]},{"t":"无聊自叙五首 其三","f":"五言古诗","c":["壮岁多感愤，果然遭变迁。","苍狼嗥我后，白虎啸我前。","出门视天地，日月更黄玄。","我生怅已矣，世途何望焉！","抱有殷、周器，饿与沟壑填。","薇蕨甘如饴，夫岂饮盗泉！","韬晦陆沈间，蛰龙思九渊。","壮心时一露，牖下铭燕然。"]},{"t":"无聊自叙五首 其四","f":"五言古诗","c":["行年忽四十，误矣此半生。","青春去如电，皓有何所营！","朔风吹南雪，萧萧边马声。","闻之心悽恻，大海当门横。","出门无高会，日月长西倾。","托身栖远岛，室有巨鲸鸣。","愧无伐蛟手，宝剑空铿铿！","摧颓惟长卧，白日过前楹。"]},{"t":"无聊自叙五首 其五","f":"五言古诗","c":["四十复四十，百年亦可知。","落叶辞故柯，坠地无返时。","光阴不我驻，前路复何期！","经纶一无绪，两鬓且丝丝。","窃怪阮嗣宗，途穷哭何之！","世途今复局，望晋羡坦夷。","今日两眼泪，见骨无已而。","安得桃源游，冥然随黄、羲！"]},{"t":"赋赠林十","f":"五言古诗","c":["忆昔承平馀，君家称再盛。","棨戟交门前，裘马相辉映。","朝廷宠金张，闾里誇剧孟。","猎场夜炬明，射棚晓弓劲。","枪炮带刀矛，行围火珠迸。","以兹为乐图，閒即张觞政。","拥妓青楼门，酒酣恣豪横。","人畏周处狂，官恕徐邈圣！","君独耽诗书，怀才事吟咏。","万卷环酒杯，一编对灯檠。","诸昆伯仲间，淡漠清风夐。","当夫应试时，夺标则凌竞。","春风二、三月，青衫行掉罄。","琐院压同侪，旗亭得佳评。","我时始识君，诗坛共高兴。","君谓我诗豪，邱迟两敌称。","自此车船间，簦笠偶合并。","蛟洋静不波，鲸海澄如镜。","欲采骊龙珠，来照齐侯乘。","扬帆五虎门，看山八闽嶝。","闽峤风景多，歌诗互投赠。","望古吊无诸，钓台从空亘。","秋色满中原，苍苍风雨暝。","旗鼓分两峰，云涛相汀滢。","感慨汉盛时，瓯疆奉禀命。","日月曾几何？","名场各蹭蹬。","尘世起变迁，周郊弃南郑。","茫茫大海天，于今失夏正！","君家走苍黄，防军皆剽轻。","君去为冥飞，我居作潜泳。","鯈鳞难远逃，沧桑阅至竟。","伏莽虽频生，鸿沟已大定。","昨者君复归，山川非昔胜。","问君江南地，风花俱艳靓。","鹿上姑苏台，莺蹄采香径。","士女犹酣嬉，江山未易姓。","黑浊上海洋，夷氛流不净。","此地岂桃源，同余恋栈性！","遂向大荒沙，俱临小槛阱。","寄托蟭蟟栖，称呼马牛应。","酩酊醉乡甜，沈沦壑谷靘。","种秫百亩嬴，供税仍无剩。","庭前九十峰，秀色差堪饤。","邀余作山行，青山排石磴。","入山一以深，庶或逃新令。","岂知大东州，早视如几凳！","谢客空缒幽，蜀丁失依凭。","世路既已穷，閒居非我病。","咫尺汗漫游，膻中葆素行。","与世为浊清，与人同醉醒。","田园虽生涯，有时付破甑。","世界蛮触争，潜龙以角听。","或可免伧荒，相携出泥泞。","投诗君勿传，此间多刺侦！"]},{"t":"过秀水村视禾田感赋四首","f":"五言古诗","c":["闭门效閒居，未能遗田亩。","禾稻青油油，我愧泥涂叟！","孜孜田亩视，胜彼谋升斗。","春初来一行，苗寸长如韭。","今夏偶复观，稻华秀已久。","幽鸟鸣田间，老农登陇首。","林树带茅茨，出入沽村酒。","田家乐事多，轩冕同敝帚。","愿寻沮溺徒，永结蓬蒿友！"]},{"t":"赋梅","f":"五言古诗","c":["积冻满孤山，昨夜竹桥折。","流水疏篱间，佳人自幽绝。","青青林际松，娟娟岭半月。","横斜出数枝，微芳不能歇。","我为看花来，寒兴对之发。","感此尘埃中，何以得自拔！","台湾刀俎地，杀气填林樾。","百卉不能妍，生意皆夭阏。","有时闻煮鹤，桃花流猩血。","于今八、九年，始见一株雪。","爱之三摩挲，嫣然劫灰脱。","风韵固温存，心肠自石铁。","宇宙回阳春，不向此中泄。","花开寂不喧，令予不忍别！"]},{"t":"咏栴木","f":"五言古诗","c":["海南产异木，其材过豫樟。","下者供床榻，上者充栋梁。","妙质谢雕饰，触目生辉煌。","髹漆置棐几，墨客喜琳琅。","自从版图易，百物添税章。","山海尽环牢，虞衡峻法纲。","千重云雾窟，铁印苍皮僵。","日月入剥蚀，斧斤落风霜。","我欲置此木，如营白玉堂。","贱价增三倍，贵者逾双璜。","官府有掊克，民间无盖藏。","巍峨九十峰，万木空苍苍。","忆昔承平时，培植事包荒。","百谷溢海岱，群梓出梯航。","租赋蠲积逋，何有求篚筐！"]},{"t":"咏蔗糖","f":"五言古诗","c":["炎洲孳大利，豫樟及蔗浆。","豫樟煎作脑，蔗桨煎作糖。","樟脑璨玉华，糖屑瑩玄霜。","馀润及五洲，饶裕在千箱。","一入虏官手，搜剔无粒藏。","樟脑供官卖，私贩严律章。","蔗糖加酷例，一担九输将。","宾筵失旨甘，画饼充饥肠。","粔籹蜜饵间，渴慕馓餦餭。","枣杏瓜棣生，无处问饴饧。","美洲传异种，空闻一丈长。","熬蒸出膏液，未敷税吏尝。","鬼机代人力，漏卮永无当。","子虚赋云梦，嘉味满潇湘。","客至阙甘饮，谁嗜盐、茶、姜。","甜流不涌地，玄圃空温汤。","赤沙冱丽冰，梅冶滋不祥。"]},{"t":"风暴晚稻四首","f":"五言古诗","c":["四野寡桑麻，耕犁事已细。","灾厉与暴徵，谁复田园计！","如何田价昂，寸土需重币？","总由谋生隘，食租当急济。","其奈贾平章，蓄买公田势！","洛阳千万顷，纸市有前例。","兹事漫具论，我当树六艺。","田宅虽就荒，树木爱阴翳。","带草生书窗，幽花对庭际。","春至百物温，空廪亦度岁。"]},{"t":"岁暮不憀，忽得李二垂危之信","f":"五言古诗","c":["独居困穷愁，寒冬逼岁暮。","心绪郁不纾，无处展幽步。","天末怀友朋，又闻故人故。","寥寥知己间，晨星随薤露。","空林野鸟啼，回车哭歧路。","日作伤心人，出门倦会晤。","李生我石交，忽焉通尺素。","言在垂死中，欲待巨卿顾。","肝肠寸寸摧，手足忙无措。","故旧难复得，新交多舛互！","向秀山阳心，处仲黄垆慕。","日暗雪霏霏，哀情谁与诉！"]},{"t":"触目感咏","f":"五言古诗","c":["蹑足炎山顶，回首沧溟天。","蜃市随风起，赤城堕我前。","我家东海畔，海水没桑田。","顾盼旧城郭，沦灭无人烟。","驱车北原路，荒草何芊芊！","郊野莽萧瑟，牛马鸣道边。","飒飒凄风捲，荒荒白日悬。","踯躅何所往？","山海空相连。","山有猛兽迹，海有蛟龙涎。","行路既已难，谁能扬长鞭！","家国念存丧，身世多变迁。","抚剑长太息，埋地今千年！","朝驾扶桑谷，夕宿昆崙巅。","飙轮无所阻，我愿随飞仙！","仙人不可期，时俗渐腥膻。","挥手弄牛斗，泛槎有张骞。","终当御风去，万里风泠然。"]},{"t":"怆怀身世感赋","f":"五言古诗","c":["东坡三十九，已悼劳生半。","陆机四十年，亦起逝者叹！","我更逾三秋，微尘与绁绊。","出处无可言，沈沦不胜怨！","历历数游踪，爪泥真汗漫。","北过荷兰城，南登延平观。","航海三、四回，不离闽海岸。","东望山阻深，西归海中断。","功名等云烟，科第失风汉。","岁岁秋风生，空作去来雁。","春雨长安花，无由走马看。","偶歌梁甫吟，时鼓稽康锻。","冷食闭门齑，热谢因人爨。","万卷当百城，频年惟伏案。","气尽处笼鹰，身是栖篱鴳。","嗟嗟长夜中，不能得一旦！","身世方沈湮，时世忽危乱。","海岛早沧桑，瀛洲大麋烂。","干戈似猬毛，民庶纷鲁窜。","诗书既焚烧，衣冠亦涂炭。","耆旧半云流，朋侪又雨散。","世异人已非，星移物复换。","顾我贱头颅，奈何蒙此难！","忽忽栖山中，悠悠吟泽畔。"]},{"t":"避暑感咏","f":"五言古诗","c":["盛夏汗交流，苦乏盘旋地。","有如乱世中，又逢毛鸷吏。","炎日当熏蒸，苛政方穷治。","酷吏与酷暑，古今同一致。","暴敛及横徵，民生无馀利。","长此炭火中，万无薰风被。","寝处尘埃氛，遍身皆垢腻。","洗沐不自由，有若生芒刺。","人事与天时，何处堪趋避！","恨无摩天翮，凌空生六翅！","今日入疏林，飒飒新凉至。","时鸟鸣一声，山川滋妩媚。","豁然忘三伏，真觉触百忌！","但是酷暑驱，末由苛政閟。","居士清凉身，尚未释倒置。","四体虽暂纾，惨惨在心志！","会须求桃源，人寰撒手弃。","逍遥出九天，俯视江山异。"]},{"t":"登临感作","f":"五言古诗","c":["日色落海天，青山馀一发。","苍苍海波中，何处是闽、粤？","帆断浙江风，城堕吴峰月。","痛哉海东山，竟与中华绝！","南望鲲身沙，北望鸡笼雪。","中有玉山尖，尖尖皆破缺。","白云迷翠微，青春啼林鴂。","处处苔藓深，剥尽古碑碣。","古迹无一存，往事不可说。","俯仰废兴间，悲风来不辍。"]},{"t":"谢先为生圹来徵诗，为题四作","f":"五言古诗","c":["人生如蝉蜕，终与大化游。","面目如刍灵，尻骨如轮辀。","有时归一尽，处世如寄邮。","彭殇岂异致，物宰无短修。","粪壤同蝼蚁，早暮同蜉蝣。","如何不达人，视死如视仇！","岂知身在世，未死犹赘疣。","或有浮慕者，远企神仙俦。","神仙不可期，玉棺来无由。","亦有放佚人，未死营糟邱。","或作终隐计，既老营菟裘。","皆非旷达观，高厚一身囚。","何如谢先生，乘气出九州！","请谥冥漠君，荷锸随老刘。","牛山鬼兆域，马鬣栽松楸。","阴阳作攒輴，天地为堲周。","近在锅鼎山，豫凶及窆幽。","华屋告生存，蒿里歌劝酬。","岂似杜元凯，生前营首丘！","西瞻晋宫阙，东奉二陵秋。","同人车三过，腹痛莫泪流！","千秋万岁后，尔我皆枯髅。","生诔陶渊明，安命素所求。","生祭杜牧之，埋骨宁所忧！","我来进生刍，一笑先生休！"]},{"t":"再题谢君生圹诗后","f":"古风","c":["黄土抟作人，幻成亿万身。","一朝堕黑劫，千里为幽垠。","人物委虫沙，江山生鬼燐。","哀哉东瀛土，竟与北邙亲！","千峰万壑间，惨淡蓬蒿尘。","华表归辽鹤，城郭殊人民。","惘惘市廛间，如行墟墓滨。","真仙泣铜狄，故老悲荆榛！","积骨封三观，薄殡盈九闉。","家家守俘馘，日日输鬼薪。","蓬莱气寂寞，薤露声酸辛。","大哉方壶图，亦与生圹均。","生者永埋没，死者永沈沦。","视死如视生，我爱谢茂秦。","谢客愿生天，青山豫卜邻。","地非故乡故，体是陈人陈。","经营壤泉异，封树窀穸新。","嵯峨石翁仲，荦礐瓦麒麟。","世已无华夏，君自享秋春。","于下开隧道，于上开墓门。","未掩苌弘魄，先招屈子魂。","天地供幕席，风火俟转轮。","泰山为?俎，北海为牺樽。","大块为鼻祖，百代为云孙。","太祝岁祈死，少微月告存。","遥悬归寝地，亲署葬诗坟。","生抱无涯感，死抱不朽尊。","未生、未死间，皆以骈牳论。","旷达同司空，滑稽异齐髡。","后有凭吊客，呼作谢公墩。"]},{"t":"夜雨，读国朝人诗","f":"五言古诗","c":["深夜听雨声，当作琳琅响。","春风吹檐除，声似鸣兰桨。","入耳无凡音，天机资肸蚃。","起视天宇空，窈冥含幽敞。","危坐读古书，灯暗走蝄蜽。","一编渔洋诗，生吾云霞想。","竹垞朱老翁，骚坛森法仗。","萧瑟古梅村，感慨极肮脏。","岭南陈与屈，悲歌同苍莽。","独立邵青门，深造吾向往！","维兹数大家，名当塞天壤。","一吟一沈深，本朝应无两。","苏、陆、李、何后，风骚应接踵。","如何嗜好殊，异论兴朋党！","吾独无所偏，唐、宋皆素仰。","凡调与时趋，巧制涉邪枉。","一一必删除，古人庶乎放。","晚近号多才，狐禅参龙象。","纷纷靡适从，吾取沈与蒋。","馀子未定论，徘徊倚书幌。","雨声寒入衣，曙光含夜曭。","推襟欹枕眠，鸟声报晨爽。"]},{"t":"有同姓黉士，率先断发洋装者；以其画兰册来徵题，姑为赋此","f":"楚辞体","c":["兰蕙失移根，一朝化茅茹。","人生世变多，当门谁与处！","草泽有沦胥，芳馨九畹贮。","澧源、湘水间，斯人千古许。","画兰知此意，古香浮素楮。","湘君降九嶷，目成兮心与。","形神一以违，申申女媭语。","不待灵均来，臭味先龃龉。","所愿同根人，深求空谷侣。","似兰勿似茅，吾将施缟纻！"]},{"t":"伤三儿弥月殇","f":"五言古诗","c":["我生已不辰，我命有所制。","浑沌七尺躯，陆沈半生世。","五角兼五穷，四十有四岁。","颇谓大困深，或有小汽济。","今年九阳月，忽得三男筮。","皇皇寝在床，呱呱堕于地。","虽异槐植门，或比兰生砌。","乱世得添丁，穷途获束币。","阀阅无勋名，诗书有苗裔。","虽无充闱心，犹堪告考祭。","客至试啼声，我闻辄破涕。","多男比多福，此事亦不细。","况我香山集，尚待衮师继。","王氏三珠树，窦氏五枝桂。","后日王仲淹，不患史无系。","奈何我命艰，未兴而有替！","阆胎匝月生，泡影一朝逝！","有如老树花，忽为严霜毙。","浚冲孩抱物，悲伤不自掣！","哀肠芒刺多，愁眼昏霾曀。","痛矣泥涂身，生育亦幽滞！","往时瓦徒弄，今时玉遽瘗。","天荒地老中，复挥思子泪。","吾父孝恭公，慈祥而孝悌。","隐德及多人，和光消众疠。","岂有于公门，不及张汤第！","我兄幸繁衍，而我独侘傺。","或者我持躬，不免有乖戾。","司命告于天，佞魃谗诸帝。","夺去宁馨儿，俾减传经计。","岂知沦伧荒，早已等舆隶。","斯文一线延，妄想千秋系！","讵比刘殷家，七儿分七艺。","区区不畀余，造物无乃厉！"]},{"t":"答陈六因梦寄诗","f":"五言古诗","c":["余每诵君诗，如逢君一面。","何期君梦中，忽与余相见。","山川虽阻修，两心通一线。","君居鳌海头，我居鹿江甸。","梦中获往来，较于邮传便。","昔人魂梦间，每愁道里眩。","如何我两人，神交速流电！","塞黑枫林青，无为李白颤。","九月风气凉，微霜飘素霰。","明月屋梁间，照君颜色变。","昨日君书来，文鱼衔匹练。","绸缪五色丝，交系两头绢。","明珠缭四周，良玉当中现。","展吟未及终，方诸津可咽。","俨然郭使君，锦段梦中荐。","紫海天鸡鸣，赤城云虾绚。","恨不梦重重，为通思片片！"]},{"t":"喜次儿十二岁能诗兼画","f":"五言古诗","c":["我少解诗文，作书性所拙。","下笔走龙蛇，自笑同榾柮！","至于六法间，更不识毫发。","每羡画、书、诗，昔人成三绝！","辋川图中景，米家船中物。","时悬吾心目，谁能相彷佛！","吾儿秉幼慧，游思造化窟。","湿墨入鸿濛，佳句出仓猝。","有画兼有诗，文字亦勃勃。","但此俱末艺，未可矜宝筏。","郑虔老画师，王维徒诗佛。","儒生抱膝吟，贵能知治忽。","区区笔墨中，小材同线袜。","右相驰丹青，局促伏堂阙。","庶子号浮华，承平空黼黻。","汝果为通才，须立邺侯骨。","早慧未足奇，老成斯卓越。","方今天地非，有才良拂郁。","沧海横流时，无才更沈没。","万卷床前书，供汝自除祓。","汝以艺为游，勿以艺为汨！","有成作班超，无成作楚屈！"]},{"t":"生四庶男志喜作","f":"五言古诗","c":["年华迫老大，生意近萧瑟。","陆沈海外仙，潦倒沟中瘠。","何意今年冬，艮男添一画！","秋柳发傍稊，晚荔挺偏侧。","赤足卢仝婢，累骑阮咸息。","我有望子心，素无誉儿癖。","未卜贤与愚，敢期过于轼！","今者溷伧荒，生才亦何益！","愿汝为贩脂，可以供索悉！","但我重诗书，斯文留一脉。","海东虽变迁，由东不移易。","区区盼添丁，时时望雄特。","等时汉子孙，而今沦外域。","童子执干戈，庶几卫社稷。","汝生在今兹，中原纷鼎革。","俟汝长大时，祖邦或保赤。","陶侃本庶支，壮志起宗祐。","愿汝作雄飞，补予为退鹢！","时势趋夷风，愿汝守孔泽！","汝生喜呱呱，我名戒赫赫。","汝祖有馀庆，汝辈食旧德。","曩年痛幼殇，心酸泪沾臆。","今年添幼孩，心快梦生翼。","姆养在西家，非同康乐匿。","他日携归来，有兄能汝惜！","汝在三母间，俱看为拱璧。","未知作阮孚，聊应呼谢客。"]},{"t":"书次儿槱十四岁所作山水画","f":"五言古诗","c":["余性爱山水，偶涉辄成趣。","引领东南峰，日夕起烟雾。","阴晴风雨时，崎岖心遥注。","重重丘壑深，无因得小住。","宗炳五岳形，空从梦中遇。","何意此图中，一一江山具。","石岩峭以幽，瀑泉奔而赴。","曲崖藏板杉，飞甍隐林树。","茅屋几人家，小桥通来去。","远塔想钟声，白云有深处。","僻径红叶踪，渔樵相对语。","回首望大荒，长江涵阴曙。","烟帆缥渺中，潮流变朝暮。","自昔郎士元，爱题潇湘素。","未若孟襄阳，洞庭任回溯。","吾儿有天机，恍入湖山路。","我神为之移，载发烟霞痼。","辋水出新裁，武陵寻旧渡。","一时玉笋班，两见虎头顾。","米家小米传，坡老小坡慕。","我惟裕文章，愿汝衣钵护！","况汝诗与文，妙才兼幼悟。","慎勿泥雕虫，自封龙驹步！"]},{"t":"大风述事五十韵","f":"五言古诗","c":["蛰居沧海中，阅世日迁变。","衡政与蜚灾，间出如剧战。","飓风拔海水，百年未曾见。","盲飙继狞飂，一月三怒煽。","台地百万家，纷糅成草荐。","丛林与枯株，飘空若散霰。","弱哉谷蓏卉，何从留葱茜！","未知上天心，胡降此怒谴！","年来时事非，民生苦熬煎。","粒米及勺桨，靡不入榷算。","敲扑竭脂膏，寝食俱锻鍊。","群毛燎一垆，旁观目亦眩。","何况切肤灾，能不双股弁！","僇人戴天韬，无地可逃窜。","督府施律条，己意即天宪。","寸法千犀皮，束缚南宫万。","朝行而夕更，惟官之所便。","嗟嗟海山民，作踊同屦贱！","瘦者供鞭笞，肥者供刍豢。","有土此有人，为奴兼为佃。","警隶穿门房，声雷而目电。","租吏没田庐，星移复物换。","国税及杂徵，所求过卵弹。","最苦逢掖徒，时时溺在冠。","市佣与贩脂，时时输银绢。","社会掠民财，政府为奥援。","士比鸾栖棘，民如雉带箭。","所陈百未一，人且疑谤讪。","我读孑遗诗，血声和泪咽。","奈何天助虐，斯民日涂炭！","戊戌洪水灾，山崩川潦漫。","人向吕梁沈，城似汾阳灌。","千村万顷田，茫茫无陂堰。","己亥复歉荒，穷黎绝炊爨。","岂有太仓赈，可救流氓难！","无田更追呼，租税不容缓。","室燬鲂尾赪，梁亡鱼肉烂。","丙午地大震，青天迷昏旦。","人物沦大荒，深谷为高岸。","潭潭九重渊，沈沈太华观。","哭声撼原野，惊魂怖里闬。","自从沧桑来，无时无危乱。","臲卼兵燹中，残生出刀碫。","疮痍未遽平，馀殄遭乾暵。","去年台北街，滔滔横流断。","今年全岛间，重叠风水涣。","有如尪病人，被曝县空半。","皇皇赤县倪，哀哀黑海畔。","饥溺望来苏，何日睹清晏！","我作大风歌，郁噫三再叹！"]},{"t":"感怀，寄郑毓臣闽中","f":"五言古诗","c":["行年戚迟暮，绿鬓悽已皓。","坐看儿女长，起视形容槁。","每月吹天风，频频望有昊。","浮世沧桑更，中原乾坤老。","到处有蓬蒿，逢人叹潦倒！","此地灾患多，尤恐不常保。","浮沈托伧荒，踪迹近舆皂。","身世一毛轻，中心百忧捣。","长风天地飘，愁怀不可扫。","祥凤窜荆榛，妖鲸宰蓬岛。","羡君闽海游，如入山阴道。","得尝武夷茶，胜啖安期枣。","嗟余在此间，腼颜向洞獠。","蹩躠罗网中，脱身恨不早！","林泉养懦夫，江山落衰抱。","因君豁壮怀，沧波流浩浩。","临风寄短诗，白日方东杲。","望望钓龙台，莫道归来好！"]},{"t":"暴风悲","f":"五言古诗","c":["星纪岁甲寅，闰五月中浣。","七日三暴风，农民惊跣袒。","海滨斥卤地，收穫尚较晚。","迤北气候寒，秀实亦迟缓。","一旦狂飙飏，千里野如刬。","长松犹拔根，何况禾稻短！","杼柚悉索空，谋生路已断。","惟望畎亩间，或可供缗算。","鸮炙喜见弹，时夜喜见卵。","茧抽虽至筋，甑爨已在眼。","奈何嘉谷登，忽作飞蓬散。","万哭同一声，天心不为转！","回思十年来，无年无水旱。","风雨既骄横，徵歛尤怪诞！","即如今夏期，役夫徵更悍。","沿门驱壮丁，百赎无由免。","占阄立刻行，一路同编管。","农务迫眉睫，驱去不容喘。","亦有谋脱役，中人多破产。","全台百万家，如篦如席卷。","仰天同呼号，抢地同忿懑！","或者上天慈，雨金救痌痯。","罔图天助虐，风害甚于暵！","四野黄如云，一扫禾无秆。","连番抟扶摇，万窍动空窾。","仰首望飞廉，三去复三返。","我在虚室中，胆碎心为戁！","空廪非所悲，窃叹农无饭！"]},{"t":"洪潦怨","f":"五言古诗","c":["东山水决决，西海水茫茫。","海隅十万家，乃在水中央。","问水何自来？","来自熬盐场。","盐场亦何益？","徒以充上供。","合赀作盐户，倾家受盐氓。","民为盐贫瘠，官为盐富商。","时无蜃蛤利，人有鱼鳖殃。","盐田百千顷，聚土海生桑。","有人收海市，无人浚海塘。","浊流出山谷，汎滥齐屋梁。","嗷嗷泽中雁，谁开洛口仓！","水害方竭蹶，水租乃披猖。","有田乏水润，到处徵水粮。","云欲修水道，顿增十倍强。","纳输或濡滞，抄没甚锒铛。","下户封衣物，上户封屋房。","水利民所有，乃为官所攘。","峨峨水租府，乃是东洋庄。","累累水租金，乃充东洋囊。","年来水荐至，灾黎溢四方。","食鱼思建业，饮水思武昌！"]},{"t":"饮酒感咏","f":"五言古诗","c":["我饮千日酒，愿作千岁眠。","岂谓酒中趣，欲配酒中仙！","惟酒忘忧患，聊以卒岁年。","况是黑甜乡，乃有黄农天。","出门寡欢好，丧乱悬我前。","人物釜中鱼，下有急火煎。","棋奕改墟市，朝夕变沧田。","陶潜漉敝巾，何处问醴泉！","糟邱课税重，一杓论十千。","将开谢瀹口，安得阮脩钱！"]},{"t":"见槱儿画兰感题","f":"五言古诗","c":["我爱郑所南，兰根不著土。","悬立海天中，旷若无所睹。","霜深雨露稀，幽寥自千古。","荆棘满世途，出门即豺虎。","藜藿亦乾枯，孤芳尚何取！","橘颂无回风，蕙荪成茅茹。","凤凰受诒笯，鸩鸠以为处。","户艾服盈腰，芳草迷故宇。","吾儿阶下秀，胸怀九畹谱。","诗中有骚心，画中有香祖。","相对情为怡，颇解尘埃苦。","虽在童稚年，已似兰生圃。","异时富根荄，破空出环堵。","我衰汝长成，荣枯互相补。","悠悠大荒东，行吟自得所。","何必沅与湘，始可培芳杜。","即此挥毫间，已是玉屑吐。","翛然倚江皋，臭味不余忤。","相期临清流，风骚绳素武！","尚留五柳居，待作三径主！"]},{"t":"将游珠潭路上即事二首 其一","f":"五言古诗","c":["一径上危峦，行行五十里。","遥望触口山，近见浊溪涘。","浊溪如瞿塘，洪流不见底。","触口如龙门，两山相对峙。","一过浊水村，草岭连天起。","回视所来山，复在深壑里。","山上复有山，水中复有水。","浊溪合清溪，渭源涉泾委。","暮入集集街，轻车如风驶。","四山锁千家，中峰结虚市。","夜来雨声多，溪声喧人耳。","曙色入高楼，云白天光紫。","我心急看山，冒雨行不止。"]},{"t":"将游珠潭路上即事二首 其二","f":"五言古诗","c":["此去山路艰，有似盘云栈。","峭壁摩深溪，摩崖行一线。","碧山号青城，悬泉落白涧。","飞瀑奔长空，雪花成匹练。","不到石门峰，宛睹匡庐面。","再见浊水溪，穿山去如箭。","阴晴无定间，山容千万变。","百险遇一夷，神舒目犹眩。","覆崖似破钟，云根系天半。","我行云窟中，梁悬山忽断。","舆夫行伛偻，林麓纷迷漫。","路入水里坑，渐觉岚光散。","过溪矗危峰，峨峨凌霄汉。"]},{"t":"四十初度感赋","f":"七言古诗","c":["我生四十度春风，风光过眼如落红。","看山、看水俱已厌，杜户长作桑苧翁。","翁今何事守室中，俊鹰绦辔鹤囚笼？","心志降下如降龙，倜傥迥不与曩同。","梁锽意气无禄位，苏轼头颅有隐衷。","岂诚徐积不婚仕，亦匪平子甘蒿蓬。","时异世非伏环堵，譬处眢井佩鞠藭。","陆行既愁虎狼恶，波行复愁蛟鳄凶！","繁华世界皆污染，迢迢惟有冥飞鸿。","我生素志殊崇隆，伏波、定远冀一逢。","不然殿像麒麟阁，龟兹作赋声摩空。","走马扬鞭白榆塞，珥毫抵掌甘泉宫。","或为遨游万里路，东探禹穴、西华封。","昆崙、弱水无不至，返棹小泊吴江淞。","神仙鬼谷寻崆峒，有兴要登泰岱峰。","奈何憔悴羁海外，平生百愿无一从！","乾坤无家我无往，五岳空自罗心胸。","庄生幸能齐得丧，儒仲亦颇忘穷通。","呼马、呼牛靡不可，为龙、为鼠皆甚庸。","年来百念况灰尽，伏雌殊不羡飞雄。","陶潜只为菊秫计，陆倕思以田亩终。","山与鹿麋水与鱼，春听禽鸟秋听虫。","便便妙腹诗书饱，轣轣枯肠藜藿充。","妻孥酌酒为我寿，谬以少微当高崧。","灵均庚寅、我丙寅，愧无兰芷降吾躬！","劫中乌兔双丸速，倏忽十载过辽东。"]},{"t":"閒居遣怀放歌二首","f":"七言古诗","c":["生天当在诸君后，成佛要在诸君前。","居前不肯使人轾，居后岂肯使人轩！","丈夫抑郁居世间，谁为浊清谁愚贤！","泉石巢、夷与握臂，庙廊伊、葛与比肩。","尔时雌黄俗人眼，妇竖毁誉皆可怜！","至今陋巷有千秋，当日东家无一廛。","我生位置将何处，吟哦七字或可传。","后有渭南、前青莲，世上浮名尘与烟。","所叹岁月华吾颠，再见沧海为桑田。","平生钓龙屠鳌手，放废一朝到九渊。","走狗斗鸡称行辈，来牛去马同神仙。","素丝可缁石可磷，要存吾白完吾坚。","解衣盘礴画图史，散花烂漫女婆禅。","糊涂羹对鸱夷酒，裸袒二虫作周旋。","晞身阳阿濯汤谷，出入渣滓冥冥先。","上至列缺望大壑，峥嵘无地廓无天。","南海帝倏北海忽，何日回斡成大千？","我时腰缠骑鹤去，谪仙一醉三千年。"]},{"t":"风雨感事","f":"七言古诗","c":["楼头暴雨兼暴风，扬沙走石声挣摐。","四山漠漠如泼墨，海上龙尾捎长空。","云垂海立不知际，天低若笠幪阴翳。","怪道乾坤不肃清，年来风雨皆残厉。","三宵两昼无霎停，饥乌冻雀拖湿翎。","荒林鸟呼泥滑滑，破屋花泣雾冥冥。","陇上老农荷锄叹，太仓玉粒今摧半。","去汝难逃鼠食求，愁余那更狼戾看！","九衢百巷见谽谺，杜陵空怀十万家。","天半老茅为败絮，云边碎瓦疑飞霞。","去年南部遭地震，万室黔黎归一殡。","井落陷崩入蚁封，山川裂坼成龟亹。","吾台处处生劫灰，人物时时供馀烬。","前朝痛哭声未终，今日悽酸泪成阵。","戊戌、己亥连两灾，田畴一望为蒿莱。","悬崖万丈发暴潦，平地千家入湍豗。","眼前风雨特小耳，何容伤心作歌纪。","俯视雷霆抵婴儿，未信人间失箸匕！","海上烽烟犹不销，世上浮霾宜如此。"]},{"t":"欲辟荒榛感作","f":"古风","c":["延秋门中白日昏，??鸺鹠舞蹲蹲。","城狐欺人怒乘屋，野狼衔肉走冲村。","千丈废台为窟穴，万年古树长儿孙。","天阴雨黑声崩奔，草木森森啼断魂。","左邻右舍皆流徙，出门千里无鸡豚。","人类稀少兽迹蕃，变迁城市如荒屯。","岂惟城市不可见，下穴上巢绕畿甸。","愚公顿起移山心，急携锹锄效填竁。","烈炬焚橑火四煽，高呼鼠辈来鏖战。","驱除未终心忽艰，方今暴虎方出山。","夷狄横行入人间，髑髅头颅堆阓阛。","宫殿为墟钟簴失，神皋万里血痕殷。","沈沈天帝闭天关，不闻射狼天弧弯。","何为在此争么么？","枉费钜功斗众顽。","须扬长剑倚天外，神奸巨憝供削剬。","平铲大地为泰坛，九州四海歌安澜！"]},{"t":"登望，不胜今昔兴衰之感；慨焉贼之","f":"七言古诗","c":["东望青山西望海，海山苍苍犹未改。","陵谷荒凉人物衰，海上空留涨痕在！","往年海上浮汉槎，牛斗星辰路不差。","稛载珠玑通越峤，运输琛赆贡京华。","楼船岁揽洋川米，津市春封北苑茶。","齐地鱼盐兼蜃蛤，秦山竹木连桑麻。","牛羊孳乳量千谷，朝射豪猪暮糜鹿。","渔山猎水不可穷，虞泽衡林曷胜牧！","云梦藷蔗伞山糖，玉屑琼霜煮豫樟。","江陵之橘洞庭柑，锡山有金号不祥。","其馀百物纷难谱，飞走植潜踰郑圃。","田上上错赋中中，东南海岱称腴土。","为忆台湾全盛时，举袂成幕襼成帷。","土木衣锦兽粱肉，馀粮栖亩民无饥。","处处耕凿人歌舞，家家纨绮户书诗。","只今版图沦化外，万方玉帛无王会。","民间衣食尽锱铢，闾左生谋皆课最。","细针密缕无所逃，零落衣冠为驵侩。","事后争思故国宽，眼前虏尉仍虏官。","新丰鸡犬何家入？","举头但见海漫漫。"]},{"t":"自赋","f":"七言古诗","c":["威仪汉世已无馀，陆贾越台犹著书。","图形不到凌烟阁，闭户自甘子云居。","天荒地老无闻见，过眼沧桑皆若虚。","志气自昔撼山岳，乃今局促随卷舒。","世上呼牛或呼马，意中为龙又为猪。","当前寄托蚊双睫，随处揶揄鬼一车。","闻道汉廷方变法，屏弃八珍嗜羊菹。","不信衣冠舞鸲鹆，竟然钟鼓乐鶢鶋！","我自倔强风尘外，习气不为时世除。","褐衣皂帽欲千古，金石之声出草庐。"]},{"t":"地震行","f":"古风","c":["维岁丙午月刚卯，天柱倾颓地轴挠。","星辰易位山川崩，五行二气同纷搅。","日月未悬天未开，大造莽莽飞黄埃。","巨灵怒劈太华来，坤舆斮破声如雷。","六鳌断足化黄能，娲皇一见心为哀！","哀哉城郭阛阓为蒿莱，血肉肤躯为废骸。","高岸深谷何所有，不见人烟唯阴霾。","初如大块抟抔土，神工鬼伯擂地鼓。","人寰簸荡无立锥，海水翻腾有飞弩。","惊心下界多游魂，转瞬九渊欲沈羽。","陷落诸罗十万家，人物邱陵尽泥沙。","四海龙战玄黄血，千山龟坼纵横叉。","不信乾坤又灰烬，可怜髑髅皆齿牙！","哭夫、哭子、哭父母，惨淡往来鲁国髽。","岂知蓬莱昔翻覆，神山久已沈大陆。","地上龙蛇多杀机，民间鸡犬争觳觫。","虽有孑遗半死生，阿鼻牛首怒狞狞。","暂偷食息鱼游釜，终见漂流蚁满城。","天心如此已可叹，何为此遭益糜烂！","当今有几虮虱臣，浩劫无穷裸虫患？","欲排阊阖问天公，天关沈沈漫复漫。","俯视罗山斗六门，山飞川走坤维断。"]},{"t":"后地震行","f":"古风","c":["忆昨甲辰冬十月，千里江山系一发。","高岸为谷深为陵，蓬莱沈没金银阙。","城郭人民半已非，汹汹江山空四围。","无头、无目刑天舞，一手、一足商羊飞。","堆积残骨成京观，哀我遗黎何所归！","疮痍满地今未已，乾柱坤维复倾圮。","共工巨颅撼不周，竖亥大步移方里。","诸罗、斗六百里间，天崩地塌雷霆起。","至今日月尚摇摇，石破天惊震不止。","洪荒欲沌复欲分，寥廓不流亦不峙。","颠簸晦明动星辰，城市如悬虚空里。","震后赤日行曈曈，雷师为暴驱靊霳。","幕天席地十万家，哀哀哭泣洪流中！","重黎祝融复交病，翻覆阴阳纷七政。","赤乌衡维热燄张，烛龙炎井火珠迸。","闻道天上杀机流，一空十日烧九州。","地上杀机在洪水，䆕䆷方壶沈丹邱。","天韬、天械无可逃，旋倾大地添狴牢。","岂其万物成刍狗，无复四维联巨鳌！","呜呼东瀛今已沦大壑，细者沙虫大猿鹤。","世界大千输一粟，窃叹陆沈天地酷！"]},{"t":"望张汝南故居感赋","f":"楚辞体","c":["云山万叠君所居，中有当时旧精庐。","四面桄榔杂花竹，一窗琴对一床书。","当日与君坐谈处，花发鸟啼不知曙。","问字车常载酒来，寻诗客共扶筇去。","君家风雅弟与兄，讲理人称鲁二生。","气谊于时不易觏，功名与我竟无成！","今之身世凡几变，我思君兮不复见。","遭乱已沦焦尾桐，怀人空抚米家砚！","台湾山水海东稀，江山犹是、民物非。","叹息乾坤随水逝，何时风雨招魂归！","回头恍见罗山树，经帷冷落遗孥住。","月缺星阑北斗斜，屋梁颜色梦中遇。"]},{"t":"遣意漫赋","f":"七言古诗","c":["足下碧落凌三千，胸中云梦吞八、九。","不能富贵求神仙，惟有读「骚」痛饮酒。","少年乐水兼乐山，适兴问花更问柳。","此日落拓无所营，穷愁老景来相守。","丹药难驻玄发身，䌟絖空作不龟手。","甘罗既相邓禹侯，笑余四十徒腐朽！","世外自负龙凤姿，山中惟将麋鹿友。","欲免衣冠优孟容，永甘形块哀骀丑！","迩来伛偻循墙走，独坐无朋行无耦。","纷华我知亡是公，流俗人唤支离叟。","尘途有迹风怜蛇，沧海无情云变狗。","季野满腹储阳秋，强与旁人相可否？","百鍊刚肠绕指柔，偶生芒角浇一斗。","不平时作老龙鸣，长啸却同狮子吼！"]},{"t":"遣意再赋","f":"七言古诗","c":["世间已置六尺躯，身上犹存三寸舌。","南溟之鹏、北海鲲，屈伸变化归一瞥。","我生肮脏四十秋，如何枯株长守拙。","闭门郁郁无所为，如头受髡足受刖。","扬尻欲作万里行，车已无轮马无軏。","干将生就百练钢，峣峣之齿坚不缺。","年华一耗身渐柔，䰄䰄者须、星星发。","冥心思与大化游，蛇困求蜕、蝉求脱。","造物闭我糠覈中，鼠肝虫臂徒生活。","爱我谓我有用身，恶我笑我穷死骨！","我自浑沌随造物，满腔藏有苌弘血。","世途列子悲湿灰，歧路杨朱泣回辙！","傀儡新自西洋来，黥钳大为我辈设。","我已土苴视功名，时犹衮冕矜阀阅。","破坏仁义真穷奇，均输食货亦饕餮。","江湖魏阙同一邱，愿从泥龟作跛鳖！"]},{"t":"吸烟戏咏","f":"七言古诗","c":["九华仙子餐沆瀣，薜荔衣裳芙蓉带。","七宝盘匜百宝床，龙嗡鲸呿天地隘。","葡卜宫中火不衰，樱粟堆里香常在。","独衔金茎饥凤吭，孤倚玉筱瘦蛟背。","琼钟瑶席甘露浆，黑雪玄霜紫云霭。","灯闪长鸣窸窣风，斗收佳气氤氲界。","不夜城中得滥觞，常燃鼎上欣津逮。","癖嗜已同九转丹，创惩未要三年艾。","曩弃书剑求神仙，仙人谓我须淘汰。","入尘已似鼠拖肠，离世何望蝉脱蜕！","流连饮啄真籧篨，散诞形骸总疣赘。","教我且学不死方，烟霞之里垢尘外。","入山采朮兼采芝，青精有饭黄精代。","愧我尚恋烟火缘，未能绝物待沾丐。","蕙兰膏后金粟膏，仙人掷米弄狡狯。","引我漫居大沫天，置身遂入须弥芥。","有时卧游上九霄，有时魂游空五内。","燥吻惟濡陆羽茶，馋情却谢元修菜！","藉兹冀免俗氛侵，不治未是南山秽。","罗什有道吞乱针，游戏神通何介蒂！","晞发阳阿下大荒，久邻山魈木石怪。","御气身与造化游，陆地行仙才莫坏！","甜乡休道烂如泥，糟邱须知肉不败。","与人无闷世无怀，扫愁有帚诗有械。","揶揄或谓穷骨头，颠倒拚作尸居态。","邯郸一枕梦黄粱，洞府三清伸白喙。","雾液云腋流玉酥，鸾胶凤髓含金薤。","太乙然火三千年，一吸冲虚无大块。"]},{"t":"悼林乃营并及诸亡友","f":"七言古诗","c":["总角之交五、六君，存者如星散如云。","如何一年弱一个，数到林逋泪已纷。","三施、二张杨、丁、李，其间汝南最超群。","令威亦具神仙骨，化鹤一去遗榆枌。","又有廖、许及陈、蔡，同安古辈杨鸿文。","三水诗人梁钝翁，典型尤遽痛虎贲。","其一老者杨广文，溘先朝露谁告存！","及门数子亦堪悯，何笔、洪文并足论。","临终百里待师友，雾车风马吾宗闻。","邦瘁人亡痛已矣，胡为招尽林皋魂！","林君订交尤最早，潦倒无成最蹇屯。","遭丧我忝脱骖列，求友君从刎颈抡。","往时令兄推善画，古壁下笔烟云分。","墓门宿草今十载，残缣断墨风雨吞。","遗孤虽在殊零落，与君幼子成弟昆。","哀君病不在寝室，吊君死不返里门！","如斯逝者如沤幻，使余有泪难手扪。","平生无限知己痛，因君一夜雨倾盆。"]},{"t":"荒城秋望","f":"古风","c":["偶上城南冈，遥望城东道。","长林漠漠不见人，夕阳远树连芳草。","八卦山头旧寨平，石虎新遗赵王堡。","于今辟作游人园，行人凭吊迹如扫。","俯视城市半已荒，廛店折毁成空场。","昔日飞甍楼观地，今馀乱瓦堠堆傍。","废残虽已修，零落尚凄凉。","无家、无室千馀氓，散为哀鸿之四方。","回头望大道，大道直如弦。","中有平民十万田，铲除畎亩无陌阡。","嵯峨见阛市，有伍、有章似方里。","但是烟火万人家，一朝苦雨悲风起。","日落无声鸦影多，牧夫樵竖动哀歌。","无限沧桑经海岛，那堪荆棘遍山河！"]},{"t":"忆昔日航海感赋","f":"七言古诗","c":["忆昔饱帆出台湾，一瞥已过澎湖间。","千里、万里海色尽，又看山色入闽山。","山山重叠虎门关，束缚波涛锁烟鬟。","茫茫一海枕群峦，入港豁露青山颜。","高台峻垒枪炮环，战场已过馀疮瘢。","城郭险距青天半，制船巨厂成市阛。","我时停泊泛小艇，登山四顾天地宽。","风雨独凭酒楼望，烟波忽送千舟还。","一夕乘流向闽郭，钓龙台古壁巑岏。","泉亭茶榭闻歌管，楚些越歈杂悲欢。","出闱夜上乌石冈，中秋城月大于盘。","望月兴阑长太息，何时获遍五岳看！","浙、吴咫尺不能到，秦、蜀微茫更无端。","是时人物乐升平，未料沧桑有翻澜。","胸中私愿冀一遂，要当骑鹤上长安。","岂知此景犹眼前，闽城不到十馀年。","瀛海已变千桑田，埋头顿似藏九渊。","一望江山色如赭，每闻花鸟泪犹泉。","莽莽市朝落残局，沈沈人世随逝川。","投河已愧申屠狄，蹈海尤惭鲁仲连！","亦欲化鹤归辽天，辽东华表迷荒阡。","当时犹自悲落拓，只今何处伤沦涟！","盛衰兴废真一瞬，回头万事云霄悬。","往迹旧游何可问？","海上日日扬尘烟。"]},{"t":"与金陵士人话所过山水","f":"七言古诗","c":["我居海外蓬山间，蓬莱海浅湾复湾。","有山、有水无佳窟，听风、听雨愁心颜。","闻道江乡是佳处，烟花如海莺啼曙。","但恨违隔万重山，骑鹤扬州无路去！","意境频频入梦中，非游浙北即江东。","拄杖依稀三楚月，乘流彷佛五湖风。","今日遇子中华至，山川都作枕中记。","虎踞龙蟠北固亭，鹤归凤去南屏寺。","水竹三分月二分，君家正在江南村。","丹枫远远秋开径，黄叶萧萧昼闭门。","秣陵居士西陵客，有时苕霅为浮宅。","郭外常看四明峰，剡中遥拥千溪碧。","适兴即登旧酒楼，莼羹鱼脍楼上头。","苦竹城西人似水，富春江上月如钩。","斯景窃思分一半，君忆家乡遂三叹！","寻亲身带岛夷烟，作客舟居沧海岸。","座中对语各婆娑，沃洲外有汉山河。","何时收入黄图里？","鹿耳、鸡笼岛屿多！"]},{"t":"閒居书事兼述怀","f":"七言古诗","c":["富贵可轾亦可轩，贫贱居后如居前。","夙昔摊书拥万卷，铭功直欲上燕然。","有时萧寺划齑饭，魂梦复在韩、范边。","不然著述老一世，「东观馀论」、「南华篇」。","胡为浮沈至今日，海屋之畔沧桑田。","负郭洛阳非二顷，耦耕河渚乏一椽！","假与沮溺为伴侣，催敲箕敛来熬煎。","新丝未足供洋税，新谷何能办户钱！","东家养犬罚里布，西家捕鼠输府泉。","警吏穿门时入室，圆木警枕难安眠。","桃园无处居渔父，梅市何地容神仙！","邱山华屋尽零落，逃氓废圃馀荒阡。","暂时读书把耒耜，如登雪岭披黄绵。","闭门深夜慕怀、葛，挑灯课子开韦编。","五经、五典如日月，肯为乱世相轻捐！","逍遥世外亦一计，自颠、自倒忘倒悬。","惟怜一生怀壮志，经术、经济成虚诠！","糜烂尘寰无净土，隔篱何点聊穷年。","星槎倘可天上泛，凿空窃愿随张骞。","造物彼苍何阨我，土人桃梗相为缘！","不知何时堪解脱，骈枝大块殇彭篯，胚胎或免天帙缠。"]},{"t":"送客归浙","f":"七言古诗","c":["浙东此去三千里，海上蓬莱隔弱水。","君归正值鲈鲙时，轮船一日秋风起。","钱塘八月潮头高，君归好趁曲江涛。","旧时范蠡浮舟处，未似君跨海上鳌。","与君相逢在顷刻，与君别离成夙昔。","寄语中原乐土人，莫作海岛居夷客！","君居武林山水乡，西湖绿柳接红樯。","山阴饮禊兰溪曲，风渚渔陶苕水傍。","我居局促海山畔，山花、山鸟纷愁乱。","鞭扑追呼过虎苛，茧丝抽索如鱼烂。","年来山水益萧条，山林斮赭如焚烧。","四海五湖深锁闭，千峰万嶂空嶕峣。","乘风我欲随君去，葛洪未备移家具。","神仙暂作陆沈身，日月漫迟夸父步！","登高遥望云海东，浮帆一点暮天红。","知君亦有烟霞窟，他日相寻钓浦中。"]},{"t":"题近人所作「桃源问答游叙文」后","f":"七言古诗","c":["传说桃源时避秦，千年一到武陵人。","鸡犬鲜逢山外物，桑麻未识世间春。","兵燹徵徭是何事，问津逝者葛天民。","源里遗民纷纷说，秦时苛政如火热。","六国子孙多系累，天下儒生半坑杀。","男儿负剑到长城，妇女纫针入南越。","我闻斯语犹未终，秦民怒发冲冠中。","秦时纲纪虽近暴，惨惨犹存华夏风。","百年礼乐未崩坏，三代车书尚遵同。","以暴衡暴祇百一，秦罪已是邱山崇。","岂似我今□化外，非法横施来自郐。","刀锯日日供牺牲，鞭扑朝朝催课最。","无丝、无苗亦税科，有丁、有户皆头会。","俎豆古风弃弁髦，衣服新制留蛮襘。","神山千里尽沦胥，文物一朝随芜秽。","穷奇食人口有牙，蚩尤为兽翅生背。","相逢不作同等看，胡髡越裸丑周冠。","颠倒天行无历纪，邱虚郡县有戈干。","饥饿夷、齐失薇蕨，艰难黄绮在商山。","秦时容得桃源在，桃源经今亦迁改。","忽荒净土与仙津，阨窄五洲兼四海。","秦人今更去遥遥，惆怅渔郎不相待！"]},{"t":"看山写怀","f":"古风","c":["我居市廛间，恨无青山绿水环。","山人在山里，日夕峰峦烟雾起。","山人对山不解吟，孤负山水有清音。","我生能诗乏山住，失却画本无佳句。","倚楼遥望翠微巅，春来、春去迷红树。","座中有客话山容，山东有竹西有松。","山村月出催沽酒，山寺云封闻打钟。","泉声鸟语供清听，昏曙阴晴尽诗兴。","安得移居入深山，登山看海澄如镜。","山人阻我莫移家，山中无虎有苛政。","城市尘埃不易居，山林徭役亦难应。","丹灶无宽宏景庐，蓬蒿还隘羊求径。","不须歌啸慕渔樵，万水千山鲜乾净。"]},{"t":"近年薄置田亩，拟待拙著集成，变鬻以供剞劂。特恐所作不值一文，不免詅痴符之诮也。诗以志之","f":"七言古诗","c":["吾也作诗豫买田，为口腹计谋朝饘。","他日诗成待传后，吾卖吾产刊遗编。","此志非奢良易遂，此笔再支三十年。","古人名山俟友声，韩公学有欧公延。","张为曾诩奉白佛，李洞亦闻铸浪仙。","今人爱才非昔比，龙华会乏香火缘。","同时或邀众口谤，异时安望众目怜！","「太玄」子云当瓿覆，「春秋」吕氏空门悬。","况余诗文求自适，不期众好宁非偏！","冰心自携冰一卷，古调独弹古七弦。","高希万载羲皇上，旷游八极鸿濛先。","放笔洪涛走淜湃，冥心造化归镵镌。","咸韶欲招里耳听，如置石鼓伶人前。","倘售鼠璞自衒异，或怀燕石私蹁跹。","千金换取麻沙版，如珠弹雀玉抛砖。","况破百亩灾梨枣，实益枉为虚名捐。","繄余名心终不死，子孙之计非所牵。","阡陌连云亦安用，城南二顷更戋戋。","有诗有文堪掷地，无衣无食足登天。","王充或作枕中秘，桓谭有待身后传。","吾书不胫走天壤，室中遑恤灶无烟。","惟愁白傅将笑人，诗成未得鸡林钱！"]},{"t":"生圹诗歌第八，即以为跋，并靳谢老","f":"七言古诗","c":["我与谢君尚生面，号咷尺素修相见。","托友来求生圹诗，要余当作生刍奠！","笑君欲听雍门琴，笑君不来谀墓金。","只鸡斗酒桥公事，异时腹痛莫相侵！","我非食友非死友，平生未剪庾郎韭。","如何表圣携鸾台，竟望原壤歌狸首！","闻名墓下独优游，山中猿鹤自春秋。","谢安不与人同乐，谢敷偏欲人同忧。","稽康日日惟养生，范燮时时复求死。","山川尚悲陵谷迁，人物岂有安全理！","一笑张融欲凌云，手执「法华」与老君。","君藉我诗或不朽，我嗥君返倘无魂！","自昔诔铭关素行，必待盖棺论乃定。","谢老依然肉食身，奈何丐我虞歌赠！","我欲向君一呜呼，奈君健啖颜如朱！","骨相未是枯髅枯，肉相宁比臞仙臞！","我欲向君试调笑，墟墓之间又宜吊。","真卿旷达虽可思，方朔诙谐殊未妙。","占星我非大王公，君非岁星亦难料。","漫储一腔块垒词，借君一抔浇一卮。","及今未泣洹水玉，劝君且进商山芝！"]},{"t":"米贱感赋","f":"七言古诗","c":["曩者我未有田时，米贵如珠难作糜。","今时我有田数亩，米贱无从易升斗。","米贵我昔为伤心，民贫恨天不雨金。","米贱我今夜长叹，租入难供赋税半。","赋税如何底许多？","中田今升十倍科。","正税之外有附税，税外加派更繁苛。","犹幸今年歌大有，无钱有米可糊口。","倘或年时遇半荒，村南村北皆饿叟。","但是农家今亦艰，买牛雇直钱如山。","有米贱粜须官检，玉粒难入东洋关。","农家租户何须苦，催科刻日严如虎。","无田亦有人口徵，百物锥端皆榷估。"]},{"t":"书次儿槱十四岁所作史论后","f":"七言古诗","c":["时势变迁一至此，读书今已无种子。","仁义道德等籧篨，粪土「五经」、「廿四史」。","吾儿闭门读典坟，吾与汝作羲皇人。","世风不染欧、非、美，时事遑知魏、晋、秦！","姑从故纸讨生活，三国、六朝最樛葛。","英雄竖子一刹那，氐、羯、匈奴况豪末！","汝幼读书慧眼悬，他时见异勿思迁！","经济吁谟获机括，新法西学皆蹄筌。","此间教人限等级，有如蛣蜣宝丸粒。","吾家幸不随步趋，汝辈惟当安诵习！","闻道中原大改更，用夷入夏日勾萌。","不信秦嬴遗祸火，至今商、洛发儒坑。","我自不求同时世，授汝一经为一艺。","仕夷早已鄙刘殷，猾夏今更轻后羿。","屈指于今十八秋，阅人阅世真蜉蝣。","河山百战蛮蜗角，寰海千邦楚沐猴。","人才今生殊抑塞，有如黄杨当闰厄。","苏轼愿儿为八慈，陶潜训子望三益！","海外方今禁读书，乃公将史作菑畬。","治身、治世知治乱，一编何止伴閒居！"]},{"t":"过彰化废公园感赋","f":"七言古诗","c":["古榕寥落杂枯树，喷地一泉自东注。","泉间茅舍覆僵石，水外疏杨当狭路。","野鸟时时啼向人，园林无主飞灰尘。","到处病藜成瘦腊，入围荒草溷残茵。","游人来往悲丘壑，梧桐脱皮筠脱箨。","两部曾无给廪蛙，一庭岂有乘轩鹤！","年来我过东郭门，郭外人家半空村。","郭内人家半旷原，破碎门墙鸟雀喧。","其他凋零不可道，其故瑰怪良可言！","自从事事效欧、美，街衢方罫划井里。","游吉毁家为当途，晏婴徙宅因近市。","即看此地辟游场，小害亦同花石纲。","一草一木尽民力，有台有观皆民房。","谬云此事同民乐，一夫为乐万夫哭。","黔首家家戴覆盆，金钱日日填卢谷。","有人蒙羞像范铜，民膏民血涂身红。","此间差喜无此像，可怜尚带东洋风！","就中园景方增筑，已无佳处豁心目。","况当官署纷奕棋，不免童山随翻覆。","如今山水已邱墟，纤风缺月亦无馀。","园中不见三分竹，园外空过独辇车。"]},{"t":"有感书臆","f":"七言古诗","c":["平生豪气未一唾，蓦地惊人乾坤破。","胸中五狱何时平，囊里一锥已先挫。","忆昔少年意气奇，赤手欲缚蛟鼍螭。","潜移岱华翻大海，旦夕饮马东溟池。","区区心事托毫素，贾生万言、曹七步。","厥词一放走轰霆，并并二豪惊顾兔。","琳琅蚀月千明珠，翕霞九尺珊瑚株。","沈埋黄土一千丈，犹与丰城剑气俱。","一朝海水湮旸谷，方壶沦入鲸鱼腹。","娲皇竟断六鳌维，龙母坐看万鲛哭！","此时惨甚幽九渊，倏忽星周二十年。","玄黄有血膏原野，冥漠无知怨昊天！","我比苌枝漫猗傩，寒暑如邮日如火。","久拚斯世混伧荒，岂与外人为蜾蠃！","却叹樗材寿此身，千秋万古一微尘。","未来衰老病死苦，先是支离臃肿人。","人生末路竟如此，不作龙头作狗尾。","纵教扬子传「太玄」，已似马公成腐史！"]},{"t":"题次儿槱诗文卷","f":"七言古诗","c":["怪汝作诗如作画，笔扫风云驱百怪。","爱汝作文如作诗，潘江、陆海有馀漪。","郑虔名成老画师，传作未见垂当时。","王维有画兼有诗，绝妙未见兼文词。","古人专精在一艺，不尚誇多尚传世。","画虎一事倘无成，鼫鼠五能亦俱赘。","吾儿可有兼人才，行年十四、十五才。","天赋汝能天禀粹，天富汝年天骨开。","儿乎多能吾所许，儿乎末艺吾不与。","文章要须气节高，文学尤须经济举。","乱世人才安足多，扣牛宁戚徒悲歌！","台海波涛今漆黑，中华世界方蹉跎。","吾今与汝守蓬荜，吾老一任东隅失。","望汝怀器伏人间，或□扶桑作晓日！"]},{"t":"乙卯重午","f":"楚辞体","c":["五月五日吊屈原，六日又当吊台湾。","台岛此日蛟螭蟠，户三百万海漫漫。","海底残魂招不起，三百万人同日死。","髑髅鞟骼郁嵯峨，虎狼戛戛磨牙齿。","彼一人些千古伤，全台奈何不断肠！","羌沈江兮羌沈海，黑风毒浪鱼龙僵。","昨夜雷门擂大鼓，羵羊蹩躠商羊舞。","灯火煌煌黎邱市，旌旂窣窣修罗府。"]},{"t":"痛断发","f":"七言古诗","c":["我生局蹐何不辰，垂老乃为断发民！","披发欲向中华去，海天水黑波粼粼。","天为穹庐海为壑，桃源路绝秦中秦。","况是中华亦久变，发短更甚胡中人。","吴绳虽约难为纶，且留尺寸来反唇，国人姗笑倭人瞋。","我生于世一微尘，我头一发回千钧。","科头违世廿载匀，戴之如山五十春。","垂之亦自嫌剡剡，断之夫岂能彬彬！","山鬼怂剑躐余后，晞汝阳阿归陶甄。","在笯可怜断尾凤，遁荒须跨无角麟。","托迹伊川昆吾野，苍浪种种嗟沈湮！","冲冠此际无轮菌，惭颜懒被华阳巾。","惟有晋时无颜帢，称是头颅堪同寅。","古者有罪科城旦，维髡与钳为一伦。","穆生不设醴酒醇，吾不能去空嶙峋。","屈原散发遵枉渚，吾将骚首问苍旻！"]},{"t":"蓄发诗","f":"七言古诗","c":["不欧、不亚亦不倭，我发虽短未媕婀。","我头不与人同科，可屈、可伸奈我何！","垂垂渐觉成盘螺，有如玉山长嘉禾。","不似童山空峨峨。","随俗不随乡人傩，老子头颅聊自摩。","任人讪笑语言讹，闭门缩颈甘藏窝。","道逢狞吏掩而过，抱璧相如避廉颇。","自笑杨朱为一毛，有惭肤挠与目逃！","几茎衰发奚坚牢，如斯时世须餔糟。","但余未能从时髦，耄矣老夫爱皤皤。"]},{"t":"岛上本事四首 其一","f":"五言绝句","c":["见说江南好，谁知海外奇！","一天环一岛，万嶂碧琉璃。"]},{"t":"岛上本事四首 其二","f":"五言绝句","c":["海外更无海，山中复有山。","鹿麋千岁角，松树万年斑。"]},{"t":"岛上本事四首 其三","f":"五言绝句","c":["年来沧海浅，津路亦生桑。","万点鲛人泪，明珠夜不光！"]},{"t":"岛上本事四首 其四","f":"五言绝句","c":["不道深山里，更扬大海尘。","烂柯秦地客，煮石葛天民。"]},{"t":"登临感赋二首 其一","f":"五言律诗","c":["寥落八闽路，萧条大海东。","秦馀人物痛，汉外河山空！","地已中华尽，时犹故国风。","武陵不可见，鸡犬亦难同。"]},{"t":"登临感赋二首 其二","f":"五言律诗","c":["海上山长在，人间世已非。","中原天万里，远地日孤晖。","水阔闻鲸吼，云遥羡鸟归。","不堪搔首处，风景尚霏霏。"]},{"t":"山后即事二首 其一","f":"五言律诗","c":["处处箐篁密，人番溷错居。","鹿场秋出猎，鲛岛夜停渔。","月大青山近，星稀碧海虚。","忽惊峰嶂赤，烧火起箖烟。"]},{"t":"山后即事二首 其二","f":"五言律诗","c":["猎户连丁灶，藤寮石火敲。","蒸林樟出脑，炼水角成胶。","熊爪惊穿树，麋茸逐解苞。","凶番雕面见，颅骨满居巢。"]},{"t":"岛上","f":"五言律诗","c":["岛上事萧萧，重关阻客轺。","云封闽海雨，水落浙江潮。","淡菜高丽脆，樱花日本娇。","谁营南北路，十载始通桥？"]},{"t":"海上","f":"五言律诗","c":["海上人何在，乾坤信渺然！","沧桑澎岛路，风雨晋江天。","未尽庚申世，旋周甲乙年。","寰瀛今已隘，沦落竟华巅！"]},{"t":"岛咏二首 其一","f":"五言律诗","c":["孤岛云烟异，戎风丧海邦。","西航无两粤，东载失三江。","鱼鸟魂难定，蛟龙气不降。","家家空汉腊，久矣语言哤。"]},{"t":"岛咏二首 其二","f":"五言律诗","c":["骈杀及狉獉，深山亦劫尘。","禽残桑下雊，狝尽郭东㕙。","洞穴无安土，穷荒有剧秦。","时时枪炮震，知是剿番民。"]},{"t":"内山二首 其一","f":"五言律诗","c":["古径行踪少，纵横开野花。","翻山无䝤洞，汲水有人家。","万灶烟蒸脑，千棚地种茶。","谁能筹本计，僻壤教桑麻！"]},{"t":"内山二首 其二","f":"五言律诗","c":["再入深箐去，穷荒似鬼门。","山熊推树倒，野豕触人奔。","颅骨供神社，藤皮结䝤村。","蝮蛇当径立，过客有惊魂！"]},{"t":"大墩即事","f":"五言律诗","c":["偶向毬场过，消閒兴不虚。","电传千里话，风走独轮车。","市卖高丽菜，船来日本鱼。","插标农圃里，倭客课耕畬。"]},{"t":"柬梅樵三首 其一","f":"五言绝句","c":["闻君向南投，曾过北投宿。","试从鹿水头，一续「乌溪曲」。"]},{"t":"柬梅樵三首 其二","f":"五言绝句","c":["君有渭城诗，合饮宜城酒。","月下请高歌，燄峰九十九。"]},{"t":"柬梅樵三首 其三","f":"五言绝句","c":["昨日扣柴门，相对语言温。","一别何时见，夕阳浮景村！"]},{"t":"港口望帆船","f":"五言律诗","c":["港浦水迢遥，帆樯久寂寥。","云迷瓯越路，岸断广州潮。","闽舶空来往，倭关阻贩消。","微茫烟霭外，况见海门焦。"]},{"t":"送客上海三首 其一","f":"五言绝句","c":["君向淞江去，江东月正明。","回头闽海外，无限乱云生。"]},{"t":"送客上海三首 其二","f":"五言绝句","c":["一水入东吴，吴中旧有都。","武昌鱼味好，莫羡四腮鲈！"]},{"t":"送客上海三首 其三","f":"五言绝句","c":["地是中原迩，居偏外国环。","华夷人语杂，未是好家山。"]},{"t":"风空岭即景","f":"五言绝句","c":["水远明于镜，山多拱若城。","浊溪双峡雨，石瀑万峰声。"]},{"t":"大墩公园杂咏十二首 其一","f":"五言绝句","c":["行行去市阛，苍苍花木环。","东来最佳处，墙外有青山。"]},{"t":"大墩公园杂咏十二首 其二","f":"五言绝句","c":["前池浮荇藻，后槛倚芙蕖。","临水知鱼乐，无人可比鱼。"]},{"t":"大墩公园杂咏十二首 其三","f":"五言绝句","c":["透漏澎湖石，婑媠江户花。","园角旗亭近，东洋卖酒家。"]},{"t":"大墩公园杂咏十二首 其四","f":"五言绝句","c":["朝见东洋娘，暮见东洋娘。","看花高髻集，掠水翠裙飏。"]},{"t":"大墩公园杂咏十二首 其五","f":"五言绝句","c":["催敲来种花，千株万株列。","白是千人脂，红是万家血。"]},{"t":"大墩公园杂咏十二首 其六","f":"五言绝句","c":["海山榷酤多，游兴何须惜！","金钱不翼飞，祇此留微迹。"]},{"t":"大墩公园杂咏十二首 其七","f":"五言绝句","c":["缺堵衔山月，危樯出电星。","街衢连苑里，一线电光青。"]},{"t":"送李君雅歆观东洋博物会","f":"七言律诗","c":["冲风一棹出东溟，若木榑桑拂杳冥。","蠵贝晓浮三岛白，鱼龙夕吼万山青。","珊瑚网得同珠海，广乐张来似洞庭。","我欲与君分路去，他时慷慨上新亭！"]},{"t":"秋日即景二首","f":"七言律诗","c":["秋风飒飒路萧萧，千里津梁一线遥。","野燎明虚霜后猎，烟船暗泊港边潮。","拂云楼阁琉璃海，如砺关山铁索桥。","毕竟何人铭坐领？","西洲李特已寥寥。"]},{"t":"偶咏二首","f":"七言律诗","c":["散诞人间百不宜，空山袁鸟有新知。","欲寻泛宅浮家地，又是扬尘变海时。","谢朏口中惟饮酒，陆游梦里屡成诗。","莫将枯槁嘲贫贱，再见河清世已迟！"]},{"t":"自咏","f":"七言绝句","c":["本是人间一散仙，却曾游戏小壶天。","无端海上鳌梁断，不近蓬山过十年。"]},{"t":"见「琉球图」感作","f":"七言绝句","c":["鲸吞虎噬事长休，何日中邦系缀旒？","卅载降王无处去，烟波数点望琉球！"]},{"t":"偶书付垦荒日本人","f":"七言绝句","c":["剩水残山处处过，开阡辟陌报升科。","可怜海上蓬莱岛，割去膏腴左股多！"]},{"t":"书近日市况","f":"七言绝句","c":["寸丝粒黍随徵榷，褚币如云散海台。","一市人惊金气尽，梅根谁冶水衡来！"]},{"t":"近事三首 其一","f":"七言律诗","c":["更于何处好谋生，海外颠连莫可名！","上市鱼盐三倍价，入关虾菜百般徵。","西洋法网如蛛密，中国人曹比蚁轻。","叹息天心公道少，两间苦乐不均平！"]},{"t":"近事三首 其二","f":"七言律诗","c":["华屋邱墟一再经，此中民物日凋零。","国家食货皆机阱，官法卫生半死刑。","行部趣耕无雨泽，敲门巡警有雷霆。","鲁褒爱作钱神论，清浊何须辨渭泾！"]},{"t":"近事三首 其三","f":"七言律诗","c":["赋课刑书急似弦，可怜全岛万家烟！","屠尸抛胔寻常事，簸土扬灰苦劫年。","平地险生人瓮鲊，閒居惊拔眼钉钱。","沈酣若得中山酒，一醉还须百岁眠。"]},{"t":"屿上即景二首","f":"七言律诗","c":["骑危一望碧挣摐，沙觜涛头走怒泷。","眺海云生红土岭，看山日挂绿萝窗。","帆风鲨艇趋澎澳，驶浪乌艚上浙江。","万里汪洋空极目，天涯何处认闽邦！"]},{"t":"送浙客绝句四首 其一","f":"七言绝句","c":["蓬壶万里已曾经，水浅南溟又北溟。","何日海山携两袖，西风吹上落帆亭！"]},{"t":"送浙客绝句四首 其二","f":"七言绝句","c":["孤岛兵争似井陉，沈沦化外一周星。","沼吴报越英雄事，说与蓬莱海客听。"]},{"t":"自叹","f":"七言律诗","c":["烟涛万里接天流，身世沈沦守故邱。","每度秋风增马齿，连年寒雪敝貂裘。","乾坤文物经三变，海屋沧桑又一筹。","若使中原计恢复，儒衣愿换铁兜鍪！"]},{"t":"斋中即景","f":"七言律诗","c":["四围风月一灯悬，帐里芙蓉小洞天。","邺架书堆群玉府，皇图壁挂九州烟。","东洋髹漆西洋绣，南海玻璃北海毡。","又有巨文三万轴，自家织锦胜湖川。"]},{"t":"送许都司母出殡","f":"七言绝句","c":["故家今已等夷看，陵阜丘园墓道难。","日晚北邙山下路，蒿歌空展汉衣冠！"]},{"t":"前月诸罗斗六地方山崩川走，沿及全台，地震连月不止，再为悼赋七律","f":"七言律诗","c":["眼里山川渺一毫，飘摇大块失周遭。","惊闻五竺飞孤鹫，惨见三蹻断六鳌！","尘劫重重添黑界，陆沈日日撼神皋。","无量河畔洹沙数，人物于今有浪淘。"]},{"t":"咏盐","f":"七言绝句","c":["纷纷粒粒总归官，鹾贾休思法网宽！","海上年来谁煮雪？","堆盘真作水晶看。"]},{"t":"咏糖","f":"七言绝句","c":["糖霜出鼎当琼英，税敛重重百倍盈。","悔杀伞山邹佛子，竟熬甘汁误苍生！"]},{"t":"咏酒","f":"七言绝句","c":["一盏沾唇费十千，无人敢作醉中仙。","小家大户皆徵榷，惟有睡乡未税钱。"]},{"t":"咏烟","f":"七言绝句","c":["家家爱吸淡芭菰，今日也同禁脔呼。","空尽座中供客料，一筒檀管一胡芦。"]},{"t":"春兴","f":"七言律诗","c":["浮生阅过似云浮，策蹇行春散暮愁。","红树僧敲村寺罄，青山人倚酒家楼。","兵戈乱后无朱户，故旧相逢有白头。","悽绝园林花鸟路，东风如絮水如沤！"]},{"t":"漫与","f":"七言律诗","c":["大荒以外煽风尘，岛上星槎绝问津。","天堑早违天水赵，海东今作海西秦。","衣冠卖药朝鲜客，髡裸行歌日本人。","我自溷栖佣保里，莫将身比葛、怀民！"]},{"t":"台湾即事","f":"七言律诗","c":["风俗年来杂獶狙，市楼蜃气幻吹嘘。","半空电传催邮传，平地飞车挟火车。","硗确河山穿凿苦，角尖蛮触战争虚。","海南民力今凋尽，兵疫如何未劫除！"]},{"t":"送客归湖北不果二首 其一","f":"七言绝句","c":["西望沧波万里长，大江欲棹路茫茫。","海东无限萧疏柳，不送离愁到武昌。"]},{"t":"送客归湖北不果二首 其二","f":"七言绝句","c":["黄鹄山头底处乡，朝来将酒慰离觞。","八闽咫尺犹难渡，何况襄阳与汉阳！"]},{"t":"新学丛志馆来徵诗，为及编辑李君","f":"七言律诗","c":["学问今徵外九州，象胥蛮隶一兼收。","奇肱国送飞车至，深目人乘电驭游。","黑白黄红新族谱，亚、欧、非、美秘阳秋。","从兹刮眼看高论，陆贾潜夫在校雠。"]},{"t":"冲西即事二首 其一","f":"七言律诗","c":["西望汪洋万里遥，不堪人事日萧条。","千家鱼市归枯肆，百顷盐田壅晚潮。","关吏例苛难出海，估船税苦尽停桡。","祇应飞渡施神术，鞭石驱羊去作桥。"]},{"t":"冲西即事二首 其二","f":"七言律诗","c":["一层潮汐一层高，枯港回沙起怒涛。","鸦背夕阳空万瓦，鸭头春水断三篙。","难来闽布况吴布，岂有江艘与广艘！","从此津梁无利涉，环山蔽海更添牢。"]},{"t":"题杜友绍画梅 其一","f":"七言绝句","c":["天然高格印窗纱，墨迹淋漓瘦影斜。","忆昔骑驴山驿路，雪中三见汝开花。"]},{"t":"题杜友绍画梅 其二","f":"七言绝句","c":["孤山有梦即家乡，鹤骨虬枝雪月傍。","我比林逋疏更懒，爱君疏影当闻香。"]},{"t":"大墩晓起三首 其一","f":"七言绝句","c":["叆叇天光云气低，一钩银色月流西。","朦胧街树无人语，四野乱鸣日本鸡。"]},{"t":"大墩晓起三首 其二","f":"七言绝句","c":["败檐新廨四玲珑，断续街衢掠晓风。","洋式楼房昏似墨，乳鸦啼破月明中。"]},{"t":"大墩晓起三首 其三","f":"七言绝句","c":["认得倭居户未开，满天露显毬场埃。","旅人未觉飞车过，五夜惊雷入梦来。"]},{"t":"寄讯友人自台北城移居淡水尾","f":"七言律诗","c":["达士襟怀信不虚，江山随地是吾庐。","王维辋水临川墅，潘岳河阳背郭居。","千里琴樽千日酒，一房花木一床书。","遥知淡水兰溪上，风月烟波结比闾。"]},{"t":"日本游士索诗即赠","f":"七言律诗","c":["波急云昏大海滨，徵徭已遍武陵津。","故山人物沦欧、美，此地桑麻记晋、秦。","三岛谁登君子国？","一身独作葛天民。","赤间关路休归去，恐与时趋隔两尘！"]},{"t":"閒居偶咏二首 其一","f":"七言律诗","c":["蒿目时艰百不宜，襄阳休醉习家池。","琴高鱼长输租重，支遁鹤多困米饥。","裨海有关难泛宅，商山无路可寻芝。","闭门聊作羲皇侣，长与陶潜伴菊篱。"]},{"t":"閒居偶咏二首 其二","f":"七言律诗","c":["僻处逍遥自一时，世途不复问安危。","鹅黄蕉叶浮杯酒，鱼鳜桃花下钓丝。","白雪如山怜鬓发，苕华似水鉴须眉。","风云花月俱多事，惟有泉声和咏诗。"]},{"t":"过彰化东郭废公园感赋八首 其一","f":"七言绝句","c":["四面烟山四面风，半池亭榭尚玲珑。","当年城郭成芜苑，不见花开柳市东。"]},{"t":"过彰化东郭废公园感赋八首 其二","f":"七言绝句","c":["僵石欹斜卧藓苔，春光无主野花开。","园中惨绿高丽菜，时有穿城屐齿来。"]},{"t":"过彰化东郭废公园感赋八首 其三","f":"七言绝句","c":["风景依稀是白沙，毕逋今集海东鸦。","夕阳未觉芜城恨，春去春来照落花。"]},{"t":"过彰化东郭废公园感赋八首 其四","f":"七言绝句","c":["板屋圆穹倭式亭，无莺、无蝶有流萤。","楝花落尽枞椰老，傍郭相思树树青。"]},{"t":"过彰化东郭废公园感赋八首 其五","f":"七言绝句","c":["和草倭花莳野山，胭脂到此亦无颜。","倭娘来谱东洋曲，须唱青莲「菩萨蛮」。"]},{"t":"过彰化东郭废公园感赋八首 其六","f":"七言绝句","c":["无复看花载酒踪，三五倭人逐野蜂。","凉露不知春色尽，露珠犹洒旧枞榕。"]},{"t":"夏雨即事六首","f":"七言绝句","c":["征夫冒暑去无还，风雨如怜五岭蛮。","驿电不知能递否？","连天烽火在深山。"]},{"t":"酒市四首，同次儿作 其一","f":"七言绝句","c":["数钱奼女点牙筹，月地花天处处秋。","今日醁醽徵榷尽，襟痕无复满杭州。"]},{"t":"酒市四首，同次儿作 其二","f":"七言绝句","c":["此地当年酗狗屠，倚门武负善藏沽。","贳钱若向新丰去，再觅高阳旧醉徒。"]},{"t":"迟暮感伤","f":"七言律诗","c":["物换星移又几时，苍茫天地欲何之？","半生尝尽愁千斛，万事消除酒一卮。","荆棘欹危台北路，江山孤愤剑南诗！","桑田沧海浑无赖，苌楚虽华未有知。"]},{"t":"过狮子岭，俯视浊水溪即事","f":"七言律诗","c":["浊流、狮岭两崚嶒，铁轨风驰路几层。","冒险车从牛峡入，援高人怕虎牢登。","一溪水挟千龙去，两岸山如万马腾。","最好客程峰顶驻，乱蝉声里画眉应。"]},{"t":"厉行断发散足事感咏","f":"七言律诗","c":["是何世界任戕残，警吏施威六月寒。","削足妄思求适屦，髡头谬说庆弹冠。","时无美鬒人人鬝，家有金莲步步难。","癸女丁男颠倒甚，此间奚事不心酸！"]},{"t":"逃剪发感咏","f":"七言律诗","c":["穆生久惧楚人钳，藏尾藏头二纪淹。","发短忽惊城旦酷，令轻犹比路灰严。","山中夏馥缄须去，稷下淳于努目瞻。","匿迹时将形影问，余颅何术葆鬑鬑！"]},{"t":"再为厉行断发咏","f":"七言律诗","c":["长叹无天可避秦，中华远海总蒙尘！","本为海岛埋头客，更变伊川被发人。","愧与伍间伧父辈，错成廿载寓公身。","江湖满地供樗散，不数裈中虮虱臣。"]},{"t":"时俗尚新制感赋","f":"七言绝句","c":["倭制衣冠短发裁，喜欢生面一朝开。","岂知此是无颜帢，我辈如何戴得来！"]},{"t":"五十感伤四首 其一","f":"七言律诗","c":["身世飘飘不系舟，茫茫大海任浮游。","销磨豪气三千劫，龌龊年华五十秋。","尘界不夷兼不夏，人间呼马又呼牛。","此时荷到刘伶锸，万斛醇醪岂解忧！"]},{"t":"五十感伤四首 其二","f":"七言律诗","c":["苍天倏与人俱老，蓬岛还须恨作城。","失足儒坑长有愧，埋头蛮海总无声！","豪怀忽忽千秋去，壮泪汪汪万顷倾。","五十年光归一瞬，何图断送此浮生！"]},{"t":"将远游，在台北路作","f":"五言古诗","c":["我家傍海隅，常闻风涛作。","去山二十里，不见青山壑。","有时见山容，足已涉城郭。","此行向中华，万山将笼络。","不图台北路，群峰先崿崿。","有如赴汪洋，河伯先海若。","路出香山间，海山俱寥廓。","四水望西流，连山自东落。","山水交潆洄，红尘供插脚。","我车风雷驰，我神尻轮跃。","一出鸡笼山，一身脱尘缚。","俯仰洪渡中，天地入冥漠。"]},{"t":"过枋桥即景","f":"七言绝句","c":["北地枋桥似板桥，江村风景草迢迢。","残山剩水楼台外，金粉人家可淡描。"]},{"t":"鸡笼山遇雨，留宿颜君云年陋园","f":"五言古诗","c":["风雨四山来，山外开曙色。","潮声吼如雷，海上犹深黑。","雨止风怒号，风鸣雨淅淅。","开门望曙光，巨灯悬竿侧。","电气逼人青，林烟散天碧。","我为候船来，望之心怵惕！","赖有贤主人，珍重慰羁□。","远客夜不眠，毫光明满室。","宗悫万里风，宗炳五岳屐。","□去指顾间，虽老心未息。","投笔潮鸡啼，海山忽四白。"]},{"t":"将游中华作","f":"五言古诗","c":["将老再行迈，竟作万里游。","此意同矍铄，恨无勋业酬！","栖栖入□山，远与禽向俦。","向禽亦何易，踪迹巢、许侔。","尧、舜今已没，洪水自东流。","我为乘桴客，翻向陆中浮。","陆中诚阻艰，尚有桃源留。","沧海浅更涸，巨鱼日吞舟。","六鳌沈蓬山，一去不可求。","我欲穷天阙，安得昆崙邱！","中原轩辕都，胜迹神禹州。","乾坤虽莽莽，轨路自悠悠。","列子御风行，域外期一周！"]},{"t":"将泛海入中华作","f":"七言古诗","c":["飙轮发出东瀛东，台湾水与吴淞通。","五岳三山禽庆志，五湖四海范蠡风。","久闭岛上如樊笼，山水瑟瑟无欢悰。","有树髡比湘君赭，有石血见秦鞭红。","欲向方壶觅员峤，奈无黄平、乏赤松。","放棹沧溟游万里，此行或遇东王公。","中原今已霸图空，龙蟠虎踞空匆匆。","碧水千回留古迹，青山一发馀高踪。","我从世外追温伯，有目不送南飞鸿。","拌以双屐踏万里，一蹑岱顶登高嵩。","昂头缈缈白云峰，手撷仙人青芙蓉。","归来袖里乾坤大，游筇且化葛陂龙。"]},{"t":"南岸十馀里眺马当山，赋马当歌","f":"古风","c":["水莫如吕梁，山莫若太行。","兼二妙之山水，吾今果见诸马当。","马当峰拂高隼天，马当江蓄神龙渊。","龙腾水怒火轮?，峰峰壁立云涛连。","亘古屹立大江边，长江锁钥生寒烟。","一矶、一矶拥水圆，一落千寻地轴穿。","汹漭江流供插脚，轮菌庐阜疑并肩。","江水西来九派大，山翠东流万派外。","颇怪郦生「水经」疏，叙山不与马当会。","我闻马当山，风送王子安。","我来愿将一帆借，愧无雄词滕王高阁攀！","顺风直向鄱湖口，湖水入江山为走。","澎泽县西山色分，望见小孤犹回首。"]},{"t":"入庐山十五首 其一","f":"五言古诗","c":["背后负青山，当面对平筱。","虽盘庐山底，仍出众山表。","隐隐苍碧间，禅房出树杪。","古寺号「栖贤」，临流见幽窈。","涧水天上来，转觉瞿塘小。","苏公拟三峡，三峡谁多少！","阴沈至渊潭，神龙起昏晓。","寺前五老峰，远远闻啼鸟。","我从海上来，爱此红尘杳。","既过涧中桥，无限清浪绕。","复饮招阮泉，秋风双袂袅。"]},{"t":"入庐山十五首 其二","f":"五言古诗","c":["自入庐山来，众山纷磅礴。","日月藏岩阿，风云出丘壑。","神灵所宅都，江湖为缠络。","兹山诚南岳，可以兼衡、霍。","包孕百山川，巍峰起窕谷。","一罅一山开，各有新面目。","阴阳负两郡，岷嶓归一曲。","我行在觚弦，大千见粒粟。","晦明山中央，乾坤为局促。","欲揽山四陲，羌无巨灵足！"]},{"t":"自岳州巴江下水，破晓至武昌，望汉阳、入汉口即目","f":"楚辞体","c":["驳霞满天天色紫，五云台阁天中起。","继以海市虚无间，蜃楼复在空明里。","凌霄万汇天机悬，火布水锦风轮旋。","珊瑚玳瑁万家饰，虹栈星房九气鲜。","江光烂漫群龙戏，乃是千舟万舟至。","叆叇三湘七泽天，缤纷四海五湖地。","汉阳、武昌夹岸长，东西南北控中央。","安得江神一起鞭石梁，联络二十二省成一疆，朝轶大秦、暮扶桑！","呜呼我歌未罢开曙光，天苍苍兮江茫茫。","愿乘槎兮出大荒！"]},{"t":"过遂平县","f":"五言古诗","c":["自过信阳来，景物殊呰窳。","河南比鄂南，风土判良楛。","遂平房子国，周衰迁于楚。","中原若无人，鲸吞无所阻。","唐时平淮西，易名遂千古。","城西嵖岈山，战场今莽卤。","谁知五日间，此地复焦土！","强寇回霍邱，处处惊鼙鼓。","俯仰天地非，人民入刀俎。","呜呼十馀年，水火民何苦！"]},{"t":"下车入偃师县，游嵩山不至","f":"五言古诗","c":["北望首阳山，今有夷、齐祀。","南入偃师城，古为汤亳里。","帝喾所旧都，周王所东履。","如何同莒、邾，大无三百雉！","我向中逵行，不见繁昌市。","田横刎此乡，其地尚可指。","伊水入洛河，在此如江汜。","我欲游嵩山，城边聊徙倚。","望见太室容，忽焉风尘起。","中路多萑苻，踟蹰不能已！","风静山逾明，欲就心如矢。","闻说二室间，三十六峰里。","选胜而骋奇，峰峰天中峙。","甚喜山有灵，惜哉车无轵！","况是涉坎艰，爰作临崖止。"]},{"t":"凭吊中牟台及古吹台","f":"五言古诗","c":["袁、曹战时垒，云是中牟台。","师旷留遗迹，歌风有馀哀。","田丰祠已矣，楚氛安在哉！","我过朔风生，南风竞不来。","古邱不可见，一路见蒿莱。"]},{"t":"游大梁书院，观繁台塔","f":"五言古诗","c":["远对夷门城，近对禹王阁。","大梁书院中，浮图压东郭。","可有塔上铃，和答院中铎？","嶪嶪白云归，日暮栖鸦鹊。","师旷君子人，伊川圣者作。","列仙去不回，斯台空寄托！"]},{"t":"徐城西访燕子楼二首 其一","f":"七言绝句","c":["葳蕤锁落已千秋，当日无人燕燕愁。","被冷香消霜月夜，我来无梦亦登楼。"]},{"t":"徐城西访燕子楼二首 其二","f":"七言绝句","c":["白杨红粉久成灰，我向城西访古回。","太息岳阳鸿雁尽，楼头燕子不归来！"]},{"t":"过临城，望抱犊山","f":"五言古诗","c":["遥望抱犊山，下有豹子谷。","昔为隐者居，今聚绿林族。","山中豪客多，虎头飞食肉。","无地安渔樵，何处筹耕牧！","嗟乎平地间，长蛇常起陆。","况夫荒荒山，能无丛莽伏！","连绵有峰峦，迢递似平麓。","远视目力穷，近无镜光缩。","路与峄县通，轨辙分横幅。","北向滕、薛都，风轮去何速！"]},{"t":"姚村驿乘马车南过泗水向孔林，宿曲阜城","f":"五言古诗","c":["圣道日榛芜，孔路亦已荒。","沙尘飞蔽天，日色为昏黄。","我行八千里，来到泗水旁。","秋冬水潦降，波澜何汪洋！","想见横流世，难凘孔泽长！","宣公泗渊滥，吴师泗上翔。","此诚鲁壕堑，岂独圣津梁！","一车驱两马，浮杠百步强。","桥南见石路，桥下横野航。","跋涉崎岖中，突见万古坊。","汉柏参天地，鲁陵匹帝王。","回首鲁公台，已至鲁城隍。","信宿陋巷街，瞻见阙里墙。"]},{"t":"登泰山四首 其一","f":"五言古诗","c":["水行越沧海，陆行踰崤、函。","日夜行万里，更披万仞岚。","初上泰山北，复下泰山南。","既入岱宗坊，步步起巉岩。","登及岱盘九，峻甚华峰三。","悬峰出天际，危峪入空嵌。","忆我近嵩高，回轸向关、陕。","车行山隧中，忘却成皋险。","自入泰山来，险巘重重掩。","一险方才过，一峰又当脸。","回首视前峰，地底见一点。","迢递三天门，万山没深崦。","徘徊碧空中，白云为我敛。"]},{"t":"登泰山四首 其二","f":"五言古诗","c":["庐阜有高峰，四溃皆奇特。","灵境变幻间，一峰藏千亿。","探奇心未餍，复到泰山侧。","泰山层层高，别肇神仙域。","直上五十盘，凌霄去不息。","飞泉五千仞，山头惟一滴。","满山柏戴云，悬磴松生石。","秦、汉皆后来，云物万古积。","石闾对介邱，天府西东辟。","绝顶濛濛间，青旻连青壁。","真人御风行，去天不盈尺。","俯视山半云，雷声出山腋。","朝登日观峰，沧海扶桑色。"]},{"t":"自泰安北返济南作","f":"七言律诗","c":["汶桥高里朔风声，岱顶归来历下行。","清、济依然流泗水，泰山幸不隔长城！","争桃乃有齐三士，辞币曾无鲁二生。","游遍中原将北上，萧萧轮铁向燕京。"]},{"t":"晏城过齐河县","f":"五言绝句","c":["黄河入大清，济水失青青。","古曲传鸲鹆，西风野井亭。"]},{"t":"自青龙岭踰长城，登八达岭放歌","f":"古风","c":["阴山、祁连安在哉，我从绝顶登天台。","万骑胡儿今不见，万山叠叠东西来。","东望临榆负山海，西望恒岳飞尘埃。","太行、蓟邱挟两腋，勾注井陉如累垓。","秦皇、汉武多边才，能隔大漠寻蓬莱。","起自临洮至辽东，长城万里蒙恬开。","高齐幽州事徘徊，缮治长城下口隈。","我在岭头一俯视，荒荒莽莽红叶堆。","南下倒马关，北上飞狐口。","密云山如虎豹临，桑乾河作龙蛇走。","此岭嵯峨镇域中，插天疑有鬼神守。","岭外大野浩茫茫，岭内连山峰陡陡。","峰嶂虽逼天，陉谷若开牖，北门锁钥长在手。","呜呼谁能从军赴沙碛，南北东西此枢纽！"]},{"t":"舟泛大海作","f":"五言古诗","c":["放棹大洋中，四见沧海色。","长天入巨浸，或玄、或深黑。","江南见混黄，台麓见绿碧。","但是蹴风行，层层皆雪白。","有时浪矗空，银雪三山积。","平落洪浸间，隐隐黑龙脊。","我乘艨艟游，不畏长鲸掷。","谈笑轻波涛，昂头天咫尺。"]},{"t":"游灵隐山寺，观飞来峰、探峰洞，步各亭涧；入寺后，登北高峰；次韬光庵，观江海及及湖二十韵","f":"五言古诗","c":["环湖皆好山，最是灵隐秀。","后矗北高峰，前结飞来窦。","绕寺山水幽，巀嵲山门右。","山泉落琤琮，树根蟠透漏。","闻道云雨兴，常有雷霆斗。","涧声摇天风，瀑流出石溜。","洞中一线天，天半百层岫。","咫尺分乾坤，曲折现昏昼。","行到冷泉亭，遍看云峰皱。","入寺挹慧光，金身十丈彀。","五百护尊者，重重如列宿。","禅房云气多，经楼山岚凑。","爰登寺后山，高峰凌霄宙。","古树若飞龙，众石皆卧兽。","徘徊四山低，南峰可俯就。","复到观海亭，江海入袍袖。","此行遍江南，湖山尽停留。","此境良未逢，高奇兼秀透。","山连上天竺，岭真古灵鹫。","澹荡寺门前，湖光浮绮绣。"]},{"t":"杭郡登吴山巅，凭吊宋大内放歌","f":"古风","c":["湖东柳浪不闻莺，行行直入杭州城。","城中江水阻湖水，吴山长作越山横。","吴山下有第一泉，吴山上有第一峰。","吴山旧入宋大内，亭台苑囿今何空！","山头有石蛟龙举，山中无树凤凰处。","禁籞曾传凤凰名，校场曾集龙虎旅。","自从北兵渡淮过，钱塘潮汐竟无波。","九重云物红兜劫，一角湖山白雁歌。","越中断送宋山河，吴山犹映销金窝。","我到宋汴京，曾寻宋宫殿。","艮岳、青城虽不存，龙阶黼坐依稀见。","汴梁千载护朝门，潘、杨两湖仿畿甸。","如何此地数百年，吴山莽莽寒烟遍！","杭州况是锦绣乡，杭都运比汴都长。","当日爱看天水碧，祇今惟见夕阳黄！","此山虽不峻，襟带美江山。","钱江城南去，明湖城外环。","不须强弩射潮水，大江入海不复还。","江不还，湖不泻，我在山头望山下。","云中大笑海陵王，空画吴峰来立马！"]},{"t":"葛岭洪忠宣庙留题","f":"七言律诗","c":["忠贞气绕炼丹台，庙貌千秋葛岭开。","鹆谶鹃声无限恨，龙髯马角有馀哀！","祀同浙水、吴山永，人自冰天雪窖来。","可叹朝端苏属国，冷官亦惹桧枝猜！"]},{"t":"西湖杂咏六首 其一","f":"七言绝句","c":["灵隐寺边观海亭，南峰登后北峰登。","六桥烟柳三潭月，消受湖山得未曾？"]},{"t":"西湖杂咏六首 其二","f":"七言绝句","c":["湖上依然似画图，冬青树冷六陵芜。","孤臣长占栖霞岭，宋代湖山半亩无！"]},{"t":"西湖杂咏六首 其三","f":"七言绝句","c":["西泠桥畔带垂杨，亭子孤坟送夕阳。","虎阜真娘此苏小，苏、杭真个美人乡。"]},{"t":"过钱清江即事","f":"五言古诗","c":["夜行钱清江，月光明如昼。","顾望钱清堰，一钱谁消受！","廉吏说刘公，汉时贤太守。","一江留清名，遂觉钱塘陋。","我携杖头钱，清风亦两袖。","兼有月当头，不用一钱酎。","较公为不廉，千山万壑收。","中原山遍看，更愿浙东觏。","泛舟向会稽，江山若故旧。"]},{"t":"登会稽山，拜禹王庙；上谒禹陵，观窆亭、访菲泉；再游禹王寺、探禹穴，转出陵坊；至山庭，读岣嵝碑三十韵","f":"古风","c":["早年读「禹贡」，缅仰禹王功。","八载释玄书，四海尽来同。","稍长观史书，益慕禹王风。","万里探禹穴，愿追太史公。","不信年迟暮，始到会稽中。","会稽水渺渺，会稽山隆隆。","霈然下云雨，帝泽九州丰。","馀润及海外，岂独限浙东！","我自海上来，中原见高嵩。","曲阜拜孔子，兖州仰岱峰。","遍访九河迹，无若神禹工。","直北上燕京，飙轮出居庸。","回舟下渤海，再度入吴淞。","细考三江渎，亦为大禹通。","于兹拜禹庙，岂为骋游踪！","禹陵咸若亭，万古白云封。","石壁菲饮泉，信乎俭德崇！","窆石及古篆，卓立青芙蓉。","绕陵列云树，叠嶂若长墉。","陵下姒家村，陵右谷神宫。","泽比谷林尧冢远，不共苍梧舜冢终。","时世谈神奇，万灵来朝宗。","传说殿上梁，亦复化二龙。","庙内苍水使，河精海若从。","我再登禹寺，寺后穴濛濛。","宛委所封处，疑有藏圭琮。","尝想岣嵝碑，衡岳灵气钟。","何年陪禹硎，古字玉珑璁。","离离秦望山，斯篆邈难穷。","南巡留盛典，禹颂传九重。"]},{"t":"瑞安李茂才叔諴相遇孤山寺，酷爱余诗文集；邀游雁宕，愿为东道主。余以远游历半载，方自会稽还，未得如愿；赋此为后游之券","f":"古风","c":["浙江夙称山水窟，异境乃在温州湾。","温州有客邀我游雁宕，我魂已挂三十六峰间。","身虽未到神先往，敢笑康乐山缘悭！","或云灵峰七十七，中有天阙青云关。","我今足迹半天下，名山亦半识其颜。","其实胜处多未至，虽上会稽、未上天台山。","即今偃蹇西湖里，湖上山灵仍未一一相往还。","况乃龙湫从天下，岂易龙鼻披云观！","霞客一再寻雁湖，峰头芜草亦波澜。","灵运游踪所未发，永嘉閟奥诚难攀。","我闽尚有武夷九曲胜，安得曲曲都向眉梢攒。","放翁才到六曲止，晦庵地主空盘桓！","君为雁宕作主人，主宾应尽名山欢。","再把余诗展向雁宕看！"]},{"t":"自闽海入闽江作","f":"七言古诗","c":["海天一色云瞢腾，云开何乃见长城！","长城非城千山青，中有山门五虎横。","山门荡荡连海门，千回百折长江奔。","中流江峡成海峡，束缚蛟龙留潮痕。","潮来潮去山重叠，钱塘潮水不足论。","舟人金牌、长门里，重重锁钥江海水。","宛转亭头又馆头，罗星塔山连云起。","我自东北历东南，港门无此青巉岩。","大沽、黄浦剧深通，平原两岸蔑峰岚。","山东海港有山险，长流难得长山掩。","江心随处况有矶，岂比金、焦山两点！","堪痛甲申边衅开，如此江山酿祸胎。","兵备空传藏舰浦，洋氛竟及钓龙台！","于今江面澄如练，马头、马尾沧桑变。","不堪回首念昔游，闽中山水依稀见。"]},{"t":"游华归后偶得四首 其一","f":"七言绝句","c":["吴、越、燕、齐、楚、豫山，一时看尽好山还。","更从渤海来东海，闽峤千峰四顾间。"]},{"t":"游华归后偶得四首 其二","f":"七言绝句","c":["华夏清游剧半年，老怀负却好江天。","秦淮河上、西湖里，不唤笙歌载酒船。"]}]};